import React from "react";
import { useNavigate } from "react-router-dom";
import { Alert, Button, Card, CardBody, CardFooter, CardHeader, CardText, Col, Form, Row } from "reactstrap";

import * as adminApi from "services/adminApi";
import { useAuth } from "contexts/AuthContext";
import { useNotify } from "contexts/NotifyContext";
import FormField from "components/FormField/FormField";
import { Loading } from "components/Feedback/Feedback";
import { formatTanggal, formatTanggalWaktu } from "utils/format";
import { validasiAdmin, validasiPasswordBaru } from "utils/validasi";
import avatar from "assets/img/default-avatar.png";

function FormProfil({ admin }) {
  const { muatUlangProfilAdmin } = useAuth();
  const notify = useNotify();
  const [v, setV] = React.useState({ nama: admin.nama || "", email: admin.email || "" });
  const [errors, setErrors] = React.useState({});
  const [serverError, setServerError] = React.useState("");
  const [saving, setSaving] = React.useState(false);

  const ubah = (k) => (e) => {
    setV((x) => ({ ...x, [k]: e.target.value }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
  };

  const simpan = async (e) => {
    e.preventDefault();
    const er = validasiAdmin(v);
    setErrors(er);
    if (Object.keys(er).length) return;
    setSaving(true);
    setServerError("");
    try {
      // Backend tidak punya endpoint profil sendiri untuk ubah data; PUT /admin/akun/:id dipakai dengan id sendiri.
      await adminApi.update(admin.id_admin, { nama: v.nama.trim(), email: v.email.trim() });
      await muatUlangProfilAdmin();
      notify.sukses("Profil diperbarui.");
    } catch (err) {
      setServerError(err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <h5 className="title">Ubah profil</h5>
      </CardHeader>
      <Form onSubmit={simpan} noValidate>
        <CardBody>
          {serverError ? <Alert color="danger">{serverError}</Alert> : null}
          <Row>
            <Col md="6">
              <FormField label="Username" name="username" value={admin.username} disabled readOnly />
            </Col>
            <Col md="6">
              <FormField label="Email" name="email" type="email" value={v.email} onChange={ubah("email")} error={errors.email} />
            </Col>
          </Row>
          <FormField label="Nama" name="nama" required value={v.nama} onChange={ubah("nama")} error={errors.nama} maxLength={100} />
        </CardBody>
        <CardFooter>
          <Button color="primary" className="btn-fill" type="submit" disabled={saving}>
            {saving ? "Menyimpan..." : "Simpan"}
          </Button>
        </CardFooter>
      </Form>
    </Card>
  );
}

function FormPassword() {
  const notify = useNotify();
  const navigate = useNavigate();
  const { logoutAdmin } = useAuth();
  const awal = { lama: "", baru: "", ulang: "" };
  const [v, setV] = React.useState(awal);
  const [errors, setErrors] = React.useState({});
  const [serverError, setServerError] = React.useState("");
  const [saving, setSaving] = React.useState(false);

  const ubah = (k) => (e) => {
    setV((x) => ({ ...x, [k]: e.target.value }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
  };

  const simpan = async (e) => {
    e.preventDefault();
    const er = {};
    if (!v.lama) er.lama = "Password lama wajib diisi";
    const pw = validasiPasswordBaru(v.baru);
    if (pw) er.baru = pw;
    if (!er.baru && v.baru === v.lama) er.baru = "Password baru harus berbeda dari password lama";
    if (v.ulang !== v.baru) er.ulang = "Konfirmasi tidak sama dengan password baru";
    setErrors(er);
    if (Object.keys(er).length) return;

    setSaving(true);
    setServerError("");
    try {
      await adminApi.ubahPassword(v.lama, v.baru);
      // Backend mencabut semua sesi admin setelah password diubah → masuk kembali.
      notify.sukses("Password berhasil diubah. Silakan masuk kembali.");
      navigate("/admin/login", { replace: true });
      logoutAdmin();
    } catch (err) {
      setServerError(err.message); // mis. "Password lama salah."
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <h5 className="title">Ubah password</h5>
      </CardHeader>
      <Form onSubmit={simpan} noValidate>
        <CardBody>
          {serverError ? <Alert color="danger">{serverError}</Alert> : null}
          <FormField label="Password lama" name="lama" type="password" autoComplete="current-password" value={v.lama} onChange={ubah("lama")} error={errors.lama} />
          <Row>
            <Col md="6">
              <FormField
                label="Password baru"
                name="baru"
                type="password"
                autoComplete="new-password"
                value={v.baru}
                onChange={ubah("baru")}
                error={errors.baru}
                hint="Minimal 8 karakter, kombinasi huruf besar, huruf kecil, dan angka."
              />
            </Col>
            <Col md="6">
              <FormField label="Ulangi password baru" name="ulang" type="password" autoComplete="new-password" value={v.ulang} onChange={ubah("ulang")} error={errors.ulang} />
            </Col>
          </Row>
        </CardBody>
        <CardFooter>
          <Button color="primary" className="btn-fill" type="submit" disabled={saving}>
            {saving ? "Menyimpan..." : "Ubah password"}
          </Button>
        </CardFooter>
      </Form>
    </Card>
  );
}

function Profil() {
  const { admin } = useAuth();
  if (!admin) return <div className="content"><Loading /></div>;
  return (
    <div className="content">
      <Row>
        <Col md="8">
          {/* key: formulir di-reset bila data profil dari server berganti akun */}
          <FormProfil key={admin.id_admin} admin={admin} />
          <FormPassword />
        </Col>
        <Col md="4">
          <Card className="card-user">
            <CardBody>
              <CardText />
              <div className="author">
                <div className="block block-one" />
                <div className="block block-two" />
                <div className="block block-three" />
                <div className="block block-four" />
                <img alt="" className="avatar" src={avatar} />
                <h5 className="title">{admin.nama}</h5>
                <p className="description">@{admin.username}</p>
              </div>
              <div className="card-description">
                {admin.email || <span className="text-muted">Email belum diisi</span>}
              </div>
            </CardBody>
            <CardFooter>
              <small className="d-block text-muted">Login terakhir: {formatTanggalWaktu(admin.last_login_at)}</small>
              <small className="d-block text-muted">Akun dibuat: {formatTanggal(admin.createdAt)}</small>
            </CardFooter>
          </Card>
        </Col>
      </Row>
    </div>
  );
}

export default Profil;
