import React from "react";
import { Link } from "react-router-dom";
import { Alert, Button, Card, CardBody, Col, Row } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import ProyekBadge from "components/ProyekBadge/ProyekBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { formatTanggalWaktu } from "utils/format";

function DaftarProyek() {
  const [data, setData] = React.useState(null);
  const [error, setError] = React.useState(null);

  const muat = React.useCallback(async (signal) => {
    try {
      setData(await proyekApi.daftarSaya(signal));
      setError(null);
    } catch (err) {
      if (err.name !== "AbortError") setError(err);
    }
  }, []);
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    const t = setInterval(() => muat(ac.signal), 30000);
    return () => { ac.abort(); clearInterval(t); };
  }, [muat]);

  return (
    <>
      <h3 className="mb-1">Tugas Proyek</h3>
      <p className="text-muted">Proyek kelompok Anda. Progress dikirim per pertemuan, satu kali oleh salah satu anggota.</p>
      <ErrorBox error={error} onRetry={() => muat()} />
      {!data && !error ? <Loading /> : null}
      {data && data.proyek.length === 0 ? <Alert color="info">Anda belum tergabung di kelompok proyek mana pun. Hubungi guru/dosen pengampu.</Alert> : null}
      <Row>
        {(data?.proyek || []).map((p) => (
          <Col md="6" key={p.id_proyek}>
            <Card className="kuis-card">
              <CardBody>
                <div className="d-flex align-items-start">
                  <div className="flex-grow-1">
                    <h4 className="mb-1">{p.nama_kelompok}</h4>
                    <p className="category mb-2">{p.nama_tugas ? `${p.nama_tugas} · ` : ""}{p.nama_proyek} · Kelas {p.kelas}</p>
                  </div>
                  <ProyekBadge status={p.status} />
                </div>
                <ul className="list-unstyled small mb-3">
                  <li>{p.jumlah_anggota} anggota</li>
                  <li>Progress terkirim: <b>{p.jumlah_terkirim}/{p.jumlah_pertemuan}</b> pertemuan</li>
                  <li>Berkas/link saat ini: {p.jumlah_berkas}</li>
                  {p.status === "final" ? <li className="text-success">Final · {formatTanggalWaktu(p.final_at)} · {p.final_oleh_nama}</li> : null}
                  {p.pertemuan_terbuka.length ? <li className="text-success"><b>Pengiriman pertemuan ke-{p.pertemuan_terbuka.join(", ")} sedang dibuka</b></li> : null}
                </ul>
                <Button tag={Link} to={`/siswa/proyek/${p.id_proyek}`} color={p.pertemuan_terbuka.length ? "success" : "primary"} className={p.pertemuan_terbuka.length ? "btn-fill" : ""}>
                  {p.pertemuan_terbuka.length ? "Kirim progress" : "Buka proyek"}
                </Button>
              </CardBody>
            </Card>
          </Col>
        ))}
      </Row>
    </>
  );
}

export default DaftarProyek;
