import React from "react";
import ReactDOM from "react-dom/client";
// HashRouter: GitHub Pages tidak punya fallback SPA, jadi rute berada setelah "#" (mis. /#/siswa/kuis).
import { HashRouter, Route, Routes, Navigate } from "react-router-dom";

import AdminLayout from "layouts/Admin/Admin.js";
import SiswaLayout from "layouts/Siswa/Siswa.js";
import LoginSiswa from "views/LoginSiswa.js";
import LoginAdmin from "views/LoginAdmin.js";
import VerifikasiProyek from "views/VerifikasiProyek.js";
import BerkasPublik from "views/BerkasPublik.js";

import "assets/scss/black-dashboard-react.scss";
import "assets/demo/demo.css";
import "assets/css/nucleo-icons.css";
import "@fortawesome/fontawesome-free/css/all.min.css";
import "assets/css/app.css";

import ThemeContextWrapper from "./components/ThemeWrapper/ThemeWrapper";
import BackgroundColorWrapper from "./components/BackgroundColorWrapper/BackgroundColorWrapper";
import { AuthProvider } from "contexts/AuthContext";
import { NotifyProvider } from "contexts/NotifyContext";

const root = ReactDOM.createRoot(document.getElementById("root"));

root.render(
  <ThemeContextWrapper>
    <BackgroundColorWrapper>
      <NotifyProvider>
        <AuthProvider>
          <HashRouter>
            <Routes>
              <Route path="/login" element={<LoginSiswa />} />
              <Route path="/admin/login" element={<LoginAdmin />} />
              <Route path="/verifikasi/:kode" element={<VerifikasiProyek />} />
              <Route path="/berkas/:kode/:idb" element={<BerkasPublik />} />
              <Route path="/admin/*" element={<AdminLayout />} />
              <Route path="/siswa/*" element={<SiswaLayout />} />
              <Route path="*" element={<Navigate to="/siswa/kuis" replace />} />
            </Routes>
          </HashRouter>
        </AuthProvider>
      </NotifyProvider>
    </BackgroundColorWrapper>
  </ThemeContextWrapper>
);
