import React from "react";
import { Alert, Button, Input } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import ConfirmModal from "components/ConfirmModal/ConfirmModal";
import FormField from "components/FormField/FormField";
import { useNotify } from "contexts/NotifyContext";
import { formatUkuran } from "utils/format";

const EKSTENSI = ["doc", "docx", "ppt", "pptx"];
const ekstensiDari = (nama) => (/\.([A-Za-z0-9]{2,5})$/.exec(nama || "") || [])[1]?.toLowerCase() || "";
const linkHttps = (s) => { try { const u = new URL(s); return u.protocol === "https:" && u.hostname.includes(".") && !u.username && !u.password; } catch { return false; } };

/**
 * Form kirim progress satu pertemuan. Total file + link: minimal 1, maksimal `batas.maks_berkas`.
 * Pengiriman MENIMPA seluruh berkas/link proyek sebelumnya (ada konfirmasi bila sudah ada).
 */
function FormKirimProgress({ proyek, pertemuan, onTerkirim }) {
  const notify = useNotify();
  const { batas } = proyek;
  const [progress, setProgress] = React.useState("");
  const [files, setFiles] = React.useState([]);
  const [links, setLinks] = React.useState([""]);
  const [errs, setErrs] = React.useState({});
  const [konfirmasi, setKonfirmasi] = React.useState(false);
  const [mengirim, setMengirim] = React.useState(false);
  const inputFile = React.useRef(null);

  const linkTerisi = links.map((l) => l.trim()).filter(Boolean);
  const total = files.length + linkTerisi.length;
  const sisa = batas.maks_berkas - total;

  const pilihFile = (e) => {
    const baru = [...e.target.files];
    e.target.value = "";
    const galat = [];
    const diterima = [];
    for (const f of baru) {
      if (!EKSTENSI.includes(ekstensiDari(f.name))) { galat.push(`${f.name}: hanya .doc, .docx, .ppt, .pptx.`); continue; }
      if (f.size > batas.maks_ukuran_bytes) { galat.push(`${f.name}: melebihi ${formatUkuran(batas.maks_ukuran_bytes)}.`); continue; }
      if (files.some((x) => x.name === f.name && x.size === f.size) || diterima.some((x) => x.name === f.name && x.size === f.size)) continue;
      diterima.push(f);
    }
    const muat = Math.max(0, batas.maks_berkas - linkTerisi.length - files.length);
    if (diterima.length > muat) galat.push(`Maksimal ${batas.maks_berkas} file/link: ${diterima.length - muat} file tidak ditambahkan.`);
    setFiles((a) => [...a, ...diterima.slice(0, muat)]);
    setErrs((x) => ({ ...x, berkas: galat.join(" ") || undefined }));
  };

  const validasi = () => {
    const e = {};
    if (progress.trim().length < 3) e.progress = "Tulis progress minimal 3 karakter.";
    if (links.some((l) => l.trim() && !linkHttps(l.trim()))) e.berkas = "Link harus diawali https:// dan valid.";
    else if (new Set(linkTerisi).size !== linkTerisi.length) e.berkas = "Ada link yang sama.";
    else if (total < 1) e.berkas = "Kirim minimal 1 file atau link.";
    else if (total > batas.maks_berkas) e.berkas = `Maksimal ${batas.maks_berkas} file/link.`;
    setErrs(e);
    return Object.keys(e).length === 0;
  };

  const kirim = async () => {
    setMengirim(true);
    try {
      await proyekApi.kirim(proyek.id_proyek, pertemuan.nomor, { progress: progress.trim(), links: linkTerisi, files });
      notify.sukses(`Progress pertemuan ${pertemuan.nomor} terkirim.`);
      setKonfirmasi(false);
      onTerkirim();
    } catch (err) {
      notify.gagal(err.message);
      setKonfirmasi(false);
      onTerkirim(); // muat ulang: bisa jadi anggota lain sudah mengirim lebih dulu
    } finally {
      setMengirim(false);
    }
  };

  const submit = (ev) => {
    ev.preventDefault();
    if (!validasi()) return;
    if (proyek.berkas.length > 0) setKonfirmasi(true); else kirim();
  };

  return (
    <form onSubmit={submit} noValidate className="mt-3">
      <FormField label="Progress pertemuan ini" name={`progress-${pertemuan.nomor}`} type="textarea" rows={4} maxLength={2000} required
        value={progress} onChange={(e) => setProgress(e.target.value)} error={errs.progress}
        hint="Jelaskan apa yang sudah dikerjakan dan, bila ada, perbaikan sesuai catatan dosen." />

      <FormField label={`Berkas / link (${total}/${batas.maks_berkas})`} name={`berkas-${pertemuan.nomor}`} required error={errs.berkas}
        hint={`File .doc/.docx/.ppt/.pptx maks ${formatUkuran(batas.maks_ukuran_bytes)} per file, atau link https. Minimal 1, maksimal ${batas.maks_berkas} gabungan.`}>
        <ul className="list-unstyled mb-2">
          {files.map((f, i) => (
            <li key={`${f.name}-${f.size}`} className="d-flex align-items-center py-1">
              <i className="tim-icons icon-notes mr-2 text-info" /> <span style={{ wordBreak: "break-all" }}>{f.name}</span>
              <small className="text-muted ml-2">{formatUkuran(f.size)}</small>
              <Button type="button" color="link" size="sm" className="text-danger py-0" onClick={() => setFiles((a) => a.filter((_, j) => j !== i))}>Hapus</Button>
            </li>
          ))}
        </ul>
        <input ref={inputFile} type="file" multiple hidden accept=".doc,.docx,.ppt,.pptx" onChange={pilihFile} />
        <Button type="button" size="sm" color="info" disabled={sisa <= 0} onClick={() => inputFile.current?.click()}>+ Pilih file</Button>

        <div className="mt-3">
          {links.map((l, i) => (
            <div key={i} className="d-flex align-items-center mb-2">
              <Input placeholder="https://drive.google.com/..." value={l} onChange={(e) => setLinks((a) => a.map((x, j) => (j === i ? e.target.value : x)))} maxLength={500} />
              {links.length > 1 ? <Button type="button" color="link" size="sm" className="text-danger" onClick={() => setLinks((a) => a.filter((_, j) => j !== i))}>Hapus</Button> : null}
            </div>
          ))}
          <Button type="button" size="sm" color="info" disabled={files.length + links.length >= batas.maks_berkas} onClick={() => setLinks((a) => [...a, ""])}>+ Tambah link</Button>
        </div>
      </FormField>

      <Alert color="warning" className="py-2">
        Hanya <b>satu anggota</b> yang dapat mengirim progress pertemuan ini. Setelah terkirim, anggota lain tidak dapat mengirim lagi.
      </Alert>
      <Button type="submit" color="success" className="btn-fill" disabled={mengirim}>{mengirim ? "Mengirim..." : "Kirim progress"}</Button>

      <ConfirmModal isOpen={konfirmasi} title="Timpa berkas sebelumnya?" confirmText="Ya, kirim dan timpa" confirmColor="warning" loading={mengirim}
        onCancel={() => setKonfirmasi(false)} onConfirm={kirim}>
        Proyek ini sudah memiliki <b>{proyek.berkas.length} berkas/link</b>. Kiriman ini akan <b>menggantikan seluruhnya</b>, dan file lama dihapus permanen dari server. Teks progress pertemuan sebelumnya tetap tersimpan.
      </ConfirmModal>
    </form>
  );
}

export default FormKirimProgress;
