import { request, requestBlob, requestData } from "./api";

// Kuis, pemantauan, hasil, dan audit oleh admin.

/** GET /admin/ringkasan */
export const ringkasan = (signal) => requestData("/admin/ringkasan", { role: "admin", signal });

/** GET /admin/kuis?arsip=1 → array kuis (status dihitung server: draft|scheduled|live|finished|archived) */
export const list = ({ arsip = false } = {}, signal) =>
  requestData("/admin/kuis", { role: "admin", query: arsip ? { arsip: "1" } : undefined, signal });
/** GET /admin/kuis/:id → kuis + soal[] */
export const get = (id, signal) => requestData(`/admin/kuis/${id}`, { role: "admin", signal });
export const create = (data) => requestData("/admin/kuis", { role: "admin", method: "POST", body: data });
export const update = (id, data) => requestData(`/admin/kuis/${id}`, { role: "admin", method: "PUT", body: data });
export const remove = (id) => request(`/admin/kuis/${id}`, { role: "admin", method: "DELETE" });

const aksi = (id, nama, body = {}) =>
  requestData(`/admin/kuis/${id}/${nama}`, { role: "admin", method: "POST", body });
export const duplikasi = (id) => aksi(id, "duplikasi");
export const terbitkan = (id) => aksi(id, "terbitkan");
export const nonaktifkan = (id) => aksi(id, "nonaktifkan");
export const arsipkan = (id) => aksi(id, "arsipkan");
export const akhiri = (id, alasan) => aksi(id, "akhiri", alasan ? { alasan } : {});

/** GET /admin/kuis/:id/pantau (polling ringan) */
export const pantau = (id, signal) => requestData(`/admin/kuis/${id}/pantau`, { role: "admin", signal });

// ── Hasil (tidak tersedia untuk kuis draft → 404) ──
export const leaderboard = (id, signal) => requestData(`/admin/kuis/${id}/leaderboard`, { role: "admin", signal });
export const rincian = (id, signal) => requestData(`/admin/kuis/${id}/rincian`, { role: "admin", signal });
/** GET /admin/kuis/:id/jawaban?nomor=&hanya_pending=1 */
export const jawaban = (id, nomor, { hanyaPending = false } = {}, signal) =>
  requestData(`/admin/kuis/${id}/jawaban`, {
    role: "admin",
    query: { nomor, ...(hanyaPending ? { hanya_pending: "1" } : {}) },
    signal,
  });
/** POST /admin/kuis/:id/jawaban/:idj/review { benar, catatan } */
export const review = (id, idJawaban, benar, catatan) =>
  requestData(`/admin/kuis/${id}/jawaban/${idJawaban}/review`, {
    role: "admin",
    method: "POST",
    body: { benar, catatan },
  });
/** POST /admin/kuis/:id/koreksi { id_soal, id_siswa, nilai (0–10 | null=hapus), alasan } */
export const koreksi = (id, data) =>
  requestData(`/admin/kuis/${id}/koreksi`, { role: "admin", method: "POST", body: data });
/** GET /admin/kuis/:id/export?jenis=peringkat|rincian → Blob CSV */
export const exportCsv = (id, jenis) =>
  requestBlob(`/admin/kuis/${id}/export`, { role: "admin", query: { jenis } });

/** GET /admin/audit?id_kuis=&aksi=&page= → { log, total, page, limit } */
export const audit = (params, signal) => requestData("/admin/audit", { role: "admin", query: params, signal });
