import React from "react";
import { Link, useParams } from "react-router-dom";
import { Alert, Button, Card, CardBody, Input, Progress } from "reactstrap";
import * as pesertaApi from "services/pesertaApi";
import { ApiError, AUTH_EXPIRED_EVENT, clearToken } from "services/api";
import Waktu from "utils/waktu";
import { useNotify } from "contexts/NotifyContext";
import { urlGambar } from "config";
import { formatAngka, formatHitungMundur, formatTanggalWaktu } from "utils/format";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const uuid = () =>
  window.crypto?.randomUUID ? window.crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`;

const PESAN_KIRIM = {
  mengirim: "Mengirim jawaban…",
  terkirim: "✓ Jawaban terkirim",
  terlambat: "Waktu habis — jawaban tidak diterima.",
  ditutup: "Soal sudah ditutup.",
  gagal: "Gagal mengirim. Coba lagi.",
};

/**
 * Ruang kuis. Server = sumber kebenaran waktu & soal aktif. Klien hanya menggambar hitung mundur
 * dari batas waktu yang dikirim server (dikoreksi selisih jam), tidak pernah menentukan sendiri.
 * Koneksi: SSE (fetch streaming); bila gagal beralih ke polling snapshot (tetap benar).
 */
function RuangKuis() {
  const { id } = useParams();
  const notify = useNotify();

  const [snap, setSnap] = React.useState(null);
  const [kon, setKon] = React.useState("putus"); // sse | poll | putus
  const [fatal, setFatal] = React.useState(null);
  const [jawab, setJawab] = React.useState({ soalId: null, pilihan: null, status: "" });
  const [teksIsian, setTeksIsian] = React.useState("");
  const [hasilTerakhir, setHasilTerakhir] = React.useState(null);
  const [, setTick] = React.useState(0);

  // Penyimpanan mutabel untuk alur async (tidak memicu render ulang)
  const S = React.useRef({
    snap: null, selesai: false, polling: false, lastPoll: 0, ac: null, lastEvt: Date.now(),
    kon: "putus", jawab: { soalId: null, pilihan: null, status: "" }, kunci: null, hidup: true,
  });

  const ubahJawab = React.useCallback((patch) => {
    S.current.jawab = { ...S.current.jawab, ...patch };
    setJawab(S.current.jawab);
  }, []);
  const ubahKon = React.useCallback((k) => {
    S.current.kon = k;
    setKon(k);
  }, []);

  const sisaMs = () => {
    const a = S.current.snap?.soal_aktif;
    return a ? a.batas_ms - Waktu.now() : 0;
  };

  // ── menerapkan snapshot dari server ──
  const terapkan = React.useCallback(
    (s) => {
      Waktu.dariSnapshot(s.server_now);
      const baruId = s.soal_aktif?.soal?.id_soal || null;
      const ganti = baruId !== S.current.jawab.soalId;
      S.current.snap = s;
      setSnap(s);
      if (ganti) {
        S.current.kunci = null;
        setTeksIsian("");
        ubahJawab({ soalId: baruId, pilihan: null, status: "" });
      }
      if (s.hasil_sebelumnya) setHasilTerakhir(s.hasil_sebelumnya);
      const js = s.jawaban_saya;
      if (js && js.id_soal === baruId && !S.current.jawab.pilihan) {
        ubahJawab({ soalId: baruId, pilihan: js.id_opsi || js.teks, status: "terkirim" });
        if (js.teks) setTeksIsian(js.teks);
      }
      if (s.kuis.status === "finished") {
        S.current.selesai = true;
        S.current.ac?.abort();
      }
    },
    [ubahJawab]
  );

  const akibatFatal = React.useCallback((e) => {
    // Sesi berakhir ditangani layout (AUTH_EXPIRED → ke login). Selain itu 401/403/404 = tidak bisa lanjut.
    if (e && [401, 403, 404].includes(e.status)) {
      S.current.selesai = true;
      S.current.ac?.abort();
      setFatal(e);
    }
  }, []);

  const poll = React.useCallback(async () => {
    const st = S.current;
    if (st.polling || st.selesai) return;
    st.polling = true;
    st.lastPoll = Date.now();
    try {
      const s = await pesertaApi.snapshot(id);
      if (!st.hidup) return;
      terapkan(s);
      if (st.kon === "putus") ubahKon("poll");
    } catch (e) {
      akibatFatal(e);
    } finally {
      st.polling = false;
    }
  }, [id, terapkan, ubahKon, akibatFatal]);

  const onEvent = React.useCallback(
    (nama, d) => {
      const st = S.current;
      st.lastEvt = Date.now();
      if (nama === "snapshot") {
        ubahKon("sse");
        terapkan(d);
      } else if (nama === "hasil") {
        setHasilTerakhir(d);
      } else if (nama === "selesai") {
        st.selesai = true;
        if (st.snap) {
          const akhir = { ...st.snap, kuis: { ...st.snap.kuis, status: "finished" }, soal_aktif: null };
          st.snap = akhir;
          setSnap(akhir);
        }
      } else if (nama === "sesi_berakhir") {
        st.selesai = true;
        notify.gagal(d?.alasan || "Sesi berakhir. Silakan masuk lagi.");
        // Server mencabut sesi: picu alur keluar yang sama dengan sesi kedaluwarsa.
        clearToken("siswa");
        window.dispatchEvent(new CustomEvent(AUTH_EXPIRED_EVENT, { detail: { role: "siswa" } }));
      }
    },
    [terapkan, ubahKon, notify]
  );

  const hubung = React.useCallback(async () => {
    const st = S.current;
    let gagal = 0;
    while (!st.selesai && st.hidup) {
      st.ac = new AbortController();
      st.lastEvt = Date.now();
      try {
        await pesertaApi.alirStream(id, { signal: st.ac.signal, onEvent });
        gagal = 0;
      } catch (e) {
        akibatFatal(e);
        gagal++;
      }
      if (st.selesai || !st.hidup) return;
      ubahKon("poll");
      await poll();
      await sleep(Math.min(500 * (gagal + 1), 3000));
    }
  }, [id, onEvent, poll, ubahKon, akibatFatal]);

  // ── mengirim jawaban (idempoten: kunci sama dipakai saat retry jaringan) ──
  const kirim = async (payload) => {
    const st = S.current;
    const a = st.snap?.soal_aktif;
    if (!a || ["mengirim", "terkirim"].includes(st.jawab.status) || sisaMs() <= 0) return;
    const idSoal = a.soal.id_soal;
    const batas = a.batas_ms;
    st.kunci = st.kunci || uuid();
    ubahJawab({ status: "mengirim" });
    for (;;) {
      try {
        await pesertaApi.jawab(id, { id_soal: idSoal, ...payload, kunci_idempoten: st.kunci });
        if (st.jawab.soalId === idSoal) ubahJawab({ status: "terkirim" });
        break;
      } catch (e) {
        if (st.jawab.soalId !== idSoal) return; // sudah pindah soal
        if (e instanceof ApiError && e.status === 0 && Waktu.now() < batas) {
          await sleep(250); // jaringan putus sesaat: coba lagi selama jendela masih terbuka
          continue;
        }
        if (e.code === "JAWABAN_SUDAH_ADA") ubahJawab({ status: "terkirim" });
        else if (e.code === "JAWABAN_TERLAMBAT" || e.code === "SOAL_DITUTUP") ubahJawab({ status: "terlambat" });
        else if (e.code === "KUIS_SELESAI") ubahJawab({ status: "ditutup" });
        else {
          st.kunci = null;
          ubahJawab({ status: "gagal", pilihan: null });
          notify.gagal(e.message);
        }
        break;
      }
    }
  };
  const pilih = (idOpsi) => {
    if (S.current.jawab.pilihan || sisaMs() <= 0) return;
    ubahJawab({ pilihan: idOpsi });
    kirim({ id_opsi: idOpsi });
  };
  const kirimIsian = () => {
    const t = teksIsian.trim();
    if (!t || S.current.jawab.pilihan || sisaMs() <= 0) return;
    ubahJawab({ pilihan: t });
    kirim({ teks: t });
  };

  // ── siklus hidup: sinkron jam → snapshot → SSE; tick 100 ms hanya untuk menggambar timer ──
  React.useEffect(() => {
    const st = S.current;
    st.hidup = true;
    st.selesai = false;
    const timers = [];

    timers.push(
      setInterval(() => {
        setTick((t) => (t + 1) % 1e9);
        const s = st.snap;
        if (!s || st.selesai || st.polling || Date.now() - st.lastPoll < 700) return;
        // Jaga-jaga bila push terlambat: tanya server bila batas waktu sudah lewat.
        if (s.kuis.status === "scheduled" && Waktu.now() >= s.kuis.mulai_at) poll();
        else if (s.kuis.status === "live" && s.soal_aktif && s.soal_aktif.batas_ms - Waktu.now() < -1200) poll();
      }, 100)
    );
    // Watchdog: server mengirim heartbeat tiap 5 dtk; senyap >12 dtk → anggap putus & sambung ulang.
    timers.push(
      setInterval(() => {
        if (st.kon === "sse" && !st.selesai && Date.now() - st.lastEvt > 12000 && st.ac) {
          ubahKon("putus");
          st.ac.abort();
        }
      }, 3000)
    );
    const onOnline = () => !st.selesai && st.ac && st.ac.abort();
    const onVisible = () => !document.hidden && !st.selesai && poll();
    window.addEventListener("online", onOnline);
    document.addEventListener("visibilitychange", onVisible);

    (async () => {
      await Waktu.sinkron(4);
      if (!st.hidup) return;
      poll();
      hubung();
    })();
    timers.push(setInterval(() => Waktu.sinkron(2), 60000));

    return () => {
      st.hidup = false;
      st.selesai = true;
      st.ac?.abort();
      timers.forEach(clearInterval);
      window.removeEventListener("online", onOnline);
      document.removeEventListener("visibilitychange", onVisible);
    };
  }, [id, poll, hubung, ubahKon]);

  // ── tampilan ──
  const indikator = (
    <span className="text-muted small" role="status">
      <span className={`kon-dot ${kon === "sse" ? "on" : kon === "poll" ? "poll" : ""}`} />
      {kon === "sse" ? "Tersambung" : kon === "poll" ? "Mode cadangan" : "Terputus — mencoba lagi…"}
    </span>
  );

  const header = (
    <div className="d-flex align-items-center mb-3">
      <h3 className="mb-0 flex-grow-1">{snap?.kuis.judul || "Memuat…"}</h3>
      {indikator}
      <Button tag={Link} to="/siswa/kuis" size="sm" color="secondary" className="ml-3">
        Daftar kuis
      </Button>
    </div>
  );

  if (fatal) {
    return (
      <>
        {header}
        <Alert color="danger" role="alert">{fatal.message}</Alert>
        <Button tag={Link} to="/siswa/kuis" color="primary">Kembali ke daftar kuis</Button>
      </>
    );
  }
  if (!snap) {
    return (
      <>
        {header}
        <Card><CardBody className="text-center text-muted py-5">Menyambung ke ruang kuis…</CardBody></Card>
      </>
    );
  }

  const status = snap.kuis.status;
  const a = snap.soal_aktif;
  const s = a?.soal;
  const sisa = a ? a.batas_ms - Waktu.now() : 0;
  const habis = sisa <= 0;
  const terkunciInput = (!!jawab.pilihan && jawab.status !== "") || habis;
  const pct = a ? Math.max(0, Math.min(100, (sisa / snap.kuis.durasi_soal_ms) * 100)) : 0;

  const umpanBalik = hasilTerakhir ? (
    <p className="text-muted mt-3 mb-0">
      Soal {hasilTerakhir.nomor}:{" "}
      {hasilTerakhir.dijawab
        ? hasilTerakhir.benar === null ? "menunggu pemeriksaan" : hasilTerakhir.benar ? "benar ✓" : "salah ✗"
        : "tidak dijawab"}
      {hasilTerakhir.benar !== null || !hasilTerakhir.dijawab ? ` · nilai ${formatAngka(hasilTerakhir.nilai)}` : ""}
      {hasilTerakhir.status === "sementara" ? " (sementara)" : ""}
    </p>
  ) : null;

  let isi;
  if (status === "scheduled") {
    const sisaMulai = snap.kuis.mulai_at - Waktu.now();
    isi = (
      <Card>
        <CardBody className="text-center py-5">
          <p className="text-muted">Kuis dimulai pada {formatTanggalWaktu(snap.kuis.mulai_at)}</p>
          <div className="kuis-besar">{formatHitungMundur(sisaMulai)}</div>
          <p className="text-muted mb-0">Tetap di halaman ini. Soal pertama muncul otomatis saat waktunya tiba.</p>
        </CardBody>
      </Card>
    );
  } else if (status === "live" && s) {
    isi = (
      <Card>
        <CardBody>
          <div className="d-flex align-items-start mb-2">
            <div className="flex-grow-1">
              <div className="text-muted">Soal {a.nomor} dari {a.total}</div>
              <Progress value={(a.nomor / a.total) * 100} className="kuis-progres-kecil mt-1" color="info" />
            </div>
            <div className={`kuis-timer ${sisa < 1500 ? "rendah" : ""}`} aria-hidden="true">
              {Math.max(0, sisa / 1000).toFixed(1)}
            </div>
          </div>
          <Progress value={pct} color={sisa < 1500 ? "danger" : "primary"} className="mb-3" />
          {snap.partisipasi?.bergabung && snap.partisipasi.bergabung_di_nomor > 1 ? (
            <p className="small text-muted">Anda bergabung mulai soal nomor {snap.partisipasi.bergabung_di_nomor}.</p>
          ) : null}
          <p className="kuis-teks-soal">{s.teks}</p>
          {s.gambar ? <img className="kuis-gambar" src={urlGambar(s.gambar)} alt="Gambar pendukung soal" /> : null}

          {s.tipe === "pilihan_ganda" ? (
            <div role="group" aria-label="Pilihan jawaban">
              {s.opsi.map((o, i) => (
                <button
                  key={o.id_opsi}
                  type="button"
                  className={`kuis-opsi ${jawab.pilihan === o.id_opsi ? "sel" : ""}`}
                  aria-pressed={jawab.pilihan === o.id_opsi}
                  disabled={terkunciInput}
                  onClick={() => pilih(o.id_opsi)}
                >
                  <b>{String.fromCharCode(65 + i)}.</b> {o.teks}
                </button>
              ))}
            </div>
          ) : (
            <div className="d-flex">
              <Input
                type="text"
                maxLength={500}
                autoComplete="off"
                autoFocus
                aria-label="Jawaban Anda"
                placeholder="Ketik jawaban lalu tekan Enter"
                value={teksIsian}
                disabled={terkunciInput}
                onChange={(e) => setTeksIsian(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && kirimIsian()}
              />
              <Button color="primary" className="ml-2" disabled={terkunciInput || !teksIsian.trim()} onClick={kirimIsian}>
                Kirim
              </Button>
            </div>
          )}
          <div className="text-muted mt-3" style={{ minHeight: "1.6em" }} role="status" aria-live="polite">
            {PESAN_KIRIM[jawab.status] || (habis ? "Waktu habis." : "")}
          </div>
          {umpanBalik}
        </CardBody>
      </Card>
    );
  } else if (status === "finished") {
    const bolehHasil = snap.kuis.publikasi_hasil !== "disembunyikan";
    isi = (
      <Card>
        <CardBody className="text-center py-5">
          <h2>Kuis selesai 🎉</h2>
          {umpanBalik}
          <p className="text-muted">
            {bolehHasil ? "Terima kasih sudah mengikuti." : "Hasil tidak dipublikasikan oleh admin."}
          </p>
          {bolehHasil ? (
            <Button tag={Link} to={`/siswa/kuis/${id}/hasil`} color="primary" className="btn-fill mr-2">
              Lihat hasil
            </Button>
          ) : null}
          <Button tag={Link} to="/siswa/kuis" color="secondary">Kembali</Button>
        </CardBody>
      </Card>
    );
  } else {
    isi = <Card><CardBody>Kuis tidak tersedia.</CardBody></Card>;
  }

  return (
    <>
      {header}
      {isi}
    </>
  );
}

export default RuangKuis;
