import React from "react";
import { Badge } from "reactstrap";
import { STATUS_KUIS } from "utils/format";

/** Lencana status kuis (draft | scheduled | live | finished | archived). */
function StatusBadge({ status, className = "" }) {
  const meta = STATUS_KUIS[status] || { label: status || "-", color: "info" };
  return (
    <Badge color={meta.color} className={className} pill>
      {meta.label}
    </Badge>
  );
}

export default StatusBadge;
