import React from "react";
import {
  Alert, Badge, Button, Card, CardBody, CardHeader, CardTitle, Col, FormGroup, Input, Label,
  Modal, ModalBody, ModalFooter, ModalHeader, Row, Table,
} from "reactstrap";

import * as adminApi from "services/adminApi";
import { useAuth } from "contexts/AuthContext";
import { useNotify } from "contexts/NotifyContext";
import ConfirmModal from "components/ConfirmModal/ConfirmModal";
import FormField from "components/FormField/FormField";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { formatTanggalWaktu } from "utils/format";
import { validasiAdmin } from "utils/validasi";

const FORM_BARU = { nama: "", username: "", email: "", password: "", is_aktif: true };

/** Dialog tambah (buat=true) / ubah admin. Backend hanya menerima nama, email, is_aktif saat ubah. */
function AdminModal({ awal, buat, adalahDiriSendiri, onClose, onSaved }) {
  const notify = useNotify();
  const [v, setV] = React.useState(awal);
  const [errors, setErrors] = React.useState({});
  const [serverError, setServerError] = React.useState("");
  const [saving, setSaving] = React.useState(false);

  const ubah = (k) => (e) => {
    setV((x) => ({ ...x, [k]: e.target.value }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
  };

  const simpan = async (e) => {
    e.preventDefault();
    const er = validasiAdmin(v, { buat });
    setErrors(er);
    if (Object.keys(er).length) return;
    setSaving(true);
    setServerError("");
    try {
      const hasil = buat
        ? await adminApi.create({
            nama: v.nama.trim(),
            username: v.username.trim().toLowerCase(),
            email: v.email.trim(),
            password: v.password,
          })
        : await adminApi.update(awal.id_admin, {
            nama: v.nama.trim(),
            email: v.email.trim(),
            is_aktif: v.is_aktif,
          });
      notify.sukses(buat ? "Admin berhasil dibuat." : "Admin berhasil diperbarui.");
      onSaved(hasil);
    } catch (err) {
      setServerError(err.message);
      setSaving(false);
    }
  };

  return (
    <Modal isOpen toggle={saving ? undefined : onClose} centered>
      <form onSubmit={simpan} noValidate>
        <ModalHeader toggle={saving ? undefined : onClose}>{buat ? "Tambah admin" : "Ubah admin"}</ModalHeader>
        <ModalBody>
          {serverError ? <Alert color="danger">{serverError}</Alert> : null}
          <FormField label="Nama" name="nama" required value={v.nama} onChange={ubah("nama")} error={errors.nama} maxLength={100} />
          {buat ? (
            <FormField
              label="Username"
              name="username"
              required
              autoCapitalize="none"
              autoComplete="off"
              value={v.username}
              onChange={ubah("username")}
              error={errors.username}
              hint="Huruf kecil, angka, titik, underscore, strip. Tidak bisa diubah setelah dibuat."
              maxLength={50}
            />
          ) : (
            <FormField label="Username" name="username" value={awal.username} disabled readOnly />
          )}
          <FormField label="Email" name="email" type="email" value={v.email} onChange={ubah("email")} error={errors.email} />
          {buat ? (
            <FormField
              label="Password"
              name="password"
              type="password"
              required
              autoComplete="new-password"
              value={v.password}
              onChange={ubah("password")}
              error={errors.password}
              hint="Minimal 8 karakter, kombinasi huruf besar, huruf kecil, dan angka."
            />
          ) : (
            <FormGroup check className="mt-3">
              <Label check>
                <Input
                  type="checkbox"
                  checked={v.is_aktif}
                  disabled={adalahDiriSendiri}
                  onChange={(e) => setV((x) => ({ ...x, is_aktif: e.target.checked }))}
                />
                <span className="form-check-sign"><span className="check" /></span>
                Akun aktif{adalahDiriSendiri ? " (tidak bisa menonaktifkan akun sendiri)" : ""}
              </Label>
            </FormGroup>
          )}
        </ModalBody>
        <ModalFooter>
          <Button type="button" color="secondary" onClick={onClose} disabled={saving}>Batal</Button>
          <Button type="submit" color="primary" className="btn-fill" disabled={saving}>
            {saving ? "Menyimpan..." : "Simpan"}
          </Button>
        </ModalFooter>
      </form>
    </Modal>
  );
}

function Pengguna() {
  const { admin: saya } = useAuth();
  const notify = useNotify();
  const [rows, setRows] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);
  const [modal, setModal] = React.useState(null); // { buat: bool, awal: {...} }
  const [hapus, setHapus] = React.useState(null);
  const [menghapus, setMenghapus] = React.useState(false);

  const muat = React.useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      setRows(await adminApi.list());
    } catch (err) {
      setError(err);
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    muat();
  }, [muat]);

  const konfirmasiHapus = async () => {
    setMenghapus(true);
    try {
      await adminApi.remove(hapus.id_admin);
      notify.sukses(`Admin "${hapus.nama}" dihapus.`);
      setHapus(null);
      muat();
    } catch (err) {
      notify.gagal(err.message);
    } finally {
      setMenghapus(false);
    }
  };

  return (
    <div className="content">
      <Row>
        <Col xs="12">
          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col>
                  <CardTitle tag="h4" className="mb-0">Kelola Admin</CardTitle>
                  <p className="category mb-0">Akun yang dapat masuk ke dashboard ini</p>
                </Col>
                <Col xs="auto">
                  <Button color="primary" className="btn-fill" onClick={() => setModal({ buat: true, awal: FORM_BARU })}>
                    <i className="tim-icons icon-simple-add" /> Tambah admin
                  </Button>
                </Col>
              </Row>
            </CardHeader>
            <CardBody>
              <ErrorBox error={error} onRetry={muat} />
              {loading && rows.length === 0 ? (
                <Loading />
              ) : (
                <Table responsive>
                  <thead className="text-primary">
                    <tr>
                      <th>Nama</th>
                      <th>Username</th>
                      <th>Email</th>
                      <th>Status</th>
                      <th>Login terakhir</th>
                      <th className="aksi">Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((a) => {
                      const diriSendiri = a.id_admin === saya?.id_admin;
                      return (
                        <tr key={a.id_admin}>
                          <td>
                            {a.nama}
                            {diriSendiri ? <Badge color="info" className="ml-2">Anda</Badge> : null}
                          </td>
                          <td>{a.username}</td>
                          <td>{a.email || <span className="text-muted">-</span>}</td>
                          <td>
                            <Badge color={a.is_aktif ? "success" : "danger"} pill>
                              {a.is_aktif ? "Aktif" : "Nonaktif"}
                            </Badge>
                          </td>
                          <td>{a.last_login_at ? formatTanggalWaktu(a.last_login_at) : <span className="text-muted">Belum pernah</span>}</td>
                          <td className="aksi">
                            <Button
                              color="warning"
                              size="sm"
                              className="btn-link btn-icon"
                              title="Ubah"
                              onClick={() =>
                                setModal({
                                  buat: false,
                                  awal: { id_admin: a.id_admin, nama: a.nama, username: a.username, email: a.email || "", password: "", is_aktif: a.is_aktif },
                                })
                              }
                            >
                              <i className="tim-icons icon-pencil" />
                            </Button>
                            <Button
                              color="danger"
                              size="sm"
                              className="btn-link btn-icon"
                              title={diriSendiri ? "Tidak bisa menghapus akun yang sedang dipakai" : "Hapus"}
                              disabled={diriSendiri}
                              onClick={() => setHapus(a)}
                            >
                              <i className="tim-icons icon-trash-simple" />
                            </Button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </Table>
              )}
            </CardBody>
          </Card>
        </Col>
      </Row>

      {modal ? (
        <AdminModal
          awal={modal.awal}
          buat={modal.buat}
          adalahDiriSendiri={!!saya && modal.awal.id_admin === saya.id_admin}
          onClose={() => setModal(null)}
          onSaved={() => {
            setModal(null);
            muat();
          }}
        />
      ) : null}

      <ConfirmModal
        isOpen={!!hapus}
        title="Hapus admin?"
        confirmText="Ya, hapus"
        loading={menghapus}
        onConfirm={konfirmasiHapus}
        onCancel={() => setHapus(null)}
      >
        Akun <b>{hapus?.nama}</b> ({hapus?.username}) akan dihapus permanen dan tidak bisa login lagi.
      </ConfirmModal>
    </div>
  );
}

export default Pengguna;
