const LIMIT = 50;
const FORM_BARU = { nim: "", nama: "", kelas: "", pin: "", is_aktif: true };

/** Menampilkan PIN SEKALI (backend tidak menyimpan PIN asli; hanya hash). */
function PinModal({ judul, nim, nama, pin, onClose }) {
  const notify = useNotify();
  const salin = async () => {
    try {
      await navigator.clipboard.writeText(pin);
      notify.sukses("PIN disalin.");
    } catch {
      notify.gagal("Tidak bisa menyalin otomatis; salin manual.");
    }
  };
  return (
    <Modal isOpen toggle={onClose} centered>
      <ModalHeader toggle={onClose}>{judul}</ModalHeader>
      <ModalBody>
        <Alert color="warning">Catat PIN ini sekarang — <b>tidak akan ditampilkan lagi</b>.</Alert>
        <p className="mb-1">{nama} <span className="text-muted">({nim})</span></p>
        <div className="pin-box">{pin}</div>
      </ModalBody>
      <ModalFooter>
        <Button color="secondary" onClick={salin}>Salin PIN</Button>
        <Button color="primary" className="btn-fill" onClick={onClose}>Sudah saya catat</Button>
      </ModalFooter>
    </Modal>
  );
}

/** Dialog tambah (buat=true) / ubah siswa. Saat ubah backend hanya menerima nama, kelas, is_aktif. */
function SiswaModal({ awal, buat, daftarKelas, onClose, onSaved }) {
  const notify = useNotify();
  const [v, setV] = React.useState(awal);
  const [errors, setErrors] = React.useState({});
  const [serverError, setServerError] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const ubah = (k) => (e) => {
    setV((x) => ({ ...x, [k]: e.target.value }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
  };
  const simpan = async (e) => {
    e.preventDefault();
    const er = validasiSiswa(v, { buat });
    setErrors(er);
    if (Object.keys(er).length) return;
    setSaving(true);
    setServerError("");
    try {
      if (buat) {
        const hasil = await siswaApi.create({
          nim: v.nim.trim(), nama: v.nama.trim(), kelas: v.kelas.trim(), ...(v.pin.trim() ? { pin: v.pin.trim() } : {}),
        });
        notify.sukses("Siswa ditambahkan.");
        onSaved(hasil); // hasil.pin_awal → ditampilkan lewat PinModal
      } else {
        await siswaApi.update(awal.id_siswa, { nama: v.nama.trim(), kelas: v.kelas.trim(), is_aktif: v.is_aktif });
        notify.sukses("Siswa diperbarui.");
        onSaved(null);
      }
    } catch (err) {
      setServerError(err.message);
      setSaving(false);
    }
  };
  return (
    <Modal isOpen toggle={saving ? undefined : onClose} centered>
      <form onSubmit={simpan} noValidate>
        <ModalHeader toggle={saving ? undefined : onClose}>{buat ? "Tambah siswa" : "Ubah siswa"}</ModalHeader>
        <ModalBody>
          {serverError ? <Alert color="danger">{serverError}</Alert> : null}
          {buat ? (
            <FormField label="NIM" name="nim" required autoComplete="off" value={v.nim} onChange={ubah("nim")} error={errors.nim}
              hint="3–30 karakter (huruf, angka, titik, strip, underscore). Tidak bisa diubah setelah dibuat." maxLength={30} />
          ) : (
            <FormField label="NIM" name="nim" value={awal.nim} disabled readOnly />
          )}
          <FormField label="Nama" name="nama" required value={v.nama} onChange={ubah("nama")} error={errors.nama} maxLength={100} />
          <FormField label="Kelas" name="kelas" required list="daftar-kelas" value={v.kelas} onChange={ubah("kelas")} error={errors.kelas}
            hint="Wajib. Kuis dipilih per kelas, jadi tulis konsisten (mis. XII-IPA-1)." maxLength={50} />
          <datalist id="daftar-kelas">
            {daftarKelas.map((k) => <option key={k} value={k} />)}
          </datalist>
          {buat ? (
            <FormField label="PIN (opsional)" name="pin" inputMode="numeric" autoComplete="off" value={v.pin} onChange={ubah("pin")}
              error={errors.pin} hint="4–12 digit angka. Kosongkan agar dibuat acak 6 digit." maxLength={12} />
          ) : (
            <FormGroup check className="mt-3">
              <Label check>
                <Input type="checkbox" checked={v.is_aktif} onChange={(e) => setV((x) => ({ ...x, is_aktif: e.target.checked }))} />
                <span className="form-check-sign"><span className="check" /></span>
                Akun aktif <small className="text-muted">(menonaktifkan langsung mengeluarkan siswa yang sedang login)</small>
              </Label>
            </FormGroup>
          )}
        </ModalBody>
        <ModalFooter>
          <Button type="button" color="secondary" onClick={onClose} disabled={saving}>Batal</Button>
          <Button type="submit" color="primary" className="btn-fill" disabled={saving}>{saving ? "Menyimpan..." : "Simpan"}</Button>
        </ModalFooter>
      </form>
    </Modal>
  );
}

/** Reset PIN: kosongkan untuk PIN acak. Semua sesi siswa itu dicabut oleh backend. */
function ResetPinModal({ siswa, onClose, onDone }) {
  const [pin, setPin] = React.useState("");
  const [error, setError] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const kirim = async (e) => {
    e.preventDefault();
    const m = validasiPin(pin);
    if (m) return setError(m);
    setSaving(true);
    setError("");
    try {
      onDone(await siswaApi.resetPin(siswa.id_siswa, pin.trim()));
    } catch (err) {
      setError(err.message);
      setSaving(false);
    }
  };
  return (
    <Modal isOpen toggle={saving ? undefined : onClose} centered>
      <form onSubmit={kirim} noValidate>
        <ModalHeader toggle={saving ? undefined : onClose}>Reset PIN</ModalHeader>
        <ModalBody>
          {error ? <Alert color="danger">{error}</Alert> : null}
          <p>PIN <b>{siswa.nama}</b> ({siswa.nim}) akan diganti dan sesi loginnya dicabut.</p>
          <FormField label="PIN baru (opsional)" name="pin" inputMode="numeric" autoComplete="off" value={pin}
            onChange={(e) => setPin(e.target.value)} hint="4–12 digit angka. Kosongkan agar dibuat acak 6 digit." maxLength={12} />
        </ModalBody>
        <ModalFooter>
          <Button type="button" color="secondary" onClick={onClose} disabled={saving}>Batal</Button>
          <Button type="submit" color="warning" disabled={saving}>{saving ? "Memproses..." : "Reset PIN"}</Button>
        </ModalFooter>
      </form>
    </Modal>
  );
}

const ALIAS = { nim: ["nim", "nis", "id"], nama: ["nama", "name"], kelas: ["kelas", "class"], pin: ["pin"] };

/** Baca CSV → baris { nim, nama, kelas, pin? }. Baris pertama = header (nim, nama, kelas, pin opsional). */
function bacaCsvSiswa(teks) {
  const rows = parseCsv(teks);
  if (rows.length < 2) throw new Error("File kosong atau hanya berisi header.");
  const head = rows[0].map((h) => h.trim().toLowerCase());
  const idx = {};
  for (const [k, alias] of Object.entries(ALIAS)) idx[k] = head.findIndex((h) => alias.includes(h));
  const hilang = ["nim", "nama", "kelas"].filter((k) => idx[k] < 0);
  if (hilang.length) throw new Error(`Kolom wajib tidak ditemukan di baris pertama: ${hilang.join(", ")}.`);
  return rows.slice(1).map((r) => ({
    nim: (r[idx.nim] || "").trim(), nama: (r[idx.nama] || "").trim(), kelas: (r[idx.kelas] || "").trim(),
    ...(idx.pin >= 0 && (r[idx.pin] || "").trim() ? { pin: r[idx.pin].trim() } : {}),
  }));
}

/** Impor massal: dipecah per 200 baris (batas backend) dan hasilnya digabung. */
function ImporModal({ onClose, onSelesai }) {
  const [baris, setBaris] = React.useState(null);
  const [namaFile, setNamaFile] = React.useState("");
  const [error, setError] = React.useState("");
  const [proses, setProses] = React.useState(null); // { selesai, total }
  const [hasil, setHasil] = React.useState(null); // { berhasil, gagal }

  const pilihFile = async (e) => {
    const f = e.target.files?.[0];
    setHasil(null);
    setError("");
    if (!f) return setBaris(null);
    try {
      setBaris(bacaCsvSiswa(await f.text()));
      setNamaFile(f.name);
    } catch (err) {
      setBaris(null);
      setError(err.message);
    }
  };

  const jalankan = async () => {
    setError("");
    const berhasil = [];
    const gagal = [];
    setProses({ selesai: 0, total: baris.length });
    try {
      for (let i = 0; i < baris.length; i += 200) {
        const r = await siswaApi.importMassal(baris.slice(i, i + 200));
        berhasil.push(...r.berhasil);
        gagal.push(...r.gagal.map((g) => ({ ...g, baris: g.baris + i })));
        setProses({ selesai: Math.min(i + 200, baris.length), total: baris.length });
      }
    } catch (err) {
      // Batch sebelumnya sudah tersimpan; tampilkan apa yang berhasil agar PIN-nya tidak hilang.
      setError(`Impor berhenti: ${err.message} Siswa yang sudah berhasil ditambahkan tetap tersimpan.`);
    }
    setProses(null);
    setHasil({ berhasil, gagal });
    if (berhasil.length) onSelesai();
  };

  const unduhPin = () =>
    unduhTeks(
      tulisCsv(["nim", "nama", "kelas", "pin"], hasil.berhasil.map((b) => [b.nim, b.nama, b.kelas, b.pin_awal])),
      "daftar-pin-siswa.csv"
    );

  return (
    <Modal isOpen toggle={proses ? undefined : onClose} centered size="lg">
      <ModalHeader toggle={proses ? undefined : onClose}>Impor siswa dari CSV</ModalHeader>
      <ModalBody>
        {error ? <Alert color="danger">{error}</Alert> : null}
        {!hasil ? (
          <>
            <p>
              Baris pertama adalah header: <code>nim, nama, kelas</code> dan opsional <code>pin</code> (pemisah koma atau
              titik koma). PIN yang kosong dibuat acak 6 digit.
            </p>
            <Input type="file" accept=".csv,text/csv" onChange={pilihFile} disabled={!!proses} />
            {baris ? (
              <p className="mt-3 mb-0">
                <b>{namaFile}</b>: {baris.length} baris siap diimpor
                {baris.length > 200 ? ` (dikirim bertahap, ${Math.ceil(baris.length / 200)} permintaan)` : ""}.
              </p>
            ) : null}
            {proses ? <p className="mt-3 mb-0 text-info">Mengimpor… {proses.selesai}/{proses.total}</p> : null}
          </>
        ) : (
          <>
            <Alert color={hasil.gagal.length ? "warning" : "success"}>
              {hasil.berhasil.length} siswa ditambahkan, {hasil.gagal.length} gagal.
            </Alert>
            {hasil.berhasil.length ? (
              <>
                <Alert color="warning" className="mb-2">
                  PIN di bawah <b>hanya tampil sekarang</b>. Unduh daftarnya sebelum menutup dialog ini.
                </Alert>
                <Button color="primary" size="sm" className="btn-fill mb-3" onClick={unduhPin}>
                  <i className="tim-icons icon-cloud-download-93" /> Unduh daftar PIN (CSV)
                </Button>
              </>
            ) : null}
            {hasil.gagal.length ? (
              <div style={{ maxHeight: 260, overflowY: "auto" }}>
                <Table size="sm">
                  <thead className="text-primary"><tr><th>Baris</th><th>NIM</th><th>Alasan gagal</th></tr></thead>
                  <tbody>
                    {hasil.gagal.map((g, i) => (
                      <tr key={i}><td>{g.baris}</td><td>{g.nim || "-"}</td><td style={{ whiteSpace: "normal" }}>{g.alasan}</td></tr>
                    ))}
                  </tbody>
                </Table>
              </div>
            ) : null}
          </>
        )}
      </ModalBody>
      <ModalFooter>
        {!hasil ? (
          <>
            <Button color="secondary" onClick={onClose} disabled={!!proses}>Batal</Button>
            <Button color="primary" className="btn-fill" onClick={jalankan} disabled={!baris || !!proses}>
              {proses ? "Mengimpor..." : "Impor"}
            </Button>
          </>
        ) : (
          <Button color="primary" className="btn-fill" onClick={onClose}>Tutup</Button>
        )}
      </ModalFooter>
    </Modal>
  );
}

function SiswaAdmin() {
  const notify = useNotify();
  const [params, setParams] = useSearchParams();
  const [q, setQ] = React.useState(params.get("q") || "");
  const [kelas, setKelas] = React.useState("");
  const [status, setStatus] = React.useState("");
  const [page, setPage] = React.useState(1);
  const dq = useDebounce(q, 400);

  const [data, setData] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);
  const [modal, setModal] = React.useState(null); // { buat, awal }
  const [impor, setImpor] = React.useState(false);
  const [resetPin, setResetPin] = React.useState(null);
  const [pinTampil, setPinTampil] = React.useState(null); // { judul, nim, nama, pin }
  const [hapus, setHapus] = React.useState(null);
  const [menghapus, setMenghapus] = React.useState(false);

  // q dari URL (pencarian navbar) → ke kolom cari
  React.useEffect(() => {
    const dari = params.get("q");
    if (dari !== null) {
      setQ(dari);
      setParams({}, { replace: true });
    }
  }, [params, setParams]);

  const muat = React.useCallback(
    async (signal) => {
      setLoading(true);
      setError(null);
      try {
        setData(await siswaApi.list({ q: dq.trim(), kelas, status, page, limit: LIMIT }, signal));
      } catch (err) {
        if (err.name !== "AbortError") setError(err);
      } finally {
        if (!signal?.aborted) setLoading(false);
      }
    },
    [dq, kelas, status, page]
  );
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    return () => ac.abort();
  }, [muat]);
  React.useEffect(() => setPage(1), [dq, kelas, status]);

  const konfirmasiHapus = async () => {
    setMenghapus(true);
    try {
      await siswaApi.remove(hapus.id_siswa);
      notify.sukses(`Siswa "${hapus.nama}" dihapus.`);
      setHapus(null);
      muat();
    } catch (err) {
      notify.gagal(err.message); // mis. 409 DATA_TERPAKAI: sudah punya riwayat → nonaktifkan saja
      setHapus(null);
    } finally {
      setMenghapus(false);
    }
  };

  const meta = data ? { page: data.page, limit: data.limit, total: data.total, total_halaman: Math.max(1, Math.ceil(data.total / data.limit)) } : null;
  const daftarKelas = data?.daftar_kelas || [];

  return (
    <div className="content">
      <Row>
        <Col xs="12">
          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col>
                  <CardTitle tag="h4" className="mb-0">Siswa</CardTitle>
                  <p className="category mb-0">Peserta kuis (login dengan NIM + PIN){data ? ` · ${data.total} siswa` : ""}</p>
                </Col>
                <Col xs="auto">
                  <Button color="secondary" className="mr-2" onClick={unduhTemplateSiswa}>
                    <i className="tim-icons icon-cloud-download-93" /> Unduh template
                  </Button>
                  <Button color="secondary" className="mr-2" onClick={() => setImpor(true)}>
                    <i className="tim-icons icon-upload" /> Impor CSV
                  </Button>
                  <Button color="primary" className="btn-fill" onClick={() => setModal({ buat: true, awal: FORM_BARU })}>
                    <i className="tim-icons icon-simple-add" /> Tambah siswa
                  </Button>
                </Col>
              </Row>
              <Row className="mt-3">
                <Col md="5"><Input placeholder="Cari NIM atau nama…" value={q} onChange={(e) => setQ(e.target.value)} /></Col>
                <Col md="3">
                  <Input type="select" value={kelas} onChange={(e) => setKelas(e.target.value)}>
                    <option value="">Semua kelas</option>
                    {daftarKelas.map((k) => <option key={k} value={k}>{k}</option>)}
                  </Input>
                </Col>
                <Col md="3">
                  <Input type="select" value={status} onChange={(e) => setStatus(e.target.value)}>
                    <option value="">Semua status</option>
                    <option value="aktif">Aktif</option>
                    <option value="nonaktif">Nonaktif</option>
                  </Input>
                </Col>
              </Row>
            </CardHeader>
            <CardBody>
              <ErrorBox error={error} onRetry={() => muat()} />
              {loading && !data ? (
                <Loading />
              ) : (
                <Table responsive>
                  <thead className="text-primary">
                    <tr><th>NIM</th><th>Nama</th><th>Kelas</th><th>Status</th><th>Login terakhir</th><th className="aksi">Aksi</th></tr>
                  </thead>
                  <tbody>
                    {(data?.siswa || []).map((s) => (
                      <tr key={s.id_siswa}>
                        <td>{s.nim}</td>
                        <td>{s.nama}</td>
                        <td>{s.kelas}</td>
                        <td><Badge color={s.is_aktif ? "success" : "danger"} pill>{s.is_aktif ? "Aktif" : "Nonaktif"}</Badge></td>
                        <td>{s.last_login_at ? formatTanggalWaktu(s.last_login_at) : <span className="text-muted">Belum pernah</span>}</td>
                        <td className="aksi">
                          <Button color="warning" size="sm" className="btn-link btn-icon" title="Ubah"
                            onClick={() => setModal({ buat: false, awal: { id_siswa: s.id_siswa, nim: s.nim, nama: s.nama, kelas: s.kelas, pin: "", is_aktif: s.is_aktif } })}>
                            <i className="tim-icons icon-pencil" />
                          </Button>
                          <Button color="info" size="sm" className="btn-link btn-icon" title="Reset PIN" onClick={() => setResetPin(s)}>
                            <i className="tim-icons icon-key-25" />
                          </Button>
                          <Button color="danger" size="sm" className="btn-link btn-icon" title="Hapus" onClick={() => setHapus(s)}>
                            <i className="tim-icons icon-trash-simple" />
                          </Button>
                        </td>
                      </tr>
                    ))}
                    {data && data.siswa.length === 0 ? (
                      <tr><td colSpan="6" className="text-center text-muted py-4">Tidak ada siswa yang cocok.</td></tr>
                    ) : null}
                  </tbody>
                </Table>
              )}
              <Pager meta={meta} onPage={setPage} />
            </CardBody>
          </Card>
        </Col>
      </Row>

      {modal ? (
        <SiswaModal
          awal={modal.awal}
          buat={modal.buat}
          daftarKelas={daftarKelas}
          onClose={() => setModal(null)}
          onSaved={(hasil) => {
            setModal(null);
            if (hasil) setPinTampil({ judul: "PIN siswa baru", nim: hasil.nim, nama: hasil.nama, pin: hasil.pin_awal });
            muat();
          }}
        />
      ) : null}
      {impor ? <ImporModal onClose={() => setImpor(false)} onSelesai={() => muat()} /> : null}
      {resetPin ? (
        <ResetPinModal
          siswa={resetPin}
          onClose={() => setResetPin(null)}
          onDone={(r) => {
            setPinTampil({ judul: "PIN baru", nim: r.nim, nama: resetPin.nama, pin: r.pin_baru });
            setResetPin(null);
          }}
        />
      ) : null}
      {pinTampil ? <PinModal {...pinTampil} onClose={() => setPinTampil(null)} /> : null}
      <ConfirmModal isOpen={!!hapus} title="Hapus siswa?" confirmText="Ya, hapus" loading={menghapus} onConfirm={konfirmasiHapus} onCancel={() => setHapus(null)}>
        <b>{hapus?.nama}</b> ({hapus?.nim}) akan dihapus. Siswa yang sudah punya riwayat kuis tidak bisa dihapus — nonaktifkan saja.
      </ConfirmModal>
    </div>
  );
}

export default SiswaAdmin;
