import React from "react";
import { Button } from "reactstrap";
import { formatUkuran } from "utils/format";

/** Daftar berkas/link proyek (satu set aktif). `onUnduh(berkas)` mengunduh file lewat endpoint ber-login (blob). */
function BerkasList({ berkas, onUnduh, bekerja }) {
  if (!berkas || berkas.length === 0) return <p className="text-muted mb-0">Belum ada berkas atau link yang dikirim.</p>;
  return (
    <ul className="list-unstyled mb-0">
      {berkas.map((b) => (
        <li key={b.id_berkas} className="d-flex align-items-center py-1" style={{ minWidth: 0 }}>
          <i className={`tim-icons ${b.jenis === "link" ? "icon-link-72" : "icon-notes"} mr-2 text-info`} />
          {b.jenis === "link" ? (
            <a href={b.url} target="_blank" rel="noopener noreferrer" style={{ wordBreak: "break-all" }}>{b.url}</a>
          ) : (
            <>
              <span style={{ wordBreak: "break-all" }}>{b.nama}</span>
              <small className="text-muted ml-2 text-nowrap">{formatUkuran(b.ukuran)}</small>
              <Button color="link" size="sm" className="ml-2 py-0" disabled={bekerja === b.id_berkas} onClick={() => onUnduh(b)}>
                {bekerja === b.id_berkas ? "Mengunduh..." : "Unduh"}
              </Button>
            </>
          )}
        </li>
      ))}
    </ul>
  );
}
export default BerkasList;
