import React from "react";
import { useSearchParams } from "react-router-dom";
import { Badge, Card, CardBody, CardHeader, CardTitle, Col, Input, Row, Table } from "reactstrap";
import * as kuisApi from "services/kuisApi";
import Pager from "components/Pager/Pager";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import useDebounce from "hooks/useDebounce";
import { formatTanggalWaktuDetik } from "utils/format";

// Awalan aksi (backend memfilter lewat regex ^awalan)
const KELOMPOK = [
  { v: "", l: "Semua aksi" },
  { v: "admin.", l: "Admin (login, akun)" },
  { v: "siswa.", l: "Siswa (login, kelola)" },
  { v: "kuis.", l: "Kuis" },
  { v: "soal.", l: "Soal" },
  { v: "hasil.", l: "Hasil & koreksi" },
  { v: "proyek.", l: "Tugas proyek" },
];

const ringkasDetail = (d) => {
  if (d === null || d === undefined || d === "") return "";
  const s = typeof d === "string" ? d : JSON.stringify(d);
  return s.length > 140 ? `${s.slice(0, 140)}…` : s;
};

function Audit() {
  const [params, setParams] = useSearchParams();
  const idKuis = params.get("id_kuis") || "";
  const [aksi, setAksi] = React.useState("");
  const [cari, setCari] = React.useState("");
  const [page, setPage] = React.useState(1);
  const dAksi = useDebounce(cari, 400);
  const [data, setData] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  const muat = React.useCallback(
    async (signal) => {
      setLoading(true);
      setError(null);
      try {
        // Backend: aksi dicocokkan sebagai awalan; hanya huruf, titik, dan underscore yang dipakai.
        const awalan = (dAksi.trim() || aksi).replace(/[^a-z_.]/gi, "");
        setData(await kuisApi.audit({ id_kuis: idKuis, aksi: awalan, page }, signal));
      } catch (err) {
        if (err.name !== "AbortError") setError(err);
      } finally {
        if (!signal?.aborted) setLoading(false);
      }
    },
    [idKuis, aksi, dAksi, page]
  );
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    return () => ac.abort();
  }, [muat]);
  React.useEffect(() => setPage(1), [idKuis, aksi, dAksi]);

  const meta = data ? { page: data.page, limit: data.limit, total: data.total, total_halaman: Math.max(1, Math.ceil(data.total / data.limit)) } : null;

  return (
    <div className="content">
      <Row>
        <Col xs="12">
          <Card>
            <CardHeader>
              <CardTitle tag="h4" className="mb-0">Audit Log</CardTitle>
              <p className="category mb-0">
                Jejak aksi admin, siswa, dan sistem{data ? ` · ${data.total} catatan` : ""}
                {idKuis ? (
                  <>
                    {" "}· disaring untuk satu kuis{" "}
                    <a href="#hapus" onClick={(e) => { e.preventDefault(); setParams({}); }}>(hapus filter)</a>
                  </>
                ) : null}
              </p>
              <Row className="mt-3">
                <Col md="4">
                  <Input type="select" value={aksi} onChange={(e) => { setAksi(e.target.value); setCari(""); }}>
                    {KELOMPOK.map((k) => <option key={k.v} value={k.v}>{k.l}</option>)}
                  </Input>
                </Col>
                <Col md="4">
                  <Input placeholder="Atau awalan aksi, mis. kuis.terbitkan" value={cari} onChange={(e) => setCari(e.target.value)} />
                </Col>
              </Row>
            </CardHeader>
            <CardBody>
              <ErrorBox error={error} onRetry={() => muat()} />
              {loading && !data ? (
                <Loading />
              ) : (
                <Table responsive>
                  <thead className="text-primary">
                    <tr><th>Waktu</th><th>Aktor</th><th>Aksi</th><th>Objek</th><th>Detail</th><th>IP</th></tr>
                  </thead>
                  <tbody>
                    {(data?.log || []).map((l) => (
                      <tr key={l.id_audit}>
                        <td style={{ whiteSpace: "nowrap" }}>{formatTanggalWaktuDetik(l.createdAt)}</td>
                        <td>
                          {l.aktor_nama || "-"} <Badge color={l.aktor_tipe === "admin" ? "info" : l.aktor_tipe === "siswa" ? "success" : "default"}>{l.aktor_tipe}</Badge>
                        </td>
                        <td><code>{l.aksi}</code></td>
                        <td>{l.objek_tipe ? `${l.objek_tipe} ` : ""}<span className="sub">{l.objek_id}</span></td>
                        <td style={{ whiteSpace: "normal", maxWidth: 320, wordBreak: "break-word" }}><small>{ringkasDetail(l.detail)}</small></td>
                        <td>{l.ip || "-"}</td>
                      </tr>
                    ))}
                    {data && data.log.length === 0 ? (
                      <tr><td colSpan="6" className="text-center text-muted py-4">Tidak ada catatan.</td></tr>
                    ) : null}
                  </tbody>
                </Table>
              )}
              <Pager meta={meta} onPage={setPage} />
            </CardBody>
          </Card>
        </Col>
      </Row>
    </div>
  );
}

export default Audit;
