import React from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import {
  Alert, Badge, Button, Card, CardBody, CardFooter, CardHeader, CardTitle, Col, FormGroup, Input, Label, Row,
} from "reactstrap";
import * as kuisApi from "services/kuisApi";
import * as soalApi from "services/soalApi";
import * as siswaApi from "services/siswaApi";
import { useNotify } from "contexts/NotifyContext";
import FormField from "components/FormField/FormField";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import useDebounce from "hooks/useDebounce";
import { MODE_NILAI, PUBLIKASI_HASIL, TIPE_SOAL, dariInputWaktu, keInputWaktu } from "utils/format";
import { validasiKuis } from "utils/validasi";

const tambahMenit = (inputWaktu, menit) => {
  const d = new Date(dariInputWaktu(inputWaktu));
  return keInputWaktu(new Date(d.getTime() + menit * 60000));
};
const awalBaru = () => {
  const mulai = keInputWaktu(new Date(Date.now() + 3600000)); // 1 jam lagi (WIB)
  return {
    judul: "", deskripsi: "", mapel: "", kelas: [], soal: [],
    mulai, selesai: tambahMenit(mulai, 60), durasi_soal_detik: 4,
    mode_nilai: "kecepatan", publikasi_hasil: "setelah_selesai", tampilkan_leaderboard: false,
  };
};
const dariServer = (k) => ({
  judul: k.judul, deskripsi: k.deskripsi || "", mapel: k.mapel || "", kelas: k.kelas || [],
  soal: (k.soal || []).map((s) => ({ id_soal: s.id_soal, tipe: s.tipe, teks: s.teks })),
  mulai: keInputWaktu(k.mulai_at), selesai: keInputWaktu(k.selesai_at), durasi_soal_detik: k.durasi_soal_detik,
  mode_nilai: k.mode_nilai, publikasi_hasil: k.publikasi_hasil, tampilkan_leaderboard: !!k.tampilkan_leaderboard,
});
const sama = (a, b) => JSON.stringify(a) === JSON.stringify(b);

/** Pemilih soal dari bank soal (cari → tambah). */
function PemilihSoal({ terpilih, onTambah, disabled }) {
  const [q, setQ] = React.useState("");
  const dq = useDebounce(q, 400);
  const [hasil, setHasil] = React.useState([]);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState(null);
  React.useEffect(() => {
    const ac = new AbortController();
    setLoading(true);
    soalApi
      .list({ q: dq.trim(), limit: 15, page: 1 }, ac.signal)
      .then((r) => { setHasil(r.soal); setError(null); })
      .catch((err) => err.name !== "AbortError" && setError(err))
      .finally(() => !ac.signal.aborted && setLoading(false));
    return () => ac.abort();
  }, [dq]);
  const ids = new Set(terpilih.map((s) => s.id_soal));
  return (
    <div>
      <Input placeholder="Cari di bank soal…" value={q} disabled={disabled} onChange={(e) => setQ(e.target.value)} className="mb-2" />
      <ErrorBox error={error} />
      {loading && hasil.length === 0 ? <Loading text="Memuat soal..." /> : null}
      <div className="picker-list">
        {hasil.map((s) => (
          <div className="picker-item" key={s.id_soal}>
            <div className="flex-grow-1">
              <Badge color={s.tipe === "pilihan_ganda" ? "info" : "warning"} pill className="mr-2">{TIPE_SOAL[s.tipe]}</Badge>
              {s.teks.length > 90 ? `${s.teks.slice(0, 90)}…` : s.teks}
            </div>
            <Button type="button" size="sm" color="primary" disabled={disabled || ids.has(s.id_soal)} onClick={() => onTambah({ id_soal: s.id_soal, tipe: s.tipe, teks: s.teks })}>
              {ids.has(s.id_soal) ? "Sudah dipilih" : "Tambah"}
            </Button>
          </div>
        ))}
        {!loading && hasil.length === 0 ? <p className="text-muted mb-0">Tidak ada soal yang cocok.</p> : null}
      </div>
    </div>
  );
}

function KuisForm() {
  const { id } = useParams();
  const edit = !!id;
  const navigate = useNavigate();
  const notify = useNotify();
  const [v, setV] = React.useState(awalBaru);
  const [awal, setAwal] = React.useState(null); // nilai dari server (untuk kirim hanya yang berubah)
  const [status, setStatus] = React.useState("draft");
  const [kelasOpsi, setKelasOpsi] = React.useState([]);
  const [errors, setErrors] = React.useState({});
  const [serverError, setServerError] = React.useState("");
  const [loadError, setLoadError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);
  const [saving, setSaving] = React.useState(false);

  React.useEffect(() => {
    const ac = new AbortController();
    setLoading(true);
    Promise.all([siswaApi.daftarKelas(ac.signal), edit ? kuisApi.get(id, ac.signal) : null])
      .then(([kelas, k]) => {
        setKelasOpsi(kelas);
        if (k) {
          const f = dariServer(k);
          setV(f);
          setAwal(f);
          setStatus(k.status);
        }
      })
      .catch((err) => err.name !== "AbortError" && setLoadError(err))
      .finally(() => !ac.signal.aborted && setLoading(false));
    return () => ac.abort();
  }, [edit, id]);

  const kunciJadwal = edit && ["live", "finished"].includes(status); // backend menolak ubah jadwal/soal/kelas
  const arsip = status === "archived";
  const lockJadwal = kunciJadwal || arsip || saving;
  const lockSemua = arsip || saving;

  const set = (k, val) => {
    setV((x) => ({ ...x, [k]: val }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
  };
  const ubah = (k) => (e) => set(k, e.target.value);
  const toggleKelas = (k) => set("kelas", v.kelas.includes(k) ? v.kelas.filter((x) => x !== k) : [...v.kelas, k]);
  const geser = (i, d) => {
    const j = i + d;
    if (j < 0 || j >= v.soal.length) return;
    const arr = [...v.soal];
    [arr[i], arr[j]] = [arr[j], arr[i]];
    set("soal", arr);
  };

  // Info jadwal: kuis berakhir efektif di min(selesai, mulai + soal × durasi)
  const totalMs = v.soal.length * (Number(v.durasi_soal_detik) || 0) * 1000;
  const selMs = v.mulai && v.selesai ? new Date(dariInputWaktu(v.selesai)) - new Date(dariInputWaktu(v.mulai)) : null;
  const terpotong = selMs !== null && totalMs > 0 && selMs < totalMs;

  const simpan = async (e) => {
    e.preventDefault();
    const er = validasiKuis(v, { kunciJadwal: kunciJadwal });
    if (!kunciJadwal && v.soal.length === 0) er.soal = "Pilih minimal 1 soal dari bank soal.";
    setErrors(er);
    if (Object.keys(er).length) return;
    setSaving(true);
    setServerError("");
    const meta = {
      judul: v.judul.trim(), deskripsi: v.deskripsi.trim(), mapel: v.mapel.trim(),
      publikasi_hasil: v.publikasi_hasil, tampilkan_leaderboard: v.tampilkan_leaderboard,
    };
    const jadwal = {
      mulai_at: dariInputWaktu(v.mulai), selesai_at: dariInputWaktu(v.selesai),
      durasi_soal_detik: Number(v.durasi_soal_detik), mode_nilai: v.mode_nilai,
      soal_ids: v.soal.map((s) => s.id_soal), kelas: v.kelas,
    };
    try {
      if (edit) {
        // Backend menolak (409) SETIAP field jadwal pada kuis berlangsung/selesai, walau nilainya sama
        // → kirim hanya field jadwal yang benar-benar berubah, dan tidak sama sekali saat terkunci.
        const payload = { ...meta };
        if (!kunciJadwal) {
          const asal = {
            mulai_at: dariInputWaktu(awal.mulai), selesai_at: dariInputWaktu(awal.selesai),
            durasi_soal_detik: Number(awal.durasi_soal_detik), mode_nilai: awal.mode_nilai,
            soal_ids: awal.soal.map((s) => s.id_soal), kelas: awal.kelas,
          };
          for (const k of Object.keys(jadwal)) if (!sama(jadwal[k], asal[k])) payload[k] = jadwal[k];
        }
        await kuisApi.update(id, payload);
        notify.sukses("Kuis diperbarui.");
        navigate(`/admin/kuis/${id}`);
      } else {
        const baru = await kuisApi.create({ ...meta, ...jadwal });
        notify.sukses("Kuis dibuat sebagai draft. Periksa lalu terbitkan.");
        navigate(`/admin/kuis/${baru.id_kuis}`);
      }
    } catch (err) {
      setServerError(err.message);
      setSaving(false);
    }
  };

  if (loading) return <div className="content"><Loading /></div>;
  if (loadError) return <div className="content"><ErrorBox error={loadError} /><Button tag={Link} to="/admin/kuis" color="secondary">Kembali</Button></div>;

  // Kelas yang ada di kuis tetapi tidak lagi punya siswa aktif tetap ditampilkan agar terlihat.
  const semuaKelas = [...kelasOpsi.map((k) => ({ ...k }))];
  for (const k of v.kelas) if (!semuaKelas.some((x) => x.kelas === k)) semuaKelas.push({ kelas: k, aktif: 0, total: 0 });

  return (
    <div className="content">
      <Row>
        <Col lg="10">
          <form onSubmit={simpan} noValidate>
            <Card>
              <CardHeader><CardTitle tag="h4" className="mb-0">{edit ? "Ubah kuis" : "Kuis baru"}</CardTitle></CardHeader>
              <CardBody>
                {arsip ? <Alert color="warning">Kuis yang diarsipkan tidak bisa diubah.</Alert> : null}
                {kunciJadwal ? (
                  <Alert color="info">
                    Kuis sudah {status === "live" ? "berlangsung" : "selesai"}: jadwal, soal, kelas, dan mode nilai <b>dikunci</b>.
                    Hanya judul, deskripsi, mapel, dan kebijakan hasil yang bisa diubah.
                  </Alert>
                ) : null}
                {serverError ? <Alert color="danger">{serverError}</Alert> : null}

                <Row>
                  <Col md="8"><FormField label="Judul" name="judul" required value={v.judul} disabled={lockSemua} onChange={ubah("judul")} error={errors.judul} maxLength={150} /></Col>
                  <Col md="4"><FormField label="Mapel" name="mapel" value={v.mapel} disabled={lockSemua} onChange={ubah("mapel")} error={errors.mapel} maxLength={100} /></Col>
                </Row>
                <FormField label="Deskripsi" name="deskripsi" error={errors.deskripsi}>
                  <Input id="deskripsi" type="textarea" rows="2" maxLength={1000} value={v.deskripsi} disabled={lockSemua} onChange={ubah("deskripsi")} />
                </FormField>

                <hr />
                <h5>Jadwal <small className="text-muted">(WIB)</small></h5>
                <Row>
                  <Col md="4"><FormField label="Mulai" name="mulai" type="datetime-local" required value={v.mulai} disabled={lockJadwal} onChange={ubah("mulai")} error={errors.mulai} /></Col>
                  <Col md="4"><FormField label="Berakhir paling lambat" name="selesai" type="datetime-local" required value={v.selesai} disabled={lockJadwal} onChange={ubah("selesai")} error={errors.selesai} /></Col>
                  <Col md="4"><FormField label="Durasi per soal (detik)" name="durasi_soal_detik" type="number" min={3} max={60} required value={v.durasi_soal_detik} disabled={lockJadwal} onChange={ubah("durasi_soal_detik")} error={errors.durasi_soal_detik} hint="3–60 detik" /></Col>
                </Row>
                {totalMs > 0 ? (
                  <p className={`small ${terpotong ? "text-warning" : "text-muted"}`}>
                    {v.soal.length} soal × {v.durasi_soal_detik} dtk = {Math.ceil(totalMs / 60000)} menit.
                    {terpotong ? " Waktu “Berakhir paling lambat” lebih awal dari total durasi, sehingga soal-soal terakhir tidak sempat tampil." : ""}
                  </p>
                ) : null}

                <hr />
                <h5>Peserta (kelas)</h5>
                <FormGroup className={errors.kelas ? "has-danger" : ""}>
                  {semuaKelas.length === 0 ? (
                    <p className="text-muted">Belum ada siswa. Tambahkan siswa (beserta kelasnya) di menu Siswa terlebih dahulu.</p>
                  ) : (
                    <div className="d-flex flex-wrap">
                      {semuaKelas.map((k) => (
                        <FormGroup check className="mr-4" key={k.kelas}>
                          <Label check>
                            <Input type="checkbox" checked={v.kelas.includes(k.kelas)} disabled={lockJadwal} onChange={() => toggleKelas(k.kelas)} />
                            <span className="form-check-sign"><span className="check" /></span>
                            {k.kelas} <small className="text-muted">({k.aktif} siswa aktif)</small>
                          </Label>
                        </FormGroup>
                      ))}
                    </div>
                  )}
                  {errors.kelas ? <small className="text-danger d-block" role="alert">{errors.kelas}</small> : null}
                </FormGroup>

                <hr />
                <h5>Soal <small className="text-muted">({v.soal.length} dipilih — urutan = urutan tampil)</small></h5>
                {errors.soal ? <small className="text-danger d-block mb-2" role="alert">{errors.soal}</small> : null}
                {v.soal.length === 0 ? <p className="text-muted">Belum ada soal. Tambahkan dari bank soal di bawah.</p> : null}
                {v.soal.map((s, i) => (
                  <div className="picker-item" key={s.id_soal}>
                    <b className="mr-3">{i + 1}.</b>
                    <div className="flex-grow-1">
                      {s.tipe ? <Badge color={s.tipe === "pilihan_ganda" ? "info" : "warning"} pill className="mr-2">{TIPE_SOAL[s.tipe]}</Badge> : <Badge color="danger" className="mr-2">soal dihapus</Badge>}
                      {s.teks ? (s.teks.length > 100 ? `${s.teks.slice(0, 100)}…` : s.teks) : s.id_soal}
                    </div>
                    <Button type="button" size="sm" color="secondary" className="btn-link btn-icon" disabled={lockJadwal || i === 0} title="Naikkan" onClick={() => geser(i, -1)}><i className="tim-icons icon-minimal-up" /></Button>
                    <Button type="button" size="sm" color="secondary" className="btn-link btn-icon" disabled={lockJadwal || i === v.soal.length - 1} title="Turunkan" onClick={() => geser(i, 1)}><i className="tim-icons icon-minimal-down" /></Button>
                    <Button type="button" size="sm" color="danger" className="btn-link btn-icon" disabled={lockJadwal} title="Lepas" onClick={() => set("soal", v.soal.filter((_, j) => j !== i))}><i className="tim-icons icon-simple-remove" /></Button>
                  </div>
                ))}
                {!kunciJadwal && !arsip ? (
                  <>
                    <h6 className="mt-4">Tambah dari bank soal</h6>
                    <PemilihSoal terpilih={v.soal} onTambah={(s) => set("soal", [...v.soal, s])} disabled={saving} />
                  </>
                ) : null}

                <hr />
                <h5>Penilaian &amp; hasil</h5>
                <Row>
                  <Col md="4">
                    <FormField label="Mode nilai" name="mode_nilai">
                      <Input id="mode_nilai" type="select" value={v.mode_nilai} disabled={lockJadwal} onChange={ubah("mode_nilai")}>
                        {Object.entries(MODE_NILAI).map(([k, l]) => <option key={k} value={k}>{l}</option>)}
                      </Input>
                    </FormField>
                  </Col>
                  <Col md="4">
                    <FormField label="Hasil dibuka untuk siswa" name="publikasi_hasil">
                      <Input id="publikasi_hasil" type="select" value={v.publikasi_hasil} disabled={lockSemua} onChange={ubah("publikasi_hasil")}>
                        {Object.entries(PUBLIKASI_HASIL).map(([k, l]) => <option key={k} value={k}>{l}</option>)}
                      </Input>
                    </FormField>
                  </Col>
                  <Col md="4">
                    <FormGroup check className="mt-4">
                      <Label check>
                        <Input type="checkbox" checked={v.tampilkan_leaderboard} disabled={lockSemua} onChange={(e) => set("tampilkan_leaderboard", e.target.checked)} />
                        <span className="form-check-sign"><span className="check" /></span>
                        Tampilkan papan peringkat ke siswa
                      </Label>
                    </FormGroup>
                  </Col>
                </Row>
              </CardBody>
              <CardFooter>
                <Button type="submit" color="primary" className="btn-fill" disabled={lockSemua}>{saving ? "Menyimpan..." : edit ? "Simpan perubahan" : "Simpan sebagai draft"}</Button>
                <Button tag={Link} to={edit ? `/admin/kuis/${id}` : "/admin/kuis"} color="secondary" className="ml-2" disabled={saving}>Batal</Button>
              </CardFooter>
            </Card>
          </form>
        </Col>
      </Row>
    </div>
  );
}

export default KuisForm;
