import { request, requestBlob, requestData } from "./api";

// Tugas proyek: TUGAS (induk, /admin/tugas) berisi banyak KELOMPOK (/admin/proyek); siswa (/siswa/proyek);
// verifikasi QR publik (/verifikasi/proyek).

// ── Admin: tugas (induk) ──
/** GET /admin/tugas?kelas=&q=&page=&limit= → { tugas[], total, page, limit } */
export const listTugas = (params, signal) => requestData("/admin/tugas", { role: "admin", query: params, signal });
/** → { id_tugas, nama_tugas, kelas, jadwal[], kelompok[], belum_berkelompok[], server_now } */
export const getTugas = (id, signal) => requestData(`/admin/tugas/${id}`, { role: "admin", signal });
/** POST { nama_tugas, kelas, jadwal: ["YYYY-MM-DD"] } */
export const createTugas = (data) => requestData("/admin/tugas", { role: "admin", method: "POST", body: data });
export const updateTugas = (id, data) => requestData(`/admin/tugas/${id}`, { role: "admin", method: "PUT", body: data });
export const removeTugas = (id) => request(`/admin/tugas/${id}`, { role: "admin", method: "DELETE" });
// Jadwal tingkat tugas → diterapkan ke SEMUA kelompok. Hasil: { tugas, hasil: { diterapkan, total, dilewati: [{ id_proyek, nama_kelompok, alasan }] } }
export const tambahPertemuanTugas = (id, tanggal) => requestData(`/admin/tugas/${id}/pertemuan`, { role: "admin", method: "POST", body: { tanggal } });
export const ubahPertemuanTugas = (id, nomor, tanggal) => requestData(`/admin/tugas/${id}/pertemuan/${nomor}`, { role: "admin", method: "PUT", body: { tanggal } });
export const hapusPertemuanTugas = (id, nomor) => requestData(`/admin/tugas/${id}/pertemuan/${nomor}`, { role: "admin", method: "DELETE" });

// ── Admin: kelompok ──
/** GET /admin/proyek?kelas=&status=berjalan|final&q=&page=&limit= → { proyek[], total, page, limit } */
export const list = (params, signal) => requestData("/admin/proyek", { role: "admin", query: params, signal });
export const get = (id, signal) => requestData(`/admin/proyek/${id}`, { role: "admin", signal });
/** POST { id_tugas, nama_kelompok, nama_proyek, deskripsi, anggota: [id_siswa], pertemuan?: ["YYYY-MM-DD"] }
 *  `pertemuan` tidak dikirim → menyalin jadwal tugas; dikirim (boleh []) → jadwal khusus kelompok. */
export const create = (data) => requestData("/admin/proyek", { role: "admin", method: "POST", body: data });
/** PUT { nama_kelompok, nama_proyek, deskripsi, anggota } (kelas & tugas tidak dapat diubah) */
export const update = (id, data) => requestData(`/admin/proyek/${id}`, { role: "admin", method: "PUT", body: data });
export const remove = (id) => request(`/admin/proyek/${id}`, { role: "admin", method: "DELETE" });
export const tambahPertemuan = (id, tanggal) => requestData(`/admin/proyek/${id}/pertemuan`, { role: "admin", method: "POST", body: { tanggal } });
export const ubahPertemuan = (id, nomor, tanggal) => requestData(`/admin/proyek/${id}/pertemuan/${nomor}`, { role: "admin", method: "PUT", body: { tanggal } });
export const hapusPertemuan = (id, nomor) => requestData(`/admin/proyek/${id}/pertemuan/${nomor}`, { role: "admin", method: "DELETE" });
/** POST { komentar, perlu_revisi } */
export const komentar = (id, nomor, body) => requestData(`/admin/proyek/${id}/pertemuan/${nomor}/komentar`, { role: "admin", method: "POST", body });
export const finalkan = (id) => requestData(`/admin/proyek/${id}/final`, { role: "admin", method: "POST", body: {} });
/** Membuka kunci final (QR laporan lama menjadi tidak valid). */
export const bukaKembali = (id) => requestData(`/admin/proyek/${id}/buka-kembali`, { role: "admin", method: "POST", body: {} });
/** PDF laporan kelompok yang sudah final → Blob */
export const unduhLaporanAdmin = (id) => requestBlob(`/admin/proyek/${id}/laporan`, { role: "admin" });
export const unduhBerkasAdmin = (id, idBerkas) => requestBlob(`/admin/proyek/${id}/berkas/${idBerkas}`, { role: "admin" });

// ── Siswa ──
export const daftarSaya = (signal) => requestData("/siswa/proyek", { role: "siswa", signal });
export const detailSaya = (id, signal) => requestData(`/siswa/proyek/${id}`, { role: "siswa", signal });
/** POST multipart: progress, links (JSON array), berkas (file[]) */
export const kirim = (id, nomor, { progress, links, files }) => {
  const fd = new FormData();
  fd.set("progress", progress);
  fd.set("links", JSON.stringify(links || []));
  (files || []).forEach((f) => fd.append("berkas", f, f.name));
  return requestData(`/siswa/proyek/${id}/pertemuan/${nomor}/kirim`, { role: "siswa", method: "POST", formData: fd });
};
export const unduhBerkasSiswa = (id, idBerkas) => requestBlob(`/siswa/proyek/${id}/berkas/${idBerkas}`, { role: "siswa" });
/** PDF laporan (hanya setelah final) → Blob */
export const unduhLaporan = (id) => requestBlob(`/siswa/proyek/${id}/laporan`, { role: "siswa" });

// ── Publik ──
export const verifikasi = (kode, signal) => requestData(`/verifikasi/proyek/${encodeURIComponent(kode)}`, { role: null, signal });
/** Info satu berkas final (tautan publik di PDF laporan; tanpa login). */
export const infoBerkasPublik = (kode, idBerkas, signal) =>
  requestData(`/verifikasi/proyek/${encodeURIComponent(kode)}/berkas/${encodeURIComponent(idBerkas)}`, { role: null, signal });
/** Unduh berkas final (tanpa login) → Blob */
export const unduhBerkasPublik = (kode, idBerkas) =>
  requestBlob(`/verifikasi/proyek/${encodeURIComponent(kode)}/berkas/${encodeURIComponent(idBerkas)}/unduh`, { role: null });
