import React from "react";
import { Link, useParams } from "react-router-dom";
import {
  Alert, Badge, Button, Card, CardBody, CardHeader, CardTitle, Col, FormGroup, Input, Label, Modal, ModalBody,
  ModalFooter, ModalHeader, Nav, NavItem, NavLink, Row, Table,
} from "reactstrap";
import * as kuisApi from "services/kuisApi";
import { useNotify } from "contexts/NotifyContext";
import StatusBadge from "components/StatusBadge/StatusBadge";
import FormField from "components/FormField/FormField";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { formatAngka, formatDetik, slug } from "utils/format";
import { unduhBlob } from "utils/download";

const TAB = [
  { k: "peringkat", l: "Peringkat" },
  { k: "rincian", l: "Rincian nilai" },
  { k: "jawaban", l: "Jawaban & koreksi" },
];

/** Lencana "final / sementara" untuk hasil yang masih bisa berubah. */
const BadgeFinal = ({ status }) => (
  <Badge color={status === "final" ? "success" : "warning"} pill>{status === "final" ? "Final" : "Sementara"}</Badge>
);

function Peringkat({ id, tick }) {
  const [d, setD] = React.useState(null);
  const [error, setError] = React.useState(null);
  React.useEffect(() => {
    const ac = new AbortController();
    kuisApi.leaderboard(id, ac.signal).then((r) => { setD(r); setError(null); }).catch((e) => e.name !== "AbortError" && setError(e));
    return () => ac.abort();
  }, [id, tick]);
  if (!d) return error ? <ErrorBox error={error} /> : <Loading />;
  return (
    <>
      <ErrorBox error={error} />
      <p className="text-muted">
        <BadgeFinal status={d.status} /> &nbsp;{d.soal_tertutup} dari {d.total_soal} soal sudah ditutup dan dihitung.
        {d.status === "sementara" ? " Jawaban yang menunggu pemeriksaan belum ikut peringkat." : ""}
      </p>
      <Table responsive>
        <thead className="text-primary">
          <tr><th>#</th><th>NIM</th><th>Nama</th><th>Kelas</th><th className="text-right">Skor</th><th className="text-right">Benar</th><th className="text-right">Salah</th><th className="text-right">Kosong</th><th className="text-right">Menunggu</th><th className="text-right">Waktu benar</th></tr>
        </thead>
        <tbody>
          {d.peringkat.map((b) => (
            <tr key={b.id_siswa}>
              <td>{b.peringkat}</td><td>{b.nim}</td><td>{b.nama}</td><td>{b.kelas}</td>
              <td className="text-right"><b>{formatAngka(b.skor)}</b></td>
              <td className="text-right">{b.benar}</td><td className="text-right">{b.salah}</td>
              <td className="text-right">{b.tidak_dijawab}</td>
              <td className="text-right">{b.pending || "-"}</td>
              <td className="text-right">{formatDetik(b.waktu_respons_ms)}</td>
            </tr>
          ))}
          {d.peringkat.length === 0 ? <tr><td colSpan="10" className="text-center text-muted py-4">Belum ada peserta.</td></tr> : null}
        </tbody>
      </Table>
    </>
  );
}

function Rincian({ id, tick, onBukaSoal }) {
  const [d, setD] = React.useState(null);
  const [error, setError] = React.useState(null);
  React.useEffect(() => {
    const ac = new AbortController();
    kuisApi.rincian(id, ac.signal).then((r) => { setD(r); setError(null); }).catch((e) => e.name !== "AbortError" && setError(e));
    return () => ac.abort();
  }, [id, tick]);
  if (!d) return error ? <ErrorBox error={error} /> : <Loading />;
  if (d.soal.length === 0) return <p className="text-muted mb-0">Belum ada soal yang ditutup.</p>;
  return (
    <>
      <ErrorBox error={error} />
      <p className="text-muted small">
        Nilai per soal (0–10). “-” = tidak menjawab. Klik nomor soal untuk melihat jawabannya. ⏳ = soal masih sementara (ada jawaban menunggu pemeriksaan).
      </p>
      <Table responsive size="sm" className="tabel-rincian">
        <thead className="text-primary">
          <tr>
            <th>NIM</th><th>Nama</th><th>Kelas</th>
            {d.soal.map((s) => (
              <th key={s.nomor} className="text-center" title={s.teks}>
                <a href="#soal" onClick={(e) => { e.preventDefault(); onBukaSoal(s.nomor); }}>{s.nomor}</a>
                {s.status === "sementara" ? " ⏳" : ""}
              </th>
            ))}
            <th className="text-right">Jumlah</th>
          </tr>
        </thead>
        <tbody>
          {d.siswa.map((b) => (
            <tr key={b.id_siswa}>
              <td>{b.nim}</td><td>{b.nama}</td><td>{b.kelas}</td>
              {b.nilai.map((n, i) => <td key={i} className="text-center">{n === null ? <span className="text-muted">-</span> : formatAngka(n)}</td>)}
              <td className="text-right"><b>{formatAngka(b.nilai.reduce((a, n) => a + (n || 0), 0))}</b></td>
            </tr>
          ))}
        </tbody>
      </Table>
    </>
  );
}

/** Pemeriksaan manual jawaban isian (hanya untuk jawaban yang bukan "otomatis"). */
function ReviewModal({ idKuis, j, onClose, onSaved }) {
  const notify = useNotify();
  const [benar, setBenar] = React.useState(j.benar === null ? null : j.benar);
  const [catatan, setCatatan] = React.useState(j.catatan_periksa || "");
  const [error, setError] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const kirim = async (e) => {
    e.preventDefault();
    if (benar === null) return setError("Pilih benar atau salah.");
    setSaving(true);
    try {
      await kuisApi.review(idKuis, j.id_jawaban, benar, catatan.trim());
      notify.sukses("Pemeriksaan disimpan; nilai soal dihitung ulang.");
      onSaved();
    } catch (err) {
      setError(err.message);
      setSaving(false);
    }
  };
  return (
    <Modal isOpen toggle={saving ? undefined : onClose} centered>
      <form onSubmit={kirim} noValidate>
        <ModalHeader toggle={saving ? undefined : onClose}>Periksa jawaban</ModalHeader>
        <ModalBody>
          {error ? <Alert color="danger">{error}</Alert> : null}
          <p className="mb-1">{j.nama} <span className="text-muted">({j.nim})</span></p>
          <div className="jawaban-box mb-3">{j.jawaban || "(kosong)"}</div>
          <div className="mb-3">
            <Button type="button" color={benar === true ? "success" : "secondary"} className={benar === true ? "btn-fill mr-2" : "mr-2"} onClick={() => setBenar(true)}>✓ Benar</Button>
            <Button type="button" color={benar === false ? "danger" : "secondary"} className={benar === false ? "btn-fill" : ""} onClick={() => setBenar(false)}>✗ Salah</Button>
          </div>
          <FormField label="Catatan (opsional)" name="catatan" value={catatan} maxLength={500} onChange={(e) => setCatatan(e.target.value)} />
        </ModalBody>
        <ModalFooter>
          <Button type="button" color="secondary" onClick={onClose} disabled={saving}>Batal</Button>
          <Button type="submit" color="primary" className="btn-fill" disabled={saving}>{saving ? "Menyimpan..." : "Simpan"}</Button>
        </ModalFooter>
      </form>
    </Modal>
  );
}

/** Koreksi nilai manual (menimpa nilai). Kosongkan nilai = hapus koreksi. Wajib alasan ≥ 3 karakter. */
function KoreksiModal({ idKuis, idSoal, j, onClose, onSaved }) {
  const notify = useNotify();
  const [nilai, setNilai] = React.useState(j.nilai_koreksi === null || j.nilai_koreksi === undefined ? "" : String(j.nilai_koreksi));
  const [alasan, setAlasan] = React.useState(j.alasan_koreksi || "");
  const [error, setError] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const kirim = async (e) => {
    e.preventDefault();
    const hapus = nilai.trim() === "";
    const n = Number(nilai.replace(",", "."));
    if (!hapus && !(Number.isFinite(n) && n >= 0 && n <= 10)) return setError("Nilai koreksi harus 0–10.");
    if (alasan.trim().length < 3) return setError("Alasan koreksi wajib diisi (min. 3 karakter).");
    setSaving(true);
    try {
      await kuisApi.koreksi(idKuis, { id_soal: idSoal, id_siswa: j.id_siswa, nilai: hapus ? null : n, alasan: alasan.trim() });
      notify.sukses(hapus ? "Koreksi dihapus." : "Nilai dikoreksi.");
      onSaved();
    } catch (err) {
      setError(err.message);
      setSaving(false);
    }
  };
  return (
    <Modal isOpen toggle={saving ? undefined : onClose} centered>
      <form onSubmit={kirim} noValidate>
        <ModalHeader toggle={saving ? undefined : onClose}>Koreksi nilai</ModalHeader>
        <ModalBody>
          {error ? <Alert color="danger">{error}</Alert> : null}
          <p className="mb-3">{j.nama} <span className="text-muted">({j.nim})</span> · nilai otomatis: <b>{formatAngka(j.nilai)}</b></p>
          <FormField label="Nilai koreksi (0–10)" name="nilai" inputMode="decimal" value={nilai} onChange={(e) => setNilai(e.target.value)} hint="Kosongkan untuk menghapus koreksi dan kembali ke nilai otomatis." />
          <FormField label="Alasan" name="alasan" required value={alasan} maxLength={500} onChange={(e) => setAlasan(e.target.value)} hint="Tercatat di audit log." />
        </ModalBody>
        <ModalFooter>
          <Button type="button" color="secondary" onClick={onClose} disabled={saving}>Batal</Button>
          <Button type="submit" color="primary" className="btn-fill" disabled={saving}>{saving ? "Menyimpan..." : "Simpan"}</Button>
        </ModalFooter>
      </form>
    </Modal>
  );
}

function Jawaban({ idKuis, jumlahSoal, nomorAwal, tick, bolehKoreksi }) {
  const [nomor, setNomor] = React.useState(nomorAwal || 1);
  const [pending, setPending] = React.useState(false);
  const [d, setD] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [muatKe, setMuatKe] = React.useState(0);
  const [review, setReview] = React.useState(null);
  const [koreksi, setKoreksi] = React.useState(null);

  React.useEffect(() => setNomor(nomorAwal || 1), [nomorAwal]);
  React.useEffect(() => {
    const ac = new AbortController();
    kuisApi.jawaban(idKuis, nomor, { hanyaPending: pending }, ac.signal)
      .then((r) => { setD(r); setError(null); })
      .catch((e) => e.name !== "AbortError" && setError(e));
    return () => ac.abort();
  }, [idKuis, nomor, pending, muatKe, tick]);

  const segarkan = () => { setReview(null); setKoreksi(null); setMuatKe((x) => x + 1); };

  return (
    <>
      <Row className="mb-3 align-items-end">
        <Col md="3">
          <label htmlFor="nomor-soal">Soal nomor</label>
          <Input id="nomor-soal" type="select" value={nomor} onChange={(e) => setNomor(Number(e.target.value))}>
            {Array.from({ length: jumlahSoal }, (_, i) => <option key={i + 1} value={i + 1}>{i + 1}</option>)}
          </Input>
        </Col>
        <Col md="5">
          <FormGroup check className="mb-2">
            <Label check>
              <Input type="checkbox" checked={pending} onChange={(e) => setPending(e.target.checked)} />
              <span className="form-check-sign"><span className="check" /></span>
              Hanya yang menunggu pemeriksaan
            </Label>
          </FormGroup>
        </Col>
      </Row>
      <ErrorBox error={error} />
      {(!d || d.nomor !== nomor) && !error ? <Loading /> : null}
      {d && d.nomor === nomor ? (
        <>
          <Card className="mb-3" style={{ background: "transparent", boxShadow: "none", border: "1px solid rgba(255,255,255,.1)" }}>
            <CardBody className="py-2">
              <small className="text-muted">Soal {d.nomor}{d.ditutup ? "" : " · belum ditutup (review & koreksi baru bisa dilakukan setelah soal ditutup)"}</small>
              <div>{d.soal?.teks || "(soal dihapus)"}</div>
              {d.soal?.tipe === "pilihan_ganda" ? (
                <small className="text-muted">Kunci: {d.soal.opsi.filter((o) => o.is_benar).map((o) => o.teks).join(", ")}</small>
              ) : d.soal?.jawaban_acuan?.length ? (
                <small className="text-muted">Jawaban acuan: {d.soal.jawaban_acuan.join(" / ")} · {d.soal.mode_periksa === "manual" ? "diperiksa manual" : "diperiksa otomatis"}</small>
              ) : null}
            </CardBody>
          </Card>
          <Table responsive size="sm">
            <thead className="text-primary">
              <tr><th>NIM</th><th>Nama</th><th>Kelas</th><th>Jawaban</th><th>Hasil</th><th className="text-right">Waktu</th><th className="text-right">Urutan</th><th className="text-right">Nilai</th><th className="aksi">Aksi</th></tr>
            </thead>
            <tbody>
              {d.jawaban.map((j) => {
                const nilaiTampil = j.nilai_koreksi ?? j.nilai;
                return (
                  <tr key={j.id_jawaban}>
                    <td>{j.nim}</td><td>{j.nama}</td><td>{j.kelas}</td>
                    <td style={{ whiteSpace: "normal", maxWidth: 240, wordBreak: "break-word" }}>{j.jawaban}</td>
                    <td>
                      {j.benar === null ? <Badge color="warning" pill>Menunggu</Badge> : j.benar ? <Badge color="success" pill>Benar</Badge> : <Badge color="danger" pill>Salah</Badge>}
                      {j.status_periksa === "manual" ? <span className="sub">diperiksa admin</span> : null}
                    </td>
                    <td className="text-right">{formatDetik(j.waktu_respons_ms)}</td>
                    <td className="text-right">{j.peringkat_benar ?? "-"}</td>
                    <td className="text-right">
                      {formatAngka(nilaiTampil)}
                      {j.nilai_koreksi !== null && j.nilai_koreksi !== undefined ? <span className="sub" title={j.alasan_koreksi}>dikoreksi</span> : null}
                    </td>
                    <td className="aksi">
                      {bolehKoreksi && d.ditutup && j.status_periksa !== "otomatis" ? (
                        <Button size="sm" color="info" className="btn-link" onClick={() => setReview(j)}>Periksa</Button>
                      ) : null}
                      {bolehKoreksi && d.ditutup ? (
                        <Button size="sm" color="warning" className="btn-link" onClick={() => setKoreksi(j)}>Koreksi</Button>
                      ) : null}
                    </td>
                  </tr>
                );
              })}
              {d.jawaban.length === 0 ? <tr><td colSpan="9" className="text-center text-muted py-4">Tidak ada jawaban.</td></tr> : null}
            </tbody>
          </Table>
        </>
      ) : null}
      {review ? <ReviewModal idKuis={idKuis} j={review} onClose={() => setReview(null)} onSaved={segarkan} /> : null}
      {koreksi ? <KoreksiModal idKuis={idKuis} idSoal={d?.soal?.id_soal} j={koreksi} onClose={() => setKoreksi(null)} onSaved={segarkan} /> : null}
    </>
  );
}

function KuisHasil() {
  const { id } = useParams();
  const notify = useNotify();
  const [kuis, setKuis] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [tab, setTab] = React.useState("peringkat");
  const [nomorBuka, setNomorBuka] = React.useState(1);
  const [tick, setTick] = React.useState(0);
  const [mengunduh, setMengunduh] = React.useState("");
  const statusRef = React.useRef("");
  statusRef.current = kuis?.status || "";

  React.useEffect(() => {
    let batal = false;
    const ambil = () => kuisApi.get(id).then((k) => !batal && setKuis(k)).catch((e) => !batal && setError(e));
    ambil();
    // Saat terjadwal/berlangsung: segarkan tiap 5 dtk (tab aktif memuat ulang datanya lewat `tick`).
    const t = setInterval(() => {
      if (document.hidden || !["live", "scheduled"].includes(statusRef.current)) return;
      ambil();
      setTick((x) => x + 1);
    }, 5000);
    return () => {
      batal = true;
      clearInterval(t);
    };
  }, [id]);

  const unduh = async (jenis) => {
    setMengunduh(jenis);
    try {
      const blob = await kuisApi.exportCsv(id, jenis);
      unduhBlob(blob, `${slug(kuis?.judul)}-${jenis}.csv`);
    } catch (err) {
      notify.gagal(err.message);
    } finally {
      setMengunduh("");
    }
  };

  if (!kuis) return <div className="content">{error ? <><ErrorBox error={error} /><Button tag={Link} to="/admin/kuis" color="secondary">Kembali</Button></> : <Loading />}</div>;
  if (kuis.status === "draft") {
    return (
      <div className="content">
        <Alert color="info">Kuis masih draft — belum ada hasil. Terbitkan kuis lebih dulu.</Alert>
        <Button tag={Link} to={`/admin/kuis/${id}`} color="secondary">Kembali ke kuis</Button>
      </div>
    );
  }
  const autoMuat = kuis.status === "live" || kuis.status === "scheduled";

  return (
    <div className="content">
      <Row>
        <Col xs="12">
          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col>
                  <CardTitle tag="h4" className="mb-0">{kuis.judul} <StatusBadge status={kuis.status} className="ml-2" /></CardTitle>
                  <p className="category mb-0">Hasil kuis{autoMuat ? " · diperbarui otomatis tiap 5 detik" : ""}</p>
                </Col>
                <Col xs="auto">
                  <Button color="secondary" className="mr-2" disabled={!!mengunduh} onClick={() => unduh("peringkat")}>
                    <i className="tim-icons icon-cloud-download-93" /> {mengunduh === "peringkat" ? "Mengunduh…" : "CSV peringkat"}
                  </Button>
                  <Button color="secondary" className="mr-2" disabled={!!mengunduh} onClick={() => unduh("rincian")}>
                    <i className="tim-icons icon-cloud-download-93" /> {mengunduh === "rincian" ? "Mengunduh…" : "CSV rincian"}
                  </Button>
                  <Button tag={Link} to={`/admin/kuis/${id}`} color="default">Detail kuis</Button>
                </Col>
              </Row>
              <Nav tabs className="mt-3">
                {TAB.map((t) => (
                  <NavItem key={t.k}>
                    <NavLink href={`#${t.k}`} active={tab === t.k} onClick={(e) => { e.preventDefault(); setTab(t.k); }}>{t.l}</NavLink>
                  </NavItem>
                ))}
              </Nav>
            </CardHeader>
            <CardBody>
              {tab === "peringkat" ? <Peringkat id={id} tick={tick} /> : null}
              {tab === "rincian" ? <Rincian id={id} tick={tick} onBukaSoal={(n) => { setNomorBuka(n); setTab("jawaban"); }} /> : null}
              {tab === "jawaban" ? (
                <Jawaban idKuis={id} jumlahSoal={kuis.soal_ids?.length || kuis.soal?.length || 1} nomorAwal={nomorBuka} tick={autoMuat ? tick : 0} bolehKoreksi />
              ) : null}
            </CardBody>
          </Card>
        </Col>
      </Row>
    </div>
  );
}

export default KuisHasil;
