import React from "react";
import * as adminApi from "services/adminApi";
import * as pesertaApi from "services/pesertaApi";
import { AUTH_EXPIRED_EVENT, clearToken, getToken, setToken } from "services/api";

const AuthContext = React.createContext(null);

/**
 * Dua peran terpisah (token & status masing-masing): admin dan siswa.
 * status: "memeriksa" (validasi token tersimpan) | "masuk" | "keluar"
 */
function useSesi(role, apiProfil) {
  const [user, setUser] = React.useState(null);
  const [status, setStatus] = React.useState(getToken(role) ? "memeriksa" : "keluar");

  // Saat aplikasi dibuka: validasi token tersimpan & ambil profil.
  React.useEffect(() => {
    if (!getToken(role)) return;
    let batal = false;
    apiProfil()
      .then((data) => {
        if (batal) return;
        setUser(data);
        setStatus("masuk");
      })
      .catch(() => {
        if (batal) return;
        // 401 sesi berakhir sudah membersihkan token lewat api.js. Pada error jaringan token dibiarkan,
        // tetapi pengguna diarahkan ke halaman login agar tidak terjebak di spinner.
        setUser(null);
        setStatus("keluar");
      });
    return () => {
      batal = true;
    };
  }, [role, apiProfil]);

  // Server menyatakan sesi peran ini berakhir di tengah penggunaan → keluar.
  React.useEffect(() => {
    const onExpired = (e) => {
      if (e.detail?.role !== role) return;
      setUser(null);
      setStatus("keluar");
    };
    window.addEventListener(AUTH_EXPIRED_EVENT, onExpired);
    return () => window.removeEventListener(AUTH_EXPIRED_EVENT, onExpired);
  }, [role]);

  const masuk = React.useCallback(
    (token, data) => {
      setToken(role, token);
      setUser(data);
      setStatus("masuk");
    },
    [role]
  );

  // Bersihkan sesi lokal; pencabutan di server dilakukan best-effort sebelum token dihapus.
  const keluar = React.useCallback(
    async (apiLogout) => {
      try {
        if (getToken(role)) await apiLogout();
      } catch {
        /* abaikan: token tetap dihapus di klien */
      }
      clearToken(role);
      setUser(null);
      setStatus("keluar");
    },
    [role]
  );

  return { user, setUser, status, masuk, keluar };
}

export function AuthProvider({ children }) {
  const a = useSesi("admin", adminApi.profil);
  const s = useSesi("siswa", pesertaApi.profil);
  const { masuk: masukAdmin, keluar: keluarAdmin, setUser: setAdmin } = a;
  const { masuk: masukSiswa, keluar: keluarSiswa } = s;

  const loginAdmin = React.useCallback(
    async (username, password, captchaId, captcha) => {
      const { token, admin } = await adminApi.login(username, password, captchaId, captcha);
      masukAdmin(token, admin);
      // Profil lengkap (last_login_at dst.) dimuat di belakang layar.
      adminApi.profil().then(setAdmin).catch(() => {});
    },
    [masukAdmin, setAdmin]
  );
  const logoutAdmin = React.useCallback(() => keluarAdmin(adminApi.logout), [keluarAdmin]);
  const muatUlangProfilAdmin = React.useCallback(async () => {
    const data = await adminApi.profil();
    setAdmin(data);
    return data;
  }, [setAdmin]);

  const loginSiswa = React.useCallback(
    async (nim, pin, captchaId, captcha) => {
      const { token, siswa } = await pesertaApi.login(nim, pin, captchaId, captcha);
      masukSiswa(token, siswa);
    },
    [masukSiswa]
  );
  const logoutSiswa = React.useCallback(() => keluarSiswa(pesertaApi.logout), [keluarSiswa]);

  const value = React.useMemo(
    () => ({
      admin: a.user,
      statusAdmin: a.status,
      loginAdmin,
      logoutAdmin,
      muatUlangProfilAdmin,
      siswa: s.user,
      statusSiswa: s.status,
      loginSiswa,
      logoutSiswa,
    }),
    [a.user, a.status, s.user, s.status, loginAdmin, logoutAdmin, muatUlangProfilAdmin, loginSiswa, logoutSiswa]
  );
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export const useAuth = () => React.useContext(AuthContext);
