import { request, requestData } from "./api";

// Bank soal: /admin/soal

/** GET /admin/soal?q=&tipe=&mapel=&page=&limit= → { soal, total, page, limit } */
export const list = (params, signal) => requestData("/admin/soal", { role: "admin", query: params, signal });
/** GET /admin/soal/:id → soal (+ terkunci) */
export const get = (id, signal) => requestData(`/admin/soal/${id}`, { role: "admin", signal });
export const create = (data) => requestData("/admin/soal", { role: "admin", method: "POST", body: data });
export const update = (id, data) => requestData(`/admin/soal/${id}`, { role: "admin", method: "PUT", body: data });
export const duplikasi = (id) => requestData(`/admin/soal/${id}/duplikasi`, { role: "admin", method: "POST", body: {} });
export const remove = (id) => request(`/admin/soal/${id}`, { role: "admin", method: "DELETE" });

/** POST /admin/soal/gambar (multipart, field "gambar") → { gambar, url } */
export const unggahGambar = (file) => {
  const fd = new FormData();
  fd.append("gambar", file);
  return requestData("/admin/soal/gambar", { role: "admin", method: "POST", formData: fd });
};

/**
 * POST /admin/soal/import { baris: [...], uji? } (maks 200 baris/permintaan)
 * uji=true → hanya validasi (tidak disimpan). Respons: { uji, berhasil, gagal: [{ baris (1..n dalam batch), alasan }] }
 */
export const importMassal = (baris, uji = false) =>
  requestData("/admin/soal/import", { role: "admin", method: "POST", body: { baris, uji } });
