import React from "react";
import { Link } from "react-router-dom";
import { Button, Card, CardBody, CardHeader, CardTitle, Col, Nav, NavItem, NavLink, Row, Table } from "reactstrap";
import * as kuisApi from "services/kuisApi";
import StatusBadge from "components/StatusBadge/StatusBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import AksiKuis from "views/kuis/AksiKuis";
import { formatTanggalWaktu } from "utils/format";

function KuisList() {
  const [arsip, setArsip] = React.useState(false);
  const [rows, setRows] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  const muat = React.useCallback(
    async (signal) => {
      try {
        setRows(await kuisApi.list({ arsip }, signal));
        setError(null);
      } catch (err) {
        if (err.name !== "AbortError") setError(err);
      } finally {
        if (!signal?.aborted) setLoading(false);
      }
    },
    [arsip]
  );
  React.useEffect(() => {
    setLoading(true);
    setRows(null);
    const ac = new AbortController();
    muat(ac.signal);
    const t = setInterval(() => muat(ac.signal), 15000); // status (terjadwal → berlangsung → selesai) mengikuti waktu server
    return () => {
      ac.abort();
      clearInterval(t);
    };
  }, [muat]);

  return (
    <div className="content">
      <Row>
        <Col xs="12">
          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col>
                  <CardTitle tag="h4" className="mb-0">Kuis</CardTitle>
                  <p className="category mb-0">Status dihitung server dari jadwal; tidak ada tombol “mulai” manual</p>
                </Col>
                <Col xs="auto">
                  <Button tag={Link} to="/admin/kuis/baru" color="primary" className="btn-fill">
                    <i className="tim-icons icon-simple-add" /> Kuis baru
                  </Button>
                </Col>
              </Row>
              <Nav tabs className="mt-3">
                <NavItem>
                  <NavLink href="#aktif" active={!arsip} onClick={(e) => { e.preventDefault(); setArsip(false); }}>Aktif</NavLink>
                </NavItem>
                <NavItem>
                  <NavLink href="#arsip" active={arsip} onClick={(e) => { e.preventDefault(); setArsip(true); }}>Arsip</NavLink>
                </NavItem>
              </Nav>
            </CardHeader>
            <CardBody>
              <ErrorBox error={error} onRetry={() => muat()} />
              {loading && !rows ? (
                <Loading />
              ) : (
                <Table responsive>
                  <thead className="text-primary">
                    <tr><th>Kuis</th><th>Kelas</th><th>Jadwal</th><th>Soal</th><th>Status</th><th className="aksi">Aksi</th></tr>
                  </thead>
                  <tbody>
                    {(rows || []).map((k) => (
                      <tr key={k.id_kuis}>
                        <td style={{ whiteSpace: "normal", minWidth: 200 }}>
                          <Link className="table-link" to={`/admin/kuis/${k.id_kuis}`}>{k.judul}</Link>
                          <span className="sub">{k.mapel || "Tanpa mapel"}</span>
                        </td>
                        <td style={{ whiteSpace: "normal" }}>{k.kelas.join(", ") || <span className="text-muted">-</span>}</td>
                        <td>
                          {formatTanggalWaktu(k.mulai_at)}
                          <span className="sub">s.d. {formatTanggalWaktu(k.akhir_efektif)}</span>
                        </td>
                        <td>{k.jumlah_soal}<span className="sub">{k.durasi_soal_detik} dtk/soal · {k.mode_nilai === "tetap" ? "nilai tetap" : "nilai kecepatan"}</span></td>
                        <td><StatusBadge status={k.status} /></td>
                        <td className="aksi">
                          <AksiKuis
                            kuis={k}
                            compact
                            tanpa={["pantau"]}
                            onSelesai={(nama) => nama && muat()}
                          />
                        </td>
                      </tr>
                    ))}
                    {rows && rows.length === 0 ? (
                      <tr>
                        <td colSpan="6" className="text-center text-muted py-4">
                          {arsip ? "Belum ada kuis di arsip." : "Belum ada kuis. Buat kuis baru untuk memulai."}
                        </td>
                      </tr>
                    ) : null}
                  </tbody>
                </Table>
              )}
            </CardBody>
          </Card>
        </Col>
      </Row>
    </div>
  );
}

export default KuisList;
