import React from "react";
import { Link, Navigate, useLocation } from "react-router-dom";
import { Alert, Button, Card, CardBody, CardHeader, Form, FormGroup, Input } from "reactstrap";
import { useAuth } from "contexts/AuthContext";
import * as pesertaApi from "services/pesertaApi";
import { Loading } from "components/Feedback/Feedback";
import CaptchaField from "components/CaptchaField/CaptchaField";
import logo from "assets/img/komputer.svg";

function LoginSiswa() {
  const { statusSiswa: status, loginSiswa } = useAuth();
  const location = useLocation();
  const [nim, setNim] = React.useState("");
  const [pin, setPin] = React.useState("");
  const [captcha, setCaptcha] = React.useState(null); // { enabled, captcha_id, gambar_svg }
  const [jawaban, setJawaban] = React.useState("");
  const [error, setError] = React.useState("");
  const [loading, setLoading] = React.useState(false);

  const dari = location.state?.dari;
  const tujuan = dari ? `${dari.pathname}${dari.search || ""}${dari.hash || ""}` : "/siswa/kuis";

  // Captcha berlaku sekali pakai (2 menit) → ambil baru setiap kali perlu.
  const muatCaptcha = React.useCallback(async () => {
    setJawaban("");
    try {
      setCaptcha(await pesertaApi.captcha());
    } catch (err) {
      setCaptcha(null);
      // 404 = backend belum punya endpoint captcha siswa → login tanpa captcha.
      if (err.status !== 404) setError(err.message);
    }
  }, []);
  React.useEffect(() => {
    muatCaptcha();
  }, [muatCaptcha]);

  if (status === "memeriksa") return <div className="auth-page"><Loading text="Memeriksa sesi..." /></div>;
  if (status === "masuk") return <Navigate to={tujuan} replace />;

  const submit = async (e) => {
    e.preventDefault();
    if (!nim.trim() || !pin) {
      setError("NIM dan PIN wajib diisi.");
      return;
    }
    if (captcha?.enabled && !jawaban.trim()) {
      setError("Isi captcha terlebih dahulu.");
      return;
    }
    setError("");
    setLoading(true);
    try {
      await loginSiswa(nim.trim(), pin, captcha?.enabled ? captcha.captcha_id : undefined, jawaban.trim());
    } catch (err) {
      // Pesan "NIM tidak terdaftar atau PIN salah" sengaja sama dari server; 429 membawa Retry-After.
      setError(err.retryAfter ? `${err.message} (coba lagi ±${Math.ceil(err.retryAfter / 60)} menit)` : err.message);
      setLoading(false);
      if (captcha?.enabled) muatCaptcha(); // captcha lama sudah terpakai
    }
  };

  return (
    <div className="auth-page">
      <div style={{ width: "100%", maxWidth: 420 }}>
        <div className="auth-brand">
          <img src={logo} alt="" />
          <h1>Kuis Real-Time</h1>
          <p className="text-muted mb-0">Masuk dengan NIM dan PIN dari guru/admin</p>
        </div>
        <Card>
          <CardHeader>
            <h4 className="card-title mb-0">Login Siswa</h4>
          </CardHeader>
          <CardBody>
            <Form onSubmit={submit} noValidate>
              {error ? <Alert color="danger">{error}</Alert> : null}
              <FormGroup>
                <label htmlFor="nim">NIM</label>
                <Input
                  id="nim"
                  autoFocus
                  autoComplete="username"
                  autoCapitalize="none"
                  inputMode="text"
                  value={nim}
                  onChange={(e) => setNim(e.target.value)}
                  disabled={loading}
                />
              </FormGroup>
              <FormGroup>
                <label htmlFor="pin">PIN</label>
                <Input
                  id="pin"
                  type="password"
                  inputMode="numeric"
                  autoComplete="current-password"
                  value={pin}
                  onChange={(e) => setPin(e.target.value)}
                  disabled={loading}
                />
              </FormGroup>
              <CaptchaField captcha={captcha} value={jawaban} onChange={setJawaban} onRefresh={muatCaptcha} disabled={loading} />
              <Button color="primary" type="submit" block className="btn-fill mt-4" disabled={loading}>
                {loading ? "Memproses..." : "Masuk"}
              </Button>
              <div className="text-center mt-3">
                <Link to="/admin/login" className="text-muted">Masuk sebagai admin →</Link>
              </div>
            </Form>
          </CardBody>
        </Card>
      </div>
    </div>
  );
}

export default LoginSiswa;
