import { request, requestData } from "./api";

// Kelola siswa oleh admin: /admin/siswa

/** GET /admin/siswa?q=&kelas=&status=aktif|nonaktif&page=&limit= → { siswa, total, page, limit, daftar_kelas } */
export const list = (params, signal) => requestData("/admin/siswa", { role: "admin", query: params, signal });

/** GET /admin/siswa/kelas → [{ kelas, aktif, total }] */
export const daftarKelas = (signal) => requestData("/admin/siswa/kelas", { role: "admin", signal });

/** POST /admin/siswa { nim, nama, kelas, pin? } → siswa + pin_awal (hanya tampil sekali) */
export const create = (data) => requestData("/admin/siswa", { role: "admin", method: "POST", body: data });

/** PUT /admin/siswa/:id { nama, kelas, is_aktif } */
export const update = (id, data) => requestData(`/admin/siswa/${id}`, { role: "admin", method: "PUT", body: data });

/** POST /admin/siswa/:id/reset-pin { pin? } → { id_siswa, nim, pin_baru } */
export const resetPin = (id, pin) =>
  requestData(`/admin/siswa/${id}/reset-pin`, { role: "admin", method: "POST", body: pin ? { pin } : {} });

export const remove = (id) => request(`/admin/siswa/${id}`, { role: "admin", method: "DELETE" });

/** POST /admin/siswa/import { baris: [{nim,nama,kelas,pin?}] } (maks 200) → { berhasil[], gagal[] } */
export const importMassal = (baris) =>
  requestData("/admin/siswa/import", { role: "admin", method: "POST", body: { baris } });
