import React from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { Badge, Button, Card, CardBody, CardHeader, CardTitle, Col, Progress, Row, Table } from "reactstrap";
import * as kuisApi from "services/kuisApi";
import StatusBadge from "components/StatusBadge/StatusBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import AksiKuis, { aksiTersedia } from "views/kuis/AksiKuis";
import { MODE_NILAI, PUBLIKASI_HASIL, TIPE_SOAL, formatHitungMundur, formatTanggalWaktu } from "utils/format";

const Baris = ({ label, children }) => (
  <Row>
    <Col sm="4" tag="dt">{label}</Col>
    <Col sm="8" tag="dd">{children}</Col>
  </Row>
);

/** Pantauan langsung: polling ringan ke /pantau tiap 2 dtk selama kuis terjadwal/berlangsung. */
function PantauLive({ id, status, onStatusBerubah }) {
  const [p, setP] = React.useState(null);
  const [diterima, setDiterima] = React.useState(Date.now());
  const [error, setError] = React.useState(null);
  const [, setTick] = React.useState(0);

  React.useEffect(() => {
    const ac = new AbortController();
    let berhenti = false;
    const ambil = async () => {
      try {
        const r = await kuisApi.pantau(id, ac.signal);
        if (berhenti) return;
        setP(r);
        setDiterima(Date.now());
        setError(null);
        if (r.status !== status) onStatusBerubah(); // status dihitung server: segarkan data kuis
      } catch (err) {
        if (err.name !== "AbortError" && !berhenti) setError(err);
      }
    };
    ambil();
    const poll = setInterval(() => !document.hidden && ambil(), 2000);
    const tick = setInterval(() => setTick((t) => t + 1), 250); // hitung mundur halus di antara polling
    return () => {
      berhenti = true;
      ac.abort();
      clearInterval(poll);
      clearInterval(tick);
    };
  }, [id, status, onStatusBerubah]);

  if (!p) return error ? <ErrorBox error={error} /> : <Loading text="Memuat pantauan..." />;
  const sisa = p.sisa_ms === null || p.sisa_ms === undefined ? null : p.sisa_ms - (Date.now() - diterima);
  const pct = p.peserta_aktif ? Math.round((p.sudah_menjawab / p.peserta_aktif) * 100) : 0;

  return (
    <>
      <ErrorBox error={error} />
      <Row className="text-center mb-3">
        <Col xs="6" md="3"><div className="kuis-besar-kecil">{p.soal_aktif_nomor ? `${p.soal_aktif_nomor}/${p.jumlah_soal}` : "-"}</div><small className="text-muted">Soal aktif</small></Col>
        <Col xs="6" md="3"><div className="kuis-besar-kecil text-warning">{sisa !== null ? formatHitungMundur(sisa) : "-"}</div><small className="text-muted">{status === "scheduled" ? "Menuju mulai" : "Sisa waktu soal"}</small></Col>
        <Col xs="6" md="3"><div className="kuis-besar-kecil text-success">{p.peserta_aktif}</div><small className="text-muted">Aktif (dari {p.peserta_berhak} berhak)</small></Col>
        <Col xs="6" md="3"><div className="kuis-besar-kecil text-info">{p.peserta_bergabung}</div><small className="text-muted">Pernah bergabung</small></Col>
      </Row>
      {p.status === "live" ? (
        <>
          <div className="d-flex justify-content-between small mb-1">
            <span>Sudah menjawab soal ini</span>
            <span>{p.sudah_menjawab} dari {p.peserta_aktif} peserta aktif</span>
          </div>
          <Progress value={pct} color="success" className="mb-3" />
          <Table responsive size="sm">
            <thead className="text-primary"><tr><th>NIM</th><th>Nama</th><th>Kelas</th><th>Soal ini</th></tr></thead>
            <tbody>
              {p.daftar_aktif.map((s) => (
                <tr key={s.id_siswa}>
                  <td>{s.nim}</td><td>{s.nama}</td><td>{s.kelas}</td>
                  <td><Badge color={s.sudah_menjawab ? "success" : "default"} pill>{s.sudah_menjawab ? "Sudah menjawab" : "Belum"}</Badge></td>
                </tr>
              ))}
              {p.daftar_aktif.length === 0 ? <tr><td colSpan="4" className="text-center text-muted py-3">Belum ada peserta aktif.</td></tr> : null}
            </tbody>
          </Table>
        </>
      ) : (
        <p className="text-muted mb-0">Daftar peserta aktif tampil saat kuis berlangsung. Halaman ini memperbarui diri tiap 2 detik.</p>
      )}
    </>
  );
}

function KuisDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [kuis, setKuis] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  const muat = React.useCallback(async () => {
    try {
      setKuis(await kuisApi.get(id));
      setError(null);
    } catch (err) {
      setError(err);
    } finally {
      setLoading(false);
    }
  }, [id]);
  React.useEffect(() => {
    setLoading(true);
    muat();
  }, [muat]);

  if (loading) return <div className="content"><Loading /></div>;
  if (!kuis) {
    return (
      <div className="content">
        <ErrorBox error={error} onRetry={muat} />
        <Button tag={Link} to="/admin/kuis" color="secondary">Kembali ke daftar</Button>
      </div>
    );
  }
  const b = aksiTersedia(kuis.status);

  return (
    <div className="content">
      <ErrorBox error={error} onRetry={muat} />
      <Row>
        <Col lg="8">
          <Card>
            <CardHeader>
              <div className="d-flex align-items-start">
                <div className="flex-grow-1">
                  <CardTitle tag="h3" className="mb-1">{kuis.judul}</CardTitle>
                  <p className="category mb-0">{kuis.mapel || "Tanpa mapel"}</p>
                </div>
                <StatusBadge status={kuis.status} />
              </div>
            </CardHeader>
            <CardBody>
              <div className="mb-3">
                <AksiKuis
                  kuis={kuis}
                  tanpa={["pantau"]}
                  onSelesai={(nama) => (nama === "hapus" ? navigate("/admin/kuis", { replace: true }) : muat())}
                />
                <Button tag={Link} to={`/admin/audit?id_kuis=${kuis.id_kuis}`} color="default" className="mb-2">
                  <i className="tim-icons icon-bullet-list-67" /> Audit kuis ini
                </Button>
              </div>
              {kuis.deskripsi ? <p>{kuis.deskripsi}</p> : null}
              <dl className="detail-list">
                <Baris label="Kelas peserta">{kuis.kelas.join(", ") || "-"}</Baris>
                <Baris label="Mulai">{formatTanggalWaktu(kuis.mulai_at)}</Baris>
                <Baris label="Berakhir paling lambat">{formatTanggalWaktu(kuis.selesai_at)}</Baris>
                <Baris label="Berakhir efektif">{formatTanggalWaktu(kuis.akhir_efektif)}{kuis.diakhiri_at ? <small className="text-muted"> (diakhiri manual)</small> : null}</Baris>
                <Baris label="Durasi per soal">{kuis.durasi_soal_detik} detik</Baris>
                <Baris label="Mode nilai">{MODE_NILAI[kuis.mode_nilai]}</Baris>
                <Baris label="Hasil untuk siswa">{PUBLIKASI_HASIL[kuis.publikasi_hasil]}{kuis.tampilkan_leaderboard ? " · dengan papan peringkat" : ""}</Baris>
                <Baris label="Dibuat oleh">{kuis.dibuat_oleh || "-"}</Baris>
              </dl>
            </CardBody>
          </Card>
          <Card>
            <CardHeader><CardTitle tag="h4" className="mb-0">Soal ({kuis.soal?.length || 0})</CardTitle></CardHeader>
            <CardBody>
              <Table responsive>
                <thead className="text-primary"><tr><th>#</th><th>Soal</th><th>Tipe</th></tr></thead>
                <tbody>
                  {(kuis.soal || []).map((s, i) => (
                    <tr key={s.id_soal}>
                      <td>{i + 1}</td>
                      <td style={{ whiteSpace: "normal" }}>{s.teks}</td>
                      <td>{TIPE_SOAL[s.tipe]}{s.tipe === "isian" ? <span className="sub">{s.mode_periksa === "manual" ? "manual" : "otomatis"}</span> : null}</td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </CardBody>
          </Card>
        </Col>
        <Col lg="4">
          <Card>
            <CardHeader><CardTitle tag="h4" className="mb-0">Pantau langsung</CardTitle></CardHeader>
            <CardBody>
              {b.pantau ? (
                <PantauLive id={kuis.id_kuis} status={kuis.status} onStatusBerubah={muat} />
              ) : (
                <p className="text-muted mb-0">
                  {kuis.status === "draft" ? "Terbitkan kuis agar bisa dipantau." : "Pemantauan hanya untuk kuis terjadwal/berlangsung. Lihat Hasil untuk rekap."}
                </p>
              )}
            </CardBody>
          </Card>
        </Col>
      </Row>
    </div>
  );
}

export default KuisDetail;
