import React from "react";
import { Badge } from "reactstrap";
import { STATUS_PERTEMUAN, STATUS_PROYEK } from "utils/format";

/** Lencana status proyek (berjalan | final) atau pertemuan (belum_dibuka | terbuka | terkirim | terlewat). */
function ProyekBadge({ status, pertemuan = false, className = "" }) {
  const meta = (pertemuan ? STATUS_PERTEMUAN : STATUS_PROYEK)[status] || { label: status || "-", color: "info" };
  return <Badge color={meta.color} className={className} pill>{meta.label}</Badge>;
}
export default ProyekBadge;
