import React from "react";
import { Link, useLocation, useNavigate, useParams } from "react-router-dom";
import { Alert, Button, Card, CardBody, CardHeader, CardTitle, Col, Input, Row } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import FormField from "components/FormField/FormField";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { useNotify } from "contexts/NotifyContext";
import { formatTanggalPertemuan } from "utils/format";

const MAKS_PERTEMUAN = 30;

/**
 * Kelompok di dalam sebuah tugas.
 *  - Buat:  /admin/tugas/:id/kelompok/baru   (:id = id tugas)
 *  - Ubah:  /admin/tugas/kelompok/:id/edit   (:id = id kelompok) — nama, deskripsi, anggota
 * Anggota yang bisa dipilih: siswa aktif kelas tugas yang BELUM masuk kelompok lain di tugas yang sama.
 */
function ProyekForm() {
  const { id } = useParams();
  const { pathname } = useLocation();
  const edit = pathname.endsWith("/edit");
  const navigate = useNavigate();
  const notify = useNotify();

  const [tugas, setTugas] = React.useState(null);
  const [f, setF] = React.useState({ nama_kelompok: "", nama_proyek: "", deskripsi: "" });
  const [tersedia, setTersedia] = React.useState([]);
  const [anggota, setAnggota] = React.useState(new Set());
  const [cari, setCari] = React.useState("");
  const [mode, setMode] = React.useState("ikut"); // ikut jadwal tugas | sendiri
  const [tanggal, setTanggal] = React.useState([""]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(null);
  const [errs, setErrs] = React.useState({});
  const [menyimpan, setMenyimpan] = React.useState(false);
  const [final, setFinal] = React.useState(false);
  const [idKelompok, setIdKelompok] = React.useState(null);

  React.useEffect(() => {
    const ac = new AbortController();
    (async () => {
      try {
        let idTugas = id;
        let saatIni = [];
        if (edit) {
          const p = await proyekApi.get(id, ac.signal);
          idTugas = p.id_tugas;
          saatIni = p.anggota.map((a) => ({ id_siswa: a.id_siswa, nim: a.nim, nama: a.nama }));
          setF({ nama_kelompok: p.nama_kelompok, nama_proyek: p.nama_proyek, deskripsi: p.deskripsi || "" });
          setAnggota(new Set(saatIni.map((a) => a.id_siswa)));
          setFinal(p.status === "final");
          setIdKelompok(p.id_proyek);
        }
        const t = await proyekApi.getTugas(idTugas, ac.signal);
        setTugas(t);
        setTersedia([...t.belum_berkelompok, ...saatIni].sort((a, b) => a.nama.localeCompare(b.nama)));
      } catch (err) {
        if (err.name !== "AbortError") setError(err);
      } finally {
        setLoading(false);
      }
    })();
    return () => ac.abort();
  }, [id, edit]);

  const set = (k) => (e) => setF((x) => ({ ...x, [k]: e.target.value }));
  const toggle = (sid) => setAnggota((s) => { const n = new Set(s); if (n.has(sid)) n.delete(sid); else n.add(sid); return n; });
  const tampil = tersedia.filter((s) => !cari.trim() || `${s.nama} ${s.nim}`.toLowerCase().includes(cari.trim().toLowerCase()));

  const validasi = () => {
    const e = {};
    if (f.nama_kelompok.trim().length < 2) e.nama_kelompok = "Nama kelompok minimal 2 karakter.";
    if (f.nama_proyek.trim().length < 3) e.nama_proyek = "Nama proyek minimal 3 karakter.";
    if (anggota.size < 1) e.anggota = "Pilih minimal 1 anggota.";
    if (!edit && mode === "sendiri") {
      const t = tanggal.filter(Boolean);
      for (let i = 1; i < t.length; i++) if (t[i] <= t[i - 1]) { e.pertemuan = "Tanggal pertemuan harus berurutan dan tidak boleh sama."; break; }
    }
    setErrs(e);
    return Object.keys(e).length === 0;
  };

  const simpan = async (ev) => {
    ev.preventDefault();
    if (!validasi()) return;
    setMenyimpan(true);
    try {
      const dasar = { nama_kelompok: f.nama_kelompok.trim(), nama_proyek: f.nama_proyek.trim(), deskripsi: f.deskripsi.trim(), anggota: [...anggota] };
      let hasil;
      if (edit) hasil = await proyekApi.update(idKelompok, dasar);
      else hasil = await proyekApi.create({ ...dasar, id_tugas: tugas.id_tugas, ...(mode === "sendiri" ? { pertemuan: tanggal.filter(Boolean) } : {}) });
      notify.sukses(edit ? "Kelompok diperbarui." : "Kelompok dibuat.");
      navigate(`/admin/tugas/kelompok/${hasil.id_proyek}`);
    } catch (err) {
      notify.gagal(err.message);
    } finally {
      setMenyimpan(false);
    }
  };

  if (loading) return <div className="content"><Loading /></div>;
  if (error && !tugas) return <div className="content"><ErrorBox error={error} /></div>;
  if (final) return <div className="content"><Alert color="warning">Kelompok sudah final dan tidak dapat diubah. <Link to={`/admin/tugas/kelompok/${idKelompok}`}>Kembali ke detail</Link> (admin dapat membuka kembali final di sana).</Alert></div>;

  const batal = edit ? `/admin/tugas/kelompok/${idKelompok}` : `/admin/tugas/${tugas.id_tugas}`;

  return (
    <div className="content">
      <form onSubmit={simpan} noValidate>
        <Row>
          <Col lg="8">
            <Card>
              <CardHeader>
                <CardTitle tag="h4" className="mb-1">{edit ? "Ubah Kelompok" : "Kelompok Baru"}</CardTitle>
                <p className="category mb-0">Tugas: <b>{tugas.nama_tugas}</b> · Kelas {tugas.kelas}</p>
              </CardHeader>
              <CardBody>
                <ErrorBox error={error} />
                <FormField label="Nama kelompok" name="nama_kelompok" required value={f.nama_kelompok} onChange={set("nama_kelompok")} error={errs.nama_kelompok} maxLength={100} />
                <FormField label="Nama proyek yang dikerjakan" name="nama_proyek" required value={f.nama_proyek} onChange={set("nama_proyek")} error={errs.nama_proyek} maxLength={200} />
                <FormField label="Deskripsi proyek" name="deskripsi" type="textarea" rows={4} value={f.deskripsi} onChange={set("deskripsi")} maxLength={3000} />

                <FormField label={`Anggota kelompok (${anggota.size} dipilih)`} name="anggota" required error={errs.anggota}
                  hint="Hanya siswa aktif kelas ini yang belum masuk kelompok lain di tugas ini.">
                  {tersedia.length === 0 ? <p className="text-muted mb-0">Semua siswa sudah masuk kelompok.</p> : (
                    <>
                      <Input placeholder="Cari nama atau NIM" value={cari} onChange={(e) => setCari(e.target.value)} className="mb-2" />
                      <div style={{ maxHeight: 260, overflowY: "auto", border: "1px solid rgba(255,255,255,.1)", borderRadius: 6, padding: "6px 12px" }}>
                        {tampil.map((s) => (
                          <label key={s.id_siswa} className="d-flex align-items-center py-1 mb-0" style={{ cursor: "pointer" }}>
                            <input type="checkbox" checked={anggota.has(s.id_siswa)} onChange={() => toggle(s.id_siswa)} className="mr-2" />
                            {s.nama} <small className="text-muted ml-2">{s.nim}</small>
                          </label>
                        ))}
                        {tampil.length === 0 ? <span className="text-muted">Tidak ada siswa.</span> : null}
                      </div>
                    </>
                  )}
                </FormField>

                {!edit ? (
                  <FormField label="Jadwal pertemuan" name="pertemuan" error={errs.pertemuan}
                    hint="Siswa mengirim progress mulai H-1 pukul 00:00 sampai H-0 pukul 23:59 WIB. Jadwal dapat diubah nanti.">
                    <label className="d-flex align-items-center mb-1" style={{ cursor: "pointer" }}>
                      <input type="radio" name="mode" className="mr-2" checked={mode === "ikut"} onChange={() => setMode("ikut")} />
                      Ikuti jadwal tugas ({tugas.jadwal.length} pertemuan)
                    </label>
                    {mode === "ikut" ? (
                      <div className="ml-4 mb-2 small text-muted">
                        {tugas.jadwal.length ? tugas.jadwal.map((t, i) => <div key={t}>Pertemuan {i + 1}: {formatTanggalPertemuan(t)}</div>) : "Tugas belum punya jadwal; tambahkan di halaman tugas (berlaku ke semua kelompok)."}
                      </div>
                    ) : null}
                    <label className="d-flex align-items-center mb-2" style={{ cursor: "pointer" }}>
                      <input type="radio" name="mode" className="mr-2" checked={mode === "sendiri"} onChange={() => setMode("sendiri")} />
                      Atur jadwal sendiri untuk kelompok ini
                    </label>
                    {mode === "sendiri" ? (
                      <div className="ml-4">
                        {tanggal.map((t, i) => (
                          <div key={i} className="d-flex align-items-center mb-2">
                            <span className="mr-2 text-muted" style={{ width: 90 }}>Pertemuan {i + 1}</span>
                            <Input type="date" value={t} onChange={(e) => setTanggal((a) => a.map((x, j) => (j === i ? e.target.value : x)))} style={{ maxWidth: 180 }} />
                            {tanggal.length > 1 ? <Button type="button" color="link" size="sm" className="text-danger" onClick={() => setTanggal((a) => a.filter((_, j) => j !== i))}>Hapus</Button> : null}
                          </div>
                        ))}
                        {tanggal.length < MAKS_PERTEMUAN ? <Button type="button" size="sm" color="info" onClick={() => setTanggal((a) => [...a, ""])}>+ Tambah pertemuan</Button> : null}
                      </div>
                    ) : null}
                  </FormField>
                ) : null}

                <div className="mt-3">
                  <Button type="submit" color="primary" className="btn-fill" disabled={menyimpan}>{menyimpan ? "Menyimpan..." : "Simpan"}</Button>
                  <Button tag={Link} to={batal} color="secondary" className="ml-2">Batal</Button>
                </div>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </form>
    </div>
  );
}

export default ProyekForm;
