import React from "react";
import { Alert, Button } from "reactstrap";

export function Loading({ text = "Memuat data..." }) {
  return (
    <div className="text-center text-muted py-5">
      <i className="tim-icons icon-refresh-02 spin mr-2" /> {text}
    </div>
  );
}

export function ErrorBox({ error, onRetry }) {
  if (!error) return null;
  return (
    <Alert color="danger" className="mb-3">
      <span>
        <b>Gagal memuat data.</b> {error.message || String(error)}
        {onRetry ? (
          <Button color="link" size="sm" className="p-0 ml-2 text-white" onClick={onRetry}>
            <u>Coba lagi</u>
          </Button>
        ) : null}
      </span>
    </Alert>
  );
}
