import React from "react";
import { Button, FormGroup, Input } from "reactstrap";

/** Gambar captcha dari SVG milik server, dirender sebagai <img> (skrip di dalam SVG tidak dijalankan). */
const srcSvg = (svg) => `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;

/**
 * Isian captcha untuk login admin & siswa. `captcha` = { enabled, captcha_id, gambar_svg } dari server;
 * tidak tampil bila server menonaktifkan captcha atau datanya belum ada.
 */
function CaptchaField({ captcha, value, onChange, onRefresh, disabled }) {
  if (!captcha?.enabled) return null;
  return (
    <FormGroup>
      <label htmlFor="captcha">Captcha</label>
      <div className="captcha-box mb-2">
        <img src={srcSvg(captcha.gambar_svg)} alt="Gambar captcha" width={150} height={50} />
        <Button type="button" color="link" size="sm" onClick={onRefresh} disabled={disabled} title="Ganti captcha">
          <i className="tim-icons icon-refresh-01" /> Ganti
        </Button>
      </div>
      <Input
        id="captcha"
        autoComplete="off"
        autoCapitalize="none"
        placeholder="Ketik huruf pada gambar"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
      />
    </FormGroup>
  );
}

export default CaptchaField;
