import React from "react";
import { Button, Modal, ModalBody, ModalFooter, ModalHeader } from "reactstrap";

/**
 * Dialog konfirmasi untuk aksi berisiko (hapus, terbitkan ulang QR, dst.).
 * `onConfirm` boleh async; tombol dikunci selama berjalan. Dialog ditutup oleh pemanggil.
 */
function ConfirmModal({
  isOpen,
  title = "Konfirmasi",
  children,
  confirmText = "Ya, lanjutkan",
  confirmColor = "danger",
  loading = false,
  onConfirm,
  onCancel,
}) {
  return (
    <Modal isOpen={isOpen} toggle={loading ? undefined : onCancel} centered>
      <ModalHeader toggle={loading ? undefined : onCancel}>{title}</ModalHeader>
      <ModalBody>{children}</ModalBody>
      <ModalFooter>
        <Button color="secondary" onClick={onCancel} disabled={loading}>
          Batal
        </Button>
        <Button color={confirmColor} onClick={onConfirm} disabled={loading}>
          {loading ? "Memproses..." : confirmText}
        </Button>
      </ModalFooter>
    </Modal>
  );
}

export default ConfirmModal;
