import React from "react";
import { Link, useParams } from "react-router-dom";
import { Alert, Button, Card, CardBody, CardHeader, CardTitle } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import ProyekBadge from "components/ProyekBadge/ProyekBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { useNotify } from "contexts/NotifyContext";
import Waktu from "utils/waktu";
import { unduhBlob } from "utils/download";
import { formatHitungMundur, formatTanggalPertemuan, formatTanggalWaktu } from "utils/format";
import BerkasList from "views/proyek/BerkasList";
import FormKirimProgress from "views/siswa/FormKirimProgress";

const slug = (s) => String(s || "proyek").normalize("NFKD").replace(/[^\w\- ]+/g, "").trim().replace(/\s+/g, "-").slice(0, 50) || "proyek";

function DetailProyek() {
  const { id } = useParams();
  const notify = useNotify();
  const [p, setP] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [unduhId, setUnduhId] = React.useState(null);
  const [mencetak, setMencetak] = React.useState(false);
  const [, setTick] = React.useState(0);

  const muat = React.useCallback(async (signal) => {
    try {
      setP(await proyekApi.detailSaya(id, signal));
      setError(null);
    } catch (err) {
      if (err.name !== "AbortError") setError(err);
    }
  }, [id]);
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    const t = setInterval(() => muat(ac.signal), 30000); // jendela pertemuan dibuka/ditutup mengikuti waktu server
    const k = setInterval(() => setTick((x) => x + 1), 15000);
    return () => { ac.abort(); clearInterval(t); clearInterval(k); };
  }, [muat]);

  const unduh = async (b) => {
    setUnduhId(b.id_berkas);
    try { unduhBlob(await proyekApi.unduhBerkasSiswa(id, b.id_berkas), b.nama); }
    catch (err) { notify.gagal(err.message); }
    finally { setUnduhId(null); }
  };

  const cetak = async () => {
    setMencetak(true);
    try {
      unduhBlob(await proyekApi.unduhLaporan(id), `laporan-proyek-${slug(p.nama_kelompok)}.pdf`);
      notify.sukses("Laporan PDF diunduh.");
    } catch (err) { notify.gagal(err.message); }
    finally { setMencetak(false); }
  };

  if (error && !p) return <><Button tag={Link} to="/siswa/proyek" color="link" className="pl-0">← Kembali</Button><ErrorBox error={error} onRetry={() => muat()} /></>;
  if (!p) return <Loading />;
  const final = p.status === "final";

  return (
    <>
      <Button tag={Link} to="/siswa/proyek" color="link" className="pl-0">← Semua proyek</Button>
      <ErrorBox error={error} onRetry={() => muat()} />
      <Card>
        <CardHeader>
          <div className="d-flex align-items-start">
            <div className="flex-grow-1">
              <CardTitle tag="h3" className="mb-1">{p.nama_kelompok}</CardTitle>
              <p className="category mb-0">{p.nama_tugas ? `${p.nama_tugas} · ` : ""}{p.nama_proyek} · Kelas {p.kelas}</p>
            </div>
            <ProyekBadge status={p.status} />
          </div>
        </CardHeader>
        <CardBody>
          {p.deskripsi ? <p style={{ whiteSpace: "pre-wrap" }}>{p.deskripsi}</p> : null}
          <h5>Anggota</h5>
          <ul className="mb-0">
            {p.anggota.map((a) => <li key={a.id_siswa}>{a.nama} <small className="text-muted">NIM {a.nim}</small></li>)}
          </ul>
        </CardBody>
      </Card>

      {final ? (
        <Alert color="success">
          <b>Proyek sudah final</b> · {formatTanggalWaktu(p.final_at)} · disahkan {p.final_oleh_nama}. Proyek tidak dapat diubah lagi.
          <div className="mt-2">
            <Button color="success" className="btn-fill" disabled={mencetak} onClick={cetak}>{mencetak ? "Menyiapkan PDF..." : "Cetak laporan (PDF)"}</Button>
          </div>
        </Alert>
      ) : null}

      <Card>
        <CardHeader><CardTitle tag="h4" className="mb-0">Berkas / Link Saat Ini</CardTitle></CardHeader>
        <CardBody>
          <BerkasList berkas={p.berkas} onUnduh={unduh} bekerja={unduhId} />
          {!final && p.berkas.length ? <small className="text-muted d-block mt-2">Kiriman progress berikutnya akan menggantikan seluruh berkas/link di atas.</small> : null}
        </CardBody>
      </Card>

      <Card>
        <CardHeader><CardTitle tag="h4" className="mb-0">Log Aktivitas</CardTitle></CardHeader>
        <CardBody>
          {p.pertemuan.length === 0 ? <p className="text-muted mb-0">Belum ada pertemuan yang dijadwalkan.</p> : null}
          {p.pertemuan.map((t) => {
            const sisa = new Date(t.tutup_at).getTime() - Waktu.now();
            return (
              <div key={t.nomor} className="mb-4 pb-3" style={{ borderBottom: "1px solid rgba(255,255,255,.08)" }}>
                <div className="d-flex align-items-center flex-wrap">
                  <h5 className="mb-0 mr-2">Pertemuan {t.nomor}</h5>
                  <ProyekBadge status={t.status} pertemuan />
                  {t.perlu_revisi ? <span className="badge badge-warning badge-pill ml-2">Perlu revisi</span> : null}
                </div>
                <small className="text-muted d-block mb-2">{formatTanggalPertemuan(t.tanggal)}</small>

                {t.status === "belum_dibuka" ? <p className="text-muted mb-1">Pengiriman dibuka {formatTanggalWaktu(t.buka_at)} (H-1) dan ditutup {formatTanggalWaktu(t.tutup_at)}.</p> : null}
                {t.status === "terlewat" ? <p className="text-danger mb-1">Waktu pengiriman berakhir {formatTanggalWaktu(t.tutup_at)}; tidak ada progress yang dikirim.</p> : null}
                {t.dikirim_at ? (
                  <>
                    <p className="mb-1" style={{ whiteSpace: "pre-wrap" }}>{t.progress}</p>
                    <small className="text-muted">Dikirim oleh {t.dikirim_oleh} · {formatTanggalWaktu(t.dikirim_at)}</small>
                  </>
                ) : null}
                {t.komentar ? (
                  <Alert color={t.perlu_revisi ? "warning" : "info"} className="mt-2 mb-0">
                    <b>{t.perlu_revisi ? "Perbaikan diminta" : "Komentar dosen"}</b> <small>({t.komentar_oleh})</small>
                    <div style={{ whiteSpace: "pre-wrap" }}>{t.komentar}</div>
                  </Alert>
                ) : null}

                {t.status === "terbuka" ? (
                  <>
                    <Alert color="success" className="mt-2 mb-0 py-2">
                      Pengiriman <b>dibuka</b> · ditutup {formatTanggalWaktu(t.tutup_at)} (sisa {formatHitungMundur(sisa)}).
                    </Alert>
                    <FormKirimProgress proyek={p} pertemuan={t} onTerkirim={() => muat()} />
                  </>
                ) : null}
              </div>
            );
          })}
        </CardBody>
      </Card>
    </>
  );
}

export default DetailProyek;
