import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { Button, Card, CardBody, CardHeader, CardTitle, Col, Input, Row } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import * as siswaApi from "services/siswaApi";
import FormField from "components/FormField/FormField";
import { ErrorBox } from "components/Feedback/Feedback";
import { useNotify } from "contexts/NotifyContext";
import { formatTanggalPertemuan } from "utils/format";

const MAKS_PERTEMUAN = 30;

/** Tugas baru: nama tugas + kelas + jadwal pertemuan bawaan (disalin ke tiap kelompok yang dibuat). */
function TugasForm() {
  const navigate = useNavigate();
  const notify = useNotify();
  const [kelasList, setKelasList] = React.useState([]);
  const [nama, setNama] = React.useState("");
  const [kelas, setKelas] = React.useState("");
  const [tanggal, setTanggal] = React.useState([""]);
  const [errs, setErrs] = React.useState({});
  const [error, setError] = React.useState(null);
  const [menyimpan, setMenyimpan] = React.useState(false);

  React.useEffect(() => {
    siswaApi.daftarKelas().then((k) => setKelasList(k.filter((x) => x.aktif > 0))).catch(setError);
  }, []);

  const validasi = () => {
    const e = {};
    if (nama.trim().length < 3) e.nama = "Nama tugas minimal 3 karakter.";
    if (!kelas) e.kelas = "Pilih kelas.";
    const t = tanggal.filter(Boolean);
    for (let i = 1; i < t.length; i++) if (t[i] <= t[i - 1]) { e.jadwal = "Tanggal pertemuan harus berurutan dan tidak boleh sama."; break; }
    setErrs(e);
    return Object.keys(e).length === 0;
  };

  const simpan = async (ev) => {
    ev.preventDefault();
    if (!validasi()) return;
    setMenyimpan(true);
    try {
      const t = await proyekApi.createTugas({ nama_tugas: nama.trim(), kelas, jadwal: tanggal.filter(Boolean) });
      notify.sukses("Tugas dibuat. Sekarang tambahkan kelompok.");
      navigate(`/admin/tugas/${t.id_tugas}`);
    } catch (err) {
      notify.gagal(err.message);
    } finally {
      setMenyimpan(false);
    }
  };

  return (
    <div className="content">
      <form onSubmit={simpan} noValidate>
        <Row>
          <Col lg="8">
            <Card>
              <CardHeader><CardTitle tag="h4" className="mb-0">Tugas Proyek Baru</CardTitle></CardHeader>
              <CardBody>
                <ErrorBox error={error} />
                <FormField label="Nama tugas" name="nama_tugas" required value={nama} onChange={(e) => setNama(e.target.value)} error={errs.nama} maxLength={150} hint='Contoh: "Proyek Akhir Semester". Nama proyek tiap kelompok diisi saat membuat kelompok.' />
                <FormField label="Kelas" name="kelas" required error={errs.kelas} hint="Kelas tidak dapat diubah setelah tugas dibuat. Satu siswa hanya boleh di satu kelompok dalam satu tugas.">
                  <Input type="select" id="kelas" value={kelas} onChange={(e) => setKelas(e.target.value)} invalid={!!errs.kelas}>
                    <option value="">Pilih kelas...</option>
                    {kelasList.map((k) => <option key={k.kelas} value={k.kelas}>{k.kelas} ({k.aktif} siswa aktif)</option>)}
                  </Input>
                </FormField>
                <FormField label="Jadwal pertemuan bawaan (opsional)" name="jadwal" error={errs.jadwal}
                  hint="Disalin ke setiap kelompok baru; kelompok boleh memakai jadwal sendiri. Siswa mengirim progress mulai H-1 pukul 00:00 sampai H-0 pukul 23:59 WIB. Dapat diubah atau ditambah nanti.">
                  {tanggal.map((t, i) => (
                    <div key={i} className="d-flex align-items-center mb-2">
                      <span className="mr-2 text-muted" style={{ width: 90 }}>Pertemuan {i + 1}</span>
                      <Input type="date" value={t} onChange={(e) => setTanggal((a) => a.map((x, j) => (j === i ? e.target.value : x)))} style={{ maxWidth: 180 }} />
                      <small className="text-muted ml-2 d-none d-md-inline">{t ? formatTanggalPertemuan(t) : ""}</small>
                      {tanggal.length > 1 ? <Button type="button" color="link" size="sm" className="text-danger" onClick={() => setTanggal((a) => a.filter((_, j) => j !== i))}>Hapus</Button> : null}
                    </div>
                  ))}
                  {tanggal.length < MAKS_PERTEMUAN ? <Button type="button" size="sm" color="info" onClick={() => setTanggal((a) => [...a, ""])}>+ Tambah pertemuan</Button> : null}
                </FormField>
                <div className="mt-3">
                  <Button type="submit" color="primary" className="btn-fill" disabled={menyimpan}>{menyimpan ? "Menyimpan..." : "Simpan"}</Button>
                  <Button tag={Link} to="/admin/tugas" color="secondary" className="ml-2">Batal</Button>
                </div>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </form>
    </div>
  );
}
export default TugasForm;
