import React from "react";
import NotificationAlert from "react-notification-alert";

const NotifyContext = React.createContext({ sukses() {}, gagal() {}, info() {} });

/** Toast global (react-notification-alert bawaan template). */
export function NotifyProvider({ children }) {
  const ref = React.useRef(null);

  const tampil = React.useCallback((type, message, autoDismiss = 5) => {
    ref.current?.notificationAlert({
      place: "tc",
      message: <div>{message}</div>,
      type,
      icon: "tim-icons icon-bell-55",
      autoDismiss,
    });
  }, []);

  const value = React.useMemo(
    () => ({
      sukses: (m) => tampil("success", m),
      gagal: (m) => tampil("danger", m, 8),
      info: (m) => tampil("info", m),
    }),
    [tampil]
  );

  return (
    <NotifyContext.Provider value={value}>
      <div className="rna-container">
        <NotificationAlert ref={ref} />
      </div>
      {children}
    </NotifyContext.Provider>
  );
}

export const useNotify = () => React.useContext(NotifyContext);
