import React from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { Alert, Button, Card, CardBody, CardHeader, CardTitle, Col, Input, Modal, ModalBody, ModalFooter, ModalHeader, Row } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import ConfirmModal from "components/ConfirmModal/ConfirmModal";
import FormField from "components/FormField/FormField";
import ProyekBadge from "components/ProyekBadge/ProyekBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { useAuth } from "contexts/AuthContext";
import { useNotify } from "contexts/NotifyContext";
import { unduhBlob } from "utils/download";
import { formatTanggalPertemuan, formatTanggalWaktu, slugNama } from "utils/format";
import BerkasList from "views/proyek/BerkasList";

function ProyekDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const notify = useNotify();
  const { admin } = useAuth();
  const [p, setP] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [tanggalBaru, setTanggalBaru] = React.useState("");
  const [bekerja, setBekerja] = React.useState(false);
  const [unduhId, setUnduhId] = React.useState(null);
  const [komentar, setKomentar] = React.useState(null); // { nomor, komentar, perlu_revisi }
  const [ubah, setUbah] = React.useState(null); // { nomor, tanggal }
  const [konfirmasi, setKonfirmasi] = React.useState(null); // "final" | "buka" | "hapus" | { hapusPertemuan: nomor }
  const [mencetak, setMencetak] = React.useState(false);

  const muat = React.useCallback(async (signal) => {
    try {
      setP(await proyekApi.get(id, signal));
      setError(null);
    } catch (err) {
      if (err.name !== "AbortError") setError(err);
    }
  }, [id]);
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    const t = setInterval(() => muat(ac.signal), 30000); // status pertemuan mengikuti waktu server
    return () => { ac.abort(); clearInterval(t); };
  }, [muat]);

  const jalankan = async (fn, pesan) => {
    setBekerja(true);
    try {
      const hasil = await fn();
      if (hasil && hasil.id_proyek) setP(hasil); else await muat();
      if (pesan) notify.sukses(pesan);
      return true;
    } catch (err) {
      notify.gagal(err.message);
      muat();
      return false;
    } finally {
      setBekerja(false);
    }
  };

  const unduh = async (b) => {
    setUnduhId(b.id_berkas);
    try { unduhBlob(await proyekApi.unduhBerkasAdmin(id, b.id_berkas), b.nama); }
    catch (err) { notify.gagal(err.message); }
    finally { setUnduhId(null); }
  };

  const cetak = async () => {
    setMencetak(true);
    try { unduhBlob(await proyekApi.unduhLaporanAdmin(id), `laporan-proyek-${slugNama(p.nama_kelompok)}.pdf`); notify.sukses("Laporan PDF diunduh."); }
    catch (err) { notify.gagal(err.message); }
    finally { setMencetak(false); }
  };

  if (error && !p) return <div className="content"><ErrorBox error={error} onRetry={() => muat()} /></div>;
  if (!p) return <div className="content"><Loading /></div>;

  const final = p.status === "final";
  const terakhir = p.pertemuan[p.pertemuan.length - 1];
  const bisaHapusTerakhir = !final && terakhir && !terakhir.dikirim_at;

  return (
    <div className="content">
      <ErrorBox error={error} onRetry={() => muat()} />
      <Button tag={Link} to={`/admin/tugas/${p.id_tugas}`} color="link" className="pl-0 mb-2">← {p.nama_tugas || "Tugas"} (semua kelompok)</Button>
      <Row>
        <Col lg="8">
          <Card>
            <CardHeader>
              <Row className="align-items-start">
                <Col>
                  <CardTitle tag="h4" className="mb-1">{p.nama_kelompok} <ProyekBadge status={p.status} className="ml-2" /></CardTitle>
                  <p className="category mb-0">{p.nama_proyek} · Kelas {p.kelas}</p>
                </Col>
                <Col xs="auto">
                  {!final ? (
                    <>
                      <Button tag={Link} to={`/admin/tugas/kelompok/${p.id_proyek}/edit`} color="info" size="sm">Ubah</Button>
                      <Button color="danger" size="sm" className="ml-2" onClick={() => setKonfirmasi("hapus")}>Hapus</Button>
                    </>
                  ) : null}
                </Col>
              </Row>
            </CardHeader>
            <CardBody>
              {p.deskripsi ? <p style={{ whiteSpace: "pre-wrap" }}>{p.deskripsi}</p> : <p className="text-muted">Tanpa deskripsi.</p>}
              <h5 className="mt-3">Anggota ({p.anggota.length})</h5>
              <ul className="mb-0">
                {p.anggota.map((a) => <li key={a.id_siswa}>{a.nama} <small className="text-muted">NIM {a.nim}{a.aktif ? "" : " · nonaktif"}</small></li>)}
              </ul>
            </CardBody>
          </Card>

          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col><CardTitle tag="h4" className="mb-0">Log Aktivitas</CardTitle></Col>
                {!final ? (
                  <Col xs="auto" className="d-flex align-items-center">
                    <Input type="date" bsSize="sm" value={tanggalBaru} onChange={(e) => setTanggalBaru(e.target.value)} style={{ maxWidth: 170 }} />
                    <Button size="sm" color="primary" className="ml-2" disabled={bekerja || !tanggalBaru}
                      onClick={async () => { if (await jalankan(() => proyekApi.tambahPertemuan(id, tanggalBaru), "Pertemuan ditambahkan.")) setTanggalBaru(""); }}>
                      + Pertemuan
                    </Button>
                  </Col>
                ) : null}
              </Row>
              {!final ? <p className="category mt-2 mb-0">Siswa mengirim progress mulai H-1 pukul 00:00 s.d. H-0 pukul 23:59 WIB. Satu kali per pertemuan, oleh satu anggota.</p> : null}
            </CardHeader>
            <CardBody>
              {p.pertemuan.length === 0 ? <p className="text-muted mb-0">Belum ada pertemuan. Tambahkan tanggal pertemuan di atas.</p> : null}
              {p.pertemuan.map((t) => (
                <div key={t.nomor} className="mb-4 pb-3" style={{ borderBottom: "1px solid rgba(255,255,255,.08)" }}>
                  <div className="d-flex align-items-center flex-wrap">
                    <h5 className="mb-0 mr-2">Pertemuan {t.nomor}</h5>
                    <ProyekBadge status={t.status} pertemuan />
                    {t.perlu_revisi ? <span className="badge badge-warning badge-pill ml-2">Perlu revisi</span> : null}
                    <span className="flex-grow-1" />
                    {!final ? (
                      <>
                        <Button size="sm" color="info" className="mr-1" onClick={() => setKomentar({ nomor: t.nomor, komentar: t.komentar || "", perlu_revisi: t.perlu_revisi })}>Komentar</Button>
                        {!t.dikirim_at ? <Button size="sm" color="secondary" className="mr-1" onClick={() => setUbah({ nomor: t.nomor, tanggal: t.tanggal })}>Ubah tanggal</Button> : null}
                        {bisaHapusTerakhir && t.nomor === terakhir.nomor ? <Button size="sm" color="danger" onClick={() => setKonfirmasi({ hapusPertemuan: t.nomor })}>Hapus</Button> : null}
                      </>
                    ) : null}
                  </div>
                  <small className="text-muted d-block mb-2">
                    {formatTanggalPertemuan(t.tanggal)} · jendela: {formatTanggalWaktu(t.buka_at)} s.d. {formatTanggalWaktu(t.tutup_at)}
                  </small>
                  {t.dikirim_at ? (
                    <>
                      <p className="mb-1" style={{ whiteSpace: "pre-wrap" }}>{t.progress}</p>
                      <small className="text-muted">Dikirim oleh {t.dikirim_oleh} · {formatTanggalWaktu(t.dikirim_at)}</small>
                    </>
                  ) : (
                    <p className="text-muted mb-1">Belum ada progress dikirim.</p>
                  )}
                  {t.komentar ? (
                    <Alert color={t.perlu_revisi ? "warning" : "info"} className="mt-2 mb-0">
                      <b>{t.perlu_revisi ? "Perbaikan diminta" : "Komentar"}</b> <small>({t.komentar_oleh}, {formatTanggalWaktu(t.komentar_at)})</small>
                      <div style={{ whiteSpace: "pre-wrap" }}>{t.komentar}</div>
                    </Alert>
                  ) : null}
                </div>
              ))}
            </CardBody>
          </Card>
        </Col>

        <Col lg="4">
          <Card>
            <CardHeader><CardTitle tag="h4" className="mb-0">Berkas / Link Saat Ini</CardTitle></CardHeader>
            <CardBody>
              <BerkasList berkas={p.berkas} onUnduh={unduh} bekerja={unduhId} />
              {p.jumlah_pengiriman > 1 ? <small className="text-muted d-block mt-3">Dikirim {p.jumlah_pengiriman}× · {p.jumlah_pengiriman - 1} kali kirim ulang. Setiap kiriman menimpa berkas sebelumnya.</small> : null}
            </CardBody>
          </Card>

          <Card>
            <CardHeader><CardTitle tag="h4" className="mb-0">Pengesahan</CardTitle></CardHeader>
            <CardBody>
              {final ? (
                <>
                  <p className="mb-1"><b>Final</b> · {formatTanggalWaktu(p.final_at)}</p>
                  <p className="mb-2">Dosen pengampu: <b>{p.final_oleh_nama}</b></p>
                  <small className="text-muted d-block mb-3">Kelompok terkunci. Anggota dan admin dapat mencetak laporan PDF bertanda tangan QR.</small>
                  <Button color="success" className="btn-fill mr-2 mb-2" disabled={mencetak} onClick={cetak}>{mencetak ? "Menyiapkan PDF..." : "Cetak laporan (PDF)"}</Button>
                  <Button color="warning" className="mb-2" disabled={bekerja} onClick={() => setKonfirmasi("buka")}>Buka kembali final</Button>
                </>
              ) : (
                <>
                  <p className="text-muted">Setelah difinalkan, proyek tidak dapat diubah (berkas, pertemuan, komentar) dan siswa dapat mencetak laporan.</p>
                  <p className="small mb-3">Dosen pengampu pada tanda tangan QR: <b>{admin?.nama || "akun Anda"}</b> (admin yang memfinalkan).</p>
                  {p.jumlah_buka_kembali ? <p className="small text-warning">Final pernah dibuka kembali {p.jumlah_buka_kembali}×.</p> : null}
                  <Button color="success" className="btn-fill" disabled={bekerja || p.berkas.length === 0} onClick={() => setKonfirmasi("final")}>Finalkan proyek</Button>
                  {p.berkas.length === 0 ? <small className="text-warning d-block mt-2">Belum bisa difinalkan: belum ada berkas/link.</small> : null}
                </>
              )}
            </CardBody>
          </Card>
        </Col>
      </Row>

      {/* Komentar / perlu revisi */}
      <Modal isOpen={!!komentar} toggle={() => setKomentar(null)} centered>
        <ModalHeader toggle={() => setKomentar(null)}>Komentar — Pertemuan {komentar?.nomor}</ModalHeader>
        <ModalBody>
          <FormField label="Perbaikan / komentar" name="komentar" type="textarea" rows={5} maxLength={1000}
            value={komentar?.komentar || ""} onChange={(e) => setKomentar((k) => ({ ...k, komentar: e.target.value }))}
            hint="Dikosongkan = menghapus komentar." />
          <label className="d-flex align-items-center mb-0" style={{ cursor: "pointer" }}>
            <input type="checkbox" className="mr-2" checked={!!komentar?.perlu_revisi} onChange={(e) => setKomentar((k) => ({ ...k, perlu_revisi: e.target.checked }))} />
            Tandai perlu revisi (kelompok mengirim ulang di pertemuan berikutnya)
          </label>
        </ModalBody>
        <ModalFooter>
          <Button color="secondary" onClick={() => setKomentar(null)}>Batal</Button>
          <Button color="primary" disabled={bekerja || (komentar?.perlu_revisi && !komentar?.komentar.trim())}
            onClick={async () => { if (await jalankan(() => proyekApi.komentar(id, komentar.nomor, { komentar: komentar.komentar, perlu_revisi: !!komentar.perlu_revisi }), "Komentar disimpan.")) setKomentar(null); }}>
            Simpan
          </Button>
        </ModalFooter>
      </Modal>

      {/* Ubah tanggal pertemuan */}
      <Modal isOpen={!!ubah} toggle={() => setUbah(null)} centered>
        <ModalHeader toggle={() => setUbah(null)}>Ubah tanggal — Pertemuan {ubah?.nomor}</ModalHeader>
        <ModalBody>
          <FormField label="Tanggal pertemuan" name="tgl" type="date" value={ubah?.tanggal || ""} onChange={(e) => setUbah((u) => ({ ...u, tanggal: e.target.value }))}
            hint="Tanggal harus berurutan dengan pertemuan lain. Jendela pengiriman ikut berubah." />
        </ModalBody>
        <ModalFooter>
          <Button color="secondary" onClick={() => setUbah(null)}>Batal</Button>
          <Button color="primary" disabled={bekerja || !ubah?.tanggal}
            onClick={async () => { if (await jalankan(() => proyekApi.ubahPertemuan(id, ubah.nomor, ubah.tanggal), "Tanggal diperbarui.")) setUbah(null); }}>
            Simpan
          </Button>
        </ModalFooter>
      </Modal>

      <ConfirmModal isOpen={konfirmasi === "final"} title="Finalkan proyek?" confirmText="Ya, finalkan" confirmColor="success" loading={bekerja}
        onCancel={() => setKonfirmasi(null)}
        onConfirm={async () => { if (await jalankan(() => proyekApi.finalkan(id), "Proyek difinalkan.")) setKonfirmasi(null); }}>
        Setelah final, proyek <b>tidak dapat diubah lagi</b>: berkas, pertemuan, dan komentar terkunci. Nama dosen pengampu pada laporan adalah <b>{admin?.nama}</b>. Tindakan ini tidak dapat dibatalkan.
      </ConfirmModal>
      <ConfirmModal isOpen={konfirmasi === "buka"} title="Buka kembali final?" confirmText="Ya, buka kembali" confirmColor="warning" loading={bekerja}
        onCancel={() => setKonfirmasi(null)}
        onConfirm={async () => { if (await jalankan(() => proyekApi.bukaKembali(id), "Final dibuka kembali.")) setKonfirmasi(null); }}>
        Kelompok <b>{p.nama_kelompok}</b> kembali berstatus berjalan. <b>QR pada laporan PDF yang sudah tercetak tidak akan valid lagi</b>, dan finalisasi berikutnya membuat QR baru. Jendela pengiriman pertemuan yang sudah lewat <b>tidak ikut terbuka</b>: tambah atau ubah pertemuan agar kelompok dapat mengirim lagi. Berkas yang ada tetap tersimpan.
      </ConfirmModal>
      <ConfirmModal isOpen={konfirmasi === "hapus"} title="Hapus kelompok?" confirmText="Ya, hapus" loading={bekerja}
        onCancel={() => setKonfirmasi(null)}
        onConfirm={async () => { setBekerja(true); try { await proyekApi.remove(id); notify.sukses("Proyek dihapus."); navigate(`/admin/tugas/${p.id_tugas}`); } catch (err) { notify.gagal(err.message); setBekerja(false); } }}>
        Kelompok <b>{p.nama_kelompok}</b> beserta seluruh berkas yang sudah diunggah akan dihapus permanen.
      </ConfirmModal>
      <ConfirmModal isOpen={!!konfirmasi?.hapusPertemuan} title="Hapus pertemuan?" confirmText="Ya, hapus" loading={bekerja}
        onCancel={() => setKonfirmasi(null)}
        onConfirm={async () => { if (await jalankan(() => proyekApi.hapusPertemuan(id, konfirmasi.hapusPertemuan), "Pertemuan dihapus.")) setKonfirmasi(null); }}>
        Pertemuan {konfirmasi?.hapusPertemuan} belum menerima progress dan akan dihapus.
      </ConfirmModal>
    </div>
  );
}

export default ProyekDetail;
