import React from "react";
import { Link } from "react-router-dom";
import { Button, Card, CardBody, Col, Row } from "reactstrap";
import * as pesertaApi from "services/pesertaApi";
import Waktu from "utils/waktu";
import StatusBadge from "components/StatusBadge/StatusBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { MODE_NILAI, formatHitungMundur, formatTanggalWaktu } from "utils/format";

function KartuKuis({ k }) {
  const mulai = new Date(k.mulai_at).getTime();
  const sisaMulai = mulai - Waktu.now();
  const bolehHasil = k.status === "finished" && k.publikasi_hasil !== "disembunyikan";
  return (
    <Card className="kuis-card">
      <CardBody>
        <div className="d-flex align-items-start">
          <div className="flex-grow-1">
            <h4 className="mb-1">{k.judul}</h4>
            <p className="category mb-2">{k.mapel || "Tanpa mapel"}</p>
          </div>
          <StatusBadge status={k.status} />
        </div>
        {k.deskripsi ? <p className="text-muted">{k.deskripsi}</p> : null}
        <ul className="list-unstyled small mb-3">
          <li>Mulai: <b>{formatTanggalWaktu(k.mulai_at)}</b></li>
          <li>Selesai paling lambat: {formatTanggalWaktu(k.akhir_efektif)}</li>
          <li>{k.jumlah_soal} soal · {k.durasi_soal_detik} detik per soal</li>
          <li>Penilaian: {MODE_NILAI[k.mode_nilai] || MODE_NILAI.kecepatan}</li>
          {k.status === "scheduled" ? <li className="text-info">Dimulai dalam {formatHitungMundur(sisaMulai)}</li> : null}
        </ul>
        {k.status === "live" ? (
          <Button tag={Link} to={`/siswa/kuis/${k.id_kuis}`} color="success" className="btn-fill">
            Masuk ruang kuis (sedang berlangsung)
          </Button>
        ) : null}
        {k.status === "scheduled" ? (
          <Button tag={Link} to={`/siswa/kuis/${k.id_kuis}`} color="info">
            Buka ruang tunggu
          </Button>
        ) : null}
        {bolehHasil ? (
          <Button tag={Link} to={`/siswa/kuis/${k.id_kuis}/hasil`} color="primary" className="btn-fill">
            Lihat hasil
          </Button>
        ) : null}
        {k.status === "finished" && !bolehHasil ? (
          <span className="text-muted">Hasil tidak dipublikasikan oleh admin.</span>
        ) : null}
      </CardBody>
    </Card>
  );
}

function DaftarKuis() {
  const [data, setData] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [, setTick] = React.useState(0);

  const muat = React.useCallback(async (signal) => {
    try {
      const r = await pesertaApi.daftarKuis(signal);
      Waktu.dariSnapshot(r.server_now);
      setData(r.kuis);
      setError(null);
    } catch (err) {
      if (err.name !== "AbortError") setError(err);
    }
  }, []);

  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    const poll = setInterval(() => muat(ac.signal), 10000); // status berubah menurut waktu server
    const tick = setInterval(() => setTick((t) => t + 1), 1000); // hitung mundur
    return () => {
      ac.abort();
      clearInterval(poll);
      clearInterval(tick);
    };
  }, [muat]);

  const urut = React.useMemo(() => {
    const bobot = { live: 0, scheduled: 1, finished: 2 };
    return [...(data || [])].sort(
      (a, b) => (bobot[a.status] ?? 3) - (bobot[b.status] ?? 3) || new Date(b.mulai_at) - new Date(a.mulai_at)
    );
  }, [data]);

  return (
    <>
      <div className="mb-3">
        <h2 className="mb-0">Kuis untuk Anda</h2>
        <p className="text-muted">Kuis dari kelas Anda. Soal muncul otomatis pada jadwal yang ditentukan.</p>
      </div>
      <ErrorBox error={error} onRetry={() => muat()} />
      {!data && !error ? <Loading /> : null}
      {data && data.length === 0 ? (
        <Card>
          <CardBody className="text-center text-muted py-5">Belum ada kuis untuk kelas Anda.</CardBody>
        </Card>
      ) : null}
      <Row>
        {urut.map((k) => (
          <Col key={k.id_kuis} md="6">
            <KartuKuis k={k} />
          </Col>
        ))}
      </Row>
    </>
  );
}

export default DaftarKuis;
