import React from "react";
import { Link, useParams } from "react-router-dom";
import { Alert, Badge, Button, Card, CardBody, CardHeader, CardTitle, Col, Row, Table } from "reactstrap";
import * as pesertaApi from "services/pesertaApi";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { formatAngka } from "utils/format";

function Ringkas({ label, nilai, warna }) {
  return (
    <Col xs="6" md="3">
      <Card className="mb-3">
        <CardBody className="text-center py-3">
          <div className={`kuis-besar-kecil ${warna || ""}`}>{nilai}</div>
          <small className="text-muted">{label}</small>
        </CardBody>
      </Card>
    </Col>
  );
}

function HasilSiswa() {
  const { id } = useParams();
  const [kuis, setKuis] = React.useState(null);
  const [hasil, setHasil] = React.useState(null);
  const [lb, setLb] = React.useState(null);
  const [pesanHasil, setPesanHasil] = React.useState("");
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  const muat = React.useCallback(
    async (signal) => {
      setLoading(true);
      setError(null);
      setPesanHasil("");
      try {
        const d = await pesertaApi.detailKuis(id, signal);
        setKuis(d.kuis);
        // 403 HASIL_DISEMBUNYIKAN / HASIL_BELUM_TERSEDIA adalah kondisi normal, bukan galat.
        try {
          setHasil(await pesertaApi.hasil(id, signal));
        } catch (err) {
          if (err.name === "AbortError") throw err;
          if (err.status === 403) setPesanHasil(err.message);
          else throw err;
        }
        if (d.kuis.tampilkan_leaderboard && d.kuis.status === "finished") {
          try {
            setLb(await pesertaApi.leaderboard(id, signal));
          } catch (err) {
            if (err.name === "AbortError") throw err;
            if (err.status !== 403) throw err;
          }
        }
      } catch (err) {
        if (err.name !== "AbortError") setError(err);
      } finally {
        if (!signal?.aborted) setLoading(false);
      }
    },
    [id]
  );
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    return () => ac.abort();
  }, [muat]);

  if (loading) return <Loading />;

  return (
    <>
      <div className="d-flex align-items-center mb-3">
        <div className="flex-grow-1">
          <h2 className="mb-0">{kuis?.judul || "Hasil kuis"}</h2>
          <p className="text-muted mb-0">Hasil Anda</p>
        </div>
        <Button tag={Link} to="/siswa/kuis" color="secondary" size="sm">Daftar kuis</Button>
      </div>
      <ErrorBox error={error} onRetry={() => muat()} />
      {pesanHasil ? <Alert color="info">{pesanHasil}</Alert> : null}

      {hasil ? (
        <>
          <Row>
            <Ringkas label="Skor" nilai={formatAngka(hasil.skor)} warna="text-info" />
            <Ringkas label="Benar" nilai={hasil.benar} warna="text-success" />
            <Ringkas label="Salah" nilai={hasil.salah} warna="text-danger" />
            <Ringkas label="Tidak dijawab" nilai={hasil.tidak_dijawab} />
          </Row>
          {hasil.status_hasil === "sementara" ? (
            <Alert color="warning">
              Hasil masih <b>sementara</b>
              {hasil.pending_review > 0 ? ` — ${hasil.pending_review} jawaban menunggu pemeriksaan admin` : ""}. Nilai bisa
              berubah sampai semua soal final.
            </Alert>
          ) : null}
          <Card>
            <CardHeader>
              <CardTitle tag="h4" className="mb-0">Rincian per soal</CardTitle>
            </CardHeader>
            <CardBody>
              {hasil.per_soal.length === 0 ? (
                <p className="text-muted mb-0">Belum ada soal yang dihitung untuk Anda.</p>
              ) : (
                <Table responsive>
                  <thead className="text-primary">
                    <tr>
                      <th>#</th>
                      <th>Soal</th>
                      <th>Jawaban</th>
                      <th className="text-right">Urutan benar</th>
                      <th className="text-right">Nilai</th>
                    </tr>
                  </thead>
                  <tbody>
                    {hasil.per_soal.map((p) => (
                      <tr key={p.nomor}>
                        <td>{p.nomor}</td>
                        <td style={{ whiteSpace: "normal", minWidth: 200 }}>{p.teks}</td>
                        <td>
                          {!p.dijawab ? (
                            <Badge color="default" pill>Tidak dijawab</Badge>
                          ) : p.benar === null ? (
                            <Badge color="warning" pill>Menunggu</Badge>
                          ) : p.benar ? (
                            <Badge color="success" pill>Benar</Badge>
                          ) : (
                            <Badge color="danger" pill>Salah</Badge>
                          )}
                        </td>
                        <td className="text-right">{p.urutan_benar ?? "-"}</td>
                        <td className="text-right">
                          {formatAngka(p.nilai)}
                          {p.status === "sementara" ? <small className="text-muted"> (sementara)</small> : null}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              )}
            </CardBody>
          </Card>
        </>
      ) : null}

      {lb ? (
        <Card>
          <CardHeader>
            <CardTitle tag="h4" className="mb-0">
              Papan peringkat {lb.status === "sementara" ? <small className="text-muted">(sementara)</small> : null}
            </CardTitle>
            {lb.saya ? <p className="category mb-0">Peringkat Anda: #{lb.saya}</p> : null}
          </CardHeader>
          <CardBody>
            <Table responsive>
              <thead className="text-primary">
                <tr>
                  <th>#</th>
                  <th>Nama</th>
                  <th>Kelas</th>
                  <th className="text-right">Skor</th>
                  <th className="text-right">Benar</th>
                </tr>
              </thead>
              <tbody>
                {lb.peringkat.map((b) => (
                  <tr key={b.peringkat} className={b.saya ? "baris-saya" : ""}>
                    <td>{b.peringkat}</td>
                    <td>{b.nama} {b.saya ? <Badge color="info" className="ml-1">Anda</Badge> : null}</td>
                    <td>{b.kelas}</td>
                    <td className="text-right">{formatAngka(b.skor)}</td>
                    <td className="text-right">{b.benar}</td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </CardBody>
        </Card>
      ) : null}
    </>
  );
}

export default HasilSiswa;
