import React from "react";
import { Link } from "react-router-dom";
import { Button, Card, CardBody, CardHeader, CardTitle, Col, Input, Row, Table } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import * as siswaApi from "services/siswaApi";
import Pager from "components/Pager/Pager";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import useDebounce from "hooks/useDebounce";
import { formatTanggalWaktu } from "utils/format";

function TugasList() {
  const [kelas, setKelas] = React.useState("");
  const [cari, setCari] = React.useState("");
  const [page, setPage] = React.useState(1);
  const q = useDebounce(cari, 400);
  const [daftarKelas, setDaftarKelas] = React.useState([]);
  const [data, setData] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => { siswaApi.daftarKelas().then(setDaftarKelas).catch(() => {}); }, []);

  const muat = React.useCallback(async (signal) => {
    setLoading(true);
    setError(null);
    try {
      setData(await proyekApi.listTugas({ kelas, q: q.trim(), page }, signal));
    } catch (err) {
      if (err.name !== "AbortError") setError(err);
    } finally {
      if (!signal?.aborted) setLoading(false);
    }
  }, [kelas, q, page]);
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    return () => ac.abort();
  }, [muat]);
  React.useEffect(() => setPage(1), [kelas, q]);

  const meta = data ? { page: data.page, limit: data.limit, total: data.total, total_halaman: Math.max(1, Math.ceil(data.total / data.limit)) } : null;

  return (
    <div className="content">
      <Row>
        <Col xs="12">
          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col>
                  <CardTitle tag="h4" className="mb-0">Tugas Proyek</CardTitle>
                  <p className="category mb-0">Satu tugas per kelas, berisi beberapa kelompok{data ? ` · ${data.total} tugas` : ""}</p>
                </Col>
                <Col xs="auto">
                  <Button tag={Link} to="/admin/tugas/baru" color="primary" className="btn-fill"><i className="tim-icons icon-simple-add" /> Tugas baru</Button>
                </Col>
              </Row>
              <Row className="mt-3">
                <Col md="4" className="mb-2">
                  <Input type="select" value={kelas} onChange={(e) => setKelas(e.target.value)}>
                    <option value="">Semua kelas</option>
                    {daftarKelas.map((k) => <option key={k.kelas} value={k.kelas}>{k.kelas}</option>)}
                  </Input>
                </Col>
                <Col md="8" className="mb-2"><Input placeholder="Cari nama tugas" value={cari} onChange={(e) => setCari(e.target.value)} /></Col>
              </Row>
            </CardHeader>
            <CardBody>
              <ErrorBox error={error} onRetry={() => muat()} />
              {loading && !data ? <Loading /> : (
                <Table responsive>
                  <thead className="text-primary"><tr><th>Nama tugas</th><th>Kelas</th><th>Kelompok</th><th>Pertemuan</th><th>Dibuat</th></tr></thead>
                  <tbody>
                    {(data?.tugas || []).map((t) => (
                      <tr key={t.id_tugas}>
                        <td style={{ whiteSpace: "normal", minWidth: 220 }}><Link className="table-link" to={`/admin/tugas/${t.id_tugas}`}>{t.nama_tugas}</Link></td>
                        <td>{t.kelas}</td>
                        <td>{t.jumlah_kelompok}{t.jumlah_final ? <span className="sub text-success">{t.jumlah_final} final</span> : null}</td>
                        <td>{t.jumlah_pertemuan}</td>
                        <td>{formatTanggalWaktu(t.createdAt)}<span className="sub">{t.dibuat_oleh}</span></td>
                      </tr>
                    ))}
                    {data && data.tugas.length === 0 ? <tr><td colSpan="5" className="text-center text-muted py-4">Belum ada tugas{kelas || q ? " yang cocok dengan filter" : ". Buat tugas baru untuk memulai"}.</td></tr> : null}
                  </tbody>
                </Table>
              )}
              <Pager meta={meta} onPage={setPage} />
            </CardBody>
          </Card>
        </Col>
      </Row>
    </div>
  );
}
export default TugasList;
