import React from "react";
import { useParams } from "react-router-dom";
import { Button, Card, CardBody, CardHeader } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import { Loading } from "components/Feedback/Feedback";
import { unduhBlob } from "utils/download";
import { formatTanggalWaktu, formatUkuran } from "utils/format";
import logo from "assets/img/komputer.svg";

/**
 * Halaman PUBLIK (tanpa login) untuk satu berkas final. Tujuan tautan berkas yang tercetak di PDF laporan proyek.
 * Akses = memegang kode verifikasi + id berkas; mati bila kelompok dibuka kembali dari final.
 */
function BerkasPublik() {
  const { kode, idb } = useParams();
  const [info, setInfo] = React.useState(null);
  const [galat, setGalat] = React.useState(null);
  const [mengunduh, setMengunduh] = React.useState(false);
  const [galatUnduh, setGalatUnduh] = React.useState(null);

  React.useEffect(() => {
    const ac = new AbortController();
    proyekApi.infoBerkasPublik(kode, idb, ac.signal).then(setInfo).catch((e) => e.name !== "AbortError" && setGalat(e));
    return () => ac.abort();
  }, [kode, idb]);

  const unduh = async () => {
    setMengunduh(true);
    setGalatUnduh(null);
    try { unduhBlob(await proyekApi.unduhBerkasPublik(kode, idb), info.nama); }
    catch (e) { setGalatUnduh(e.message); }
    finally { setMengunduh(false); }
  };

  const Baris = ({ l, v }) => (<div className="mb-3"><small className="text-muted d-block">{l}</small><b>{v}</b></div>);

  return (
    <div className="auth-page">
      <div style={{ width: "100%", maxWidth: 480 }}>
        <div className="auth-brand">
          <img src={logo} alt="" />
          <h1>Berkas Proyek</h1>
        </div>
        <Card>
          <CardHeader>
            <h4 className={`card-title mb-0 ${info ? "text-success" : galat ? "text-danger" : ""}`}>
              {info ? "Berkas final" : galat ? "Tautan tidak berlaku" : "Memeriksa..."}
            </h4>
          </CardHeader>
          <CardBody>
            {!info && !galat ? <Loading text="Memeriksa tautan..." /> : null}
            {galat ? (
              <p className="mb-0">
                {galat.status === 404
                  ? "Berkas tidak ditemukan atau tautan sudah tidak berlaku. Bila proyek dibuka kembali untuk revisi, laporan baru dengan tautan baru akan diterbitkan setelah difinalkan lagi."
                  : galat.message}
              </p>
            ) : null}
            {info ? (
              <>
                <Baris l="Nama berkas" v={info.nama} />
                <Baris l="Ukuran" v={formatUkuran(info.ukuran)} />
                {info.nama_tugas ? <Baris l="Tugas" v={info.nama_tugas} /> : null}
                <Baris l="Kelompok" v={`${info.nama_kelompok} (Kelas ${info.kelas})`} />
                <Baris l="Proyek" v={info.nama_proyek} />
                <Baris l="Disahkan final" v={`${formatTanggalWaktu(info.final_at)} · ${info.nama_dosen}`} />
                <Button color="primary" className="btn-fill" block disabled={mengunduh} onClick={unduh}>{mengunduh ? "Mengunduh..." : "Unduh berkas"}</Button>
                {galatUnduh ? <p className="text-danger small mt-2 mb-0">{galatUnduh}</p> : null}
              </>
            ) : null}
          </CardBody>
        </Card>
      </div>
    </div>
  );
}

export default BerkasPublik;
