import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { Button, FormGroup, Input } from "reactstrap";
import * as kuisApi from "services/kuisApi";
import { useNotify } from "contexts/NotifyContext";
import ConfirmModal from "components/ConfirmModal/ConfirmModal";

/** Aksi siklus hidup kuis yang boleh dilakukan menurut status (aturan mengikuti backend kuis/controller.js). */
export const aksiTersedia = (status) => ({
  edit: status !== "archived",
  terbitkan: status === "draft",
  nonaktifkan: status === "scheduled", // kembali ke draft (hanya sebelum mulai)
  akhiri: status === "live",
  arsipkan: status === "finished",
  hasil: status !== "draft",
  hapus: status === "draft", // backend juga menolak bila sudah ada jawaban
  pantau: ["scheduled", "live"].includes(status),
});

const KONFIRMASI = {
  terbitkan: {
    judul: "Terbitkan kuis?",
    tombol: "Ya, terbitkan",
    warna: "success",
    isi: (k) => (
      <>Kuis <b>{k.judul}</b> akan terlihat oleh siswa kelas {k.kelas.join(", ")} dan dimulai otomatis sesuai jadwal. Setelah dimulai, jadwal, soal, kelas, dan mode nilai dikunci.</>
    ),
  },
  nonaktifkan: {
    judul: "Kembalikan ke draft?",
    tombol: "Ya, kembalikan",
    warna: "warning",
    isi: (k) => <>Kuis <b>{k.judul}</b> disembunyikan dari siswa dan dapat diedit lagi. Terbitkan ulang sebelum jadwal mulai.</>,
  },
  arsipkan: {
    judul: "Arsipkan kuis?",
    tombol: "Ya, arsipkan",
    warna: "warning",
    isi: (k) => <>Kuis <b>{k.judul}</b> dipindahkan ke arsip dan tidak lagi tampil untuk siswa. Hasilnya tetap bisa dilihat di tab Arsip.</>,
  },
  hapus: {
    judul: "Hapus kuis?",
    tombol: "Ya, hapus",
    warna: "danger",
    isi: (k) => <>Kuis draft <b>{k.judul}</b> akan dihapus permanen. Kuis yang sudah punya jawaban tidak bisa dihapus (gunakan arsip).</>,
  },
  akhiri: {
    judul: "Akhiri kuis sekarang?",
    tombol: "Ya, akhiri kuis",
    warna: "danger",
    isi: (k) => <>Kuis <b>{k.judul}</b> dihentikan saat ini juga; soal yang belum tampil tidak akan muncul. Tindakan ini tidak bisa dibatalkan.</>,
  },
};

/**
 * Tombol aksi kuis + dialog konfirmasi. `compact` = tombol ikon untuk baris tabel.
 * onSelesai(nama, hasil) dipanggil setelah aksi sukses (duplikasi langsung membuka form edit salinan).
 */
function AksiKuis({ kuis, compact = false, tanpa = [], onSelesai }) {
  const notify = useNotify();
  const navigate = useNavigate();
  const [konfirm, setKonfirm] = React.useState(null); // nama aksi
  const [alasan, setAlasan] = React.useState("");
  const [proses, setProses] = React.useState(false);
  const boleh = aksiTersedia(kuis.status);
  const tampil = (nama) => boleh[nama] && !tanpa.includes(nama);

  const jalankan = async () => {
    setProses(true);
    try {
      let hasil;
      if (konfirm === "terbitkan") hasil = await kuisApi.terbitkan(kuis.id_kuis);
      else if (konfirm === "nonaktifkan") hasil = await kuisApi.nonaktifkan(kuis.id_kuis);
      else if (konfirm === "arsipkan") hasil = await kuisApi.arsipkan(kuis.id_kuis);
      else if (konfirm === "akhiri") hasil = await kuisApi.akhiri(kuis.id_kuis, alasan.trim());
      else if (konfirm === "hapus") hasil = await kuisApi.remove(kuis.id_kuis);
      notify.sukses(
        { terbitkan: "Kuis diterbitkan.", nonaktifkan: "Kuis dikembalikan ke draft.", arsipkan: "Kuis diarsipkan.", akhiri: "Kuis diakhiri.", hapus: "Kuis dihapus." }[konfirm]
      );
      const nama = konfirm;
      setKonfirm(null);
      setAlasan("");
      onSelesai?.(nama, hasil);
    } catch (err) {
      notify.gagal(err.message);
      setKonfirm(null);
    } finally {
      setProses(false);
    }
  };

  const duplikasi = async () => {
    setProses(true);
    try {
      const baru = await kuisApi.duplikasi(kuis.id_kuis);
      notify.sukses("Kuis diduplikasi sebagai draft; atur jadwalnya.");
      navigate(`/admin/kuis/${baru.id_kuis}/edit`);
    } catch (err) {
      notify.gagal(err.message);
      setProses(false);
    }
  };

  // Satu definisi tombol, dua tampilan (ikon di tabel / teks di halaman detail)
  const T = [
    { n: "pantau", ikon: "icon-sound-wave", warna: "success", label: "Pantau", tipe: "link", ke: `/admin/kuis/${kuis.id_kuis}` },
    { n: "hasil", ikon: "icon-trophy", warna: "primary", label: "Hasil", tipe: "link", ke: `/admin/kuis/${kuis.id_kuis}/hasil` },
    { n: "edit", ikon: "icon-pencil", warna: "warning", label: "Edit", tipe: "link", ke: `/admin/kuis/${kuis.id_kuis}/edit` },
    { n: "terbitkan", ikon: "icon-send", warna: "success", label: "Terbitkan", tipe: "aksi" },
    { n: "nonaktifkan", ikon: "icon-button-pause", warna: "warning", label: "Kembalikan ke draft", tipe: "aksi" },
    { n: "akhiri", ikon: "icon-button-power", warna: "danger", label: "Akhiri sekarang", tipe: "aksi" },
    { n: "arsipkan", ikon: "icon-bank", warna: "warning", label: "Arsipkan", tipe: "aksi" },
    { n: "duplikasi", ikon: "icon-single-copy-04", warna: "info", label: "Duplikasi", tipe: "dup" },
    { n: "hapus", ikon: "icon-trash-simple", warna: "danger", label: "Hapus", tipe: "aksi" },
  ].filter((t) => (t.n === "duplikasi" ? !tanpa.includes("duplikasi") : tampil(t.n)));

  const k = konfirm ? KONFIRMASI[konfirm] : null;
  return (
    <>
      {T.map((t) => {
        const props = compact
          ? { size: "sm", color: t.warna, className: "btn-link btn-icon", title: t.label }
          : { color: t.warna, className: "mr-2 mb-2" };
        const isi = compact ? <i className={`tim-icons ${t.ikon}`} /> : <><i className={`tim-icons ${t.ikon}`} /> {t.label}</>;
        if (t.tipe === "link") return <Button key={t.n} tag={Link} to={t.ke} {...props}>{isi}</Button>;
        if (t.tipe === "dup") return <Button key={t.n} disabled={proses} onClick={duplikasi} {...props}>{isi}</Button>;
        return <Button key={t.n} disabled={proses} onClick={() => setKonfirm(t.n)} {...props}>{isi}</Button>;
      })}
      <ConfirmModal isOpen={!!k} title={k?.judul} confirmText={k?.tombol} confirmColor={k?.warna} loading={proses} onConfirm={jalankan} onCancel={() => setKonfirm(null)}>
        {k ? k.isi(kuis) : null}
        {konfirm === "akhiri" ? (
          <FormGroup className="mt-3 mb-0">
            <label htmlFor="alasan-akhiri">Alasan (opsional, masuk audit log)</label>
            <Input id="alasan-akhiri" value={alasan} maxLength={300} onChange={(e) => setAlasan(e.target.value)} />
          </FormGroup>
        ) : null}
      </ConfirmModal>
    </>
  );
}

export default AksiKuis;
