import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { Badge, Button, Card, CardBody, CardHeader, CardTitle, Col, Input, Row, Table } from "reactstrap";
import * as soalApi from "services/soalApi";
import { useNotify } from "contexts/NotifyContext";
import ConfirmModal from "components/ConfirmModal/ConfirmModal";
import Pager from "components/Pager/Pager";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import useDebounce from "hooks/useDebounce";
import { TIPE_SOAL, formatTanggalWaktu } from "utils/format";
import { unduhTemplateSoal } from "utils/templates";
import ImporSoal from "views/soal/ImporSoal";

const LIMIT = 30;

function SoalList() {
  const notify = useNotify();
  const navigate = useNavigate();
  const [q, setQ] = React.useState("");
  const [tipe, setTipe] = React.useState("");
  const [mapel, setMapel] = React.useState("");
  const [page, setPage] = React.useState(1);
  const dq = useDebounce(q, 400);
  const dMapel = useDebounce(mapel, 400);
  const [data, setData] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);
  const [hapus, setHapus] = React.useState(null);
  const [menghapus, setMenghapus] = React.useState(false);
  const [sibuk, setSibuk] = React.useState(null); // id soal yang sedang diduplikasi
  const [impor, setImpor] = React.useState(false);

  const muat = React.useCallback(
    async (signal) => {
      setLoading(true);
      setError(null);
      try {
        setData(await soalApi.list({ q: dq.trim(), tipe, mapel: dMapel.trim(), page, limit: LIMIT }, signal));
      } catch (err) {
        if (err.name !== "AbortError") setError(err);
      } finally {
        if (!signal?.aborted) setLoading(false);
      }
    },
    [dq, tipe, dMapel, page]
  );
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    return () => ac.abort();
  }, [muat]);
  React.useEffect(() => setPage(1), [dq, tipe, dMapel]);

  const duplikasi = async (s) => {
    setSibuk(s.id_soal);
    try {
      const baru = await soalApi.duplikasi(s.id_soal);
      notify.sukses("Soal diduplikasi.");
      navigate(`/admin/soal/${baru.id_soal}/edit`);
    } catch (err) {
      notify.gagal(err.message);
      setSibuk(null);
    }
  };

  const konfirmasiHapus = async () => {
    setMenghapus(true);
    try {
      await soalApi.remove(hapus.id_soal);
      notify.sukses("Soal dihapus.");
      setHapus(null);
      muat();
    } catch (err) {
      notify.gagal(err.message); // mis. 409 SOAL_TERKUNCI
      setHapus(null);
    } finally {
      setMenghapus(false);
    }
  };

  const meta = data ? { page: data.page, limit: data.limit, total: data.total, total_halaman: Math.max(1, Math.ceil(data.total / data.limit)) } : null;

  return (
    <div className="content">
      <Row>
        <Col xs="12">
          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col>
                  <CardTitle tag="h4" className="mb-0">Bank Soal</CardTitle>
                  <p className="category mb-0">Soal yang dipakai kuis terbit dikunci; gunakan Duplikasi untuk membuat versi baru{data ? ` · ${data.total} soal` : ""}</p>
                </Col>
                <Col xs="auto">
                  <Button color="secondary" className="mr-2" onClick={unduhTemplateSoal}>
                    <i className="tim-icons icon-cloud-download-93" /> Unduh template
                  </Button>
                  <Button color="secondary" className="mr-2" onClick={() => setImpor(true)}>
                    <i className="tim-icons icon-upload" /> Impor CSV
                  </Button>
                  <Button tag={Link} to="/admin/soal/baru" color="primary" className="btn-fill">
                    <i className="tim-icons icon-simple-add" /> Soal baru
                  </Button>
                </Col>
              </Row>
              <Row className="mt-3">
                <Col md="5"><Input placeholder="Cari teks soal…" value={q} onChange={(e) => setQ(e.target.value)} /></Col>
                <Col md="3">
                  <Input type="select" value={tipe} onChange={(e) => setTipe(e.target.value)}>
                    <option value="">Semua tipe</option>
                    {Object.entries(TIPE_SOAL).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
                  </Input>
                </Col>
                <Col md="3"><Input placeholder="Mapel (persis)" value={mapel} onChange={(e) => setMapel(e.target.value)} /></Col>
              </Row>
            </CardHeader>
            <CardBody>
              <ErrorBox error={error} onRetry={() => muat()} />
              {loading && !data ? (
                <Loading />
              ) : (
                <Table responsive>
                  <thead className="text-primary">
                    <tr><th>Soal</th><th>Tipe</th><th>Mapel</th><th>Dibuat</th><th className="aksi">Aksi</th></tr>
                  </thead>
                  <tbody>
                    {(data?.soal || []).map((s) => (
                      <tr key={s.id_soal}>
                        <td style={{ whiteSpace: "normal", minWidth: 260 }}>
                          <Link className="table-link" to={`/admin/soal/${s.id_soal}/edit`}>
                            {s.teks.length > 110 ? `${s.teks.slice(0, 110)}…` : s.teks}
                          </Link>
                          {s.gambar ? <i className="tim-icons icon-image-02 ml-2 text-muted" title="Ada gambar" /> : null}
                          <span className="sub">
                            {s.tipe === "pilihan_ganda" ? `${s.opsi.length} opsi` : s.mode_periksa === "manual" ? "diperiksa manual" : "diperiksa otomatis"}
                          </span>
                        </td>
                        <td><Badge color={s.tipe === "pilihan_ganda" ? "info" : "warning"} pill>{TIPE_SOAL[s.tipe]}</Badge></td>
                        <td>{s.mapel || <span className="text-muted">-</span>}</td>
                        <td>{formatTanggalWaktu(s.createdAt)}<span className="sub">{s.dibuat_oleh}</span></td>
                        <td className="aksi">
                          <Button color="warning" size="sm" className="btn-link btn-icon" title="Ubah" tag={Link} to={`/admin/soal/${s.id_soal}/edit`}>
                            <i className="tim-icons icon-pencil" />
                          </Button>
                          <Button color="info" size="sm" className="btn-link btn-icon" title="Duplikasi" disabled={sibuk === s.id_soal} onClick={() => duplikasi(s)}>
                            <i className="tim-icons icon-single-copy-04" />
                          </Button>
                          <Button color="danger" size="sm" className="btn-link btn-icon" title="Hapus" onClick={() => setHapus(s)}>
                            <i className="tim-icons icon-trash-simple" />
                          </Button>
                        </td>
                      </tr>
                    ))}
                    {data && data.soal.length === 0 ? (
                      <tr><td colSpan="5" className="text-center text-muted py-4">Belum ada soal yang cocok.</td></tr>
                    ) : null}
                  </tbody>
                </Table>
              )}
              <Pager meta={meta} onPage={setPage} />
            </CardBody>
          </Card>
        </Col>
      </Row>
      {impor ? <ImporSoal onClose={() => setImpor(false)} onSelesai={() => muat()} /> : null}
      <ConfirmModal isOpen={!!hapus} title="Hapus soal?" confirmText="Ya, hapus" loading={menghapus} onConfirm={konfirmasiHapus} onCancel={() => setHapus(null)}>
        Soal akan dihapus permanen dan dilepas dari kuis draft yang memakainya. Soal yang dipakai kuis terbit tidak bisa dihapus.
        <p className="mt-2 mb-0 text-muted">{hapus?.teks?.slice(0, 160)}</p>
      </ConfirmModal>
    </div>
  );
}

export default SoalList;
