import React from "react";
import { Link } from "react-router-dom";
import "chart.js/auto";
import { Doughnut } from "react-chartjs-2";
import { Button, Card, CardBody, CardHeader, CardTitle, Col, Row, Table } from "reactstrap";
import * as kuisApi from "services/kuisApi";
import StatusBadge from "components/StatusBadge/StatusBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { STATUS_KUIS, formatTanggalWaktu } from "utils/format";

const TEKS = "#9a9a9a";
const KARTU = [
  { kunci: "kuis_berlangsung", label: "Kuis berlangsung", ikon: "tim-icons icon-sound-wave text-success", ke: "/admin/kuis" },
  { kunci: "kuis_terjadwal", label: "Kuis terjadwal", ikon: "tim-icons icon-time-alarm text-info", ke: "/admin/kuis" },
  { kunci: "peserta_aktif_sesi_berjalan", label: "Peserta aktif sekarang", ikon: "tim-icons icon-user-run text-warning", ke: "/admin/kuis" },
  { kunci: "siswa_aktif", label: "Siswa aktif", ikon: "tim-icons icon-single-02 text-primary", ke: "/admin/siswa", sub: (r) => `dari ${r.siswa_terdaftar} terdaftar` },
];
const DONUT = ["draft", "scheduled", "live", "finished"];
const KUNCI_STATUS = { draft: "kuis_draft", scheduled: "kuis_terjadwal", live: "kuis_berlangsung", finished: "kuis_selesai" };

function Dashboard() {
  const [ringkasan, setRingkasan] = React.useState(null);
  const [kuis, setKuis] = React.useState([]);
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  const muat = React.useCallback(async (signal) => {
    try {
      const [r, k] = await Promise.all([kuisApi.ringkasan(signal), kuisApi.list({}, signal)]);
      setRingkasan(r);
      setKuis(k);
      setError(null);
    } catch (err) {
      if (err.name !== "AbortError") setError(err);
    } finally {
      if (!signal?.aborted) setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    const t = setInterval(() => muat(ac.signal), 10000); // angka "aktif" berubah saat kuis berjalan
    return () => {
      ac.abort();
      clearInterval(t);
    };
  }, [muat]);

  if (loading && !ringkasan) return <div className="content"><Loading /></div>;

  const doughnut = ringkasan && {
    labels: DONUT.map((s) => STATUS_KUIS[s].label),
    datasets: [
      {
        data: DONUT.map((s) => ringkasan[KUNCI_STATUS[s]]),
        backgroundColor: DONUT.map((s) => STATUS_KUIS[s].chart),
        borderWidth: 0,
      },
    ],
  };
  const adaKuis = ringkasan && ringkasan.kuis_total > 0;
  // Sedang berlangsung dulu, lalu yang terjadwal terdekat.
  const sorotan = kuis
    .filter((k) => k.status === "live" || k.status === "scheduled")
    .sort((a, b) => (a.status === b.status ? new Date(a.mulai_at) - new Date(b.mulai_at) : a.status === "live" ? -1 : 1))
    .slice(0, 5);

  return (
    <div className="content">
      <ErrorBox error={error} onRetry={() => muat()} />
      <Row>
        {KARTU.map((k) => (
          <Col key={k.kunci} lg="3" md="6">
            <Link to={k.ke} className="stat-link">
              <Card className="stat-card">
                <CardHeader>
                  <h5 className="card-category mb-0">{k.label}</h5>
                </CardHeader>
                <CardBody>
                  <h2 className="mb-0"><i className={k.ikon} /> {ringkasan ? ringkasan[k.kunci] : "-"}</h2>
                  {k.sub && ringkasan ? <span className="stat-nominal">{k.sub(ringkasan)}</span> : null}
                </CardBody>
              </Card>
            </Link>
          </Col>
        ))}
      </Row>
      <Row>
        <Col lg="4">
          <Card>
            <CardHeader>
              <h5 className="card-category">Komposisi kuis</h5>
              <CardTitle tag="h3">{ringkasan ? ringkasan.kuis_total : 0} kuis</CardTitle>
            </CardHeader>
            <CardBody>
              {adaKuis ? (
                <div className="chart-area" style={{ height: 240 }}>
                  <Doughnut
                    data={doughnut}
                    options={{
                      maintainAspectRatio: false,
                      cutout: "65%",
                      plugins: { legend: { position: "bottom", labels: { color: TEKS, usePointStyle: true } } },
                    }}
                  />
                </div>
              ) : (
                <p className="text-muted text-center py-5 mb-0">Belum ada kuis.</p>
              )}
            </CardBody>
          </Card>
        </Col>
        <Col lg="8">
          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col>
                  <CardTitle tag="h4" className="mb-0">Berlangsung &amp; akan datang</CardTitle>
                </Col>
                <Col xs="auto">
                  <Button tag={Link} to="/admin/kuis/baru" color="primary" size="sm" className="btn-fill">
                    <i className="tim-icons icon-simple-add" /> Kuis baru
                  </Button>
                </Col>
              </Row>
            </CardHeader>
            <CardBody>
              {sorotan.length === 0 ? (
                <p className="text-muted text-center py-4 mb-0">Tidak ada kuis yang berlangsung atau terjadwal.</p>
              ) : (
                <Table responsive>
                  <thead className="text-primary">
                    <tr>
                      <th>Kuis</th>
                      <th>Kelas</th>
                      <th>Mulai</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sorotan.map((k) => (
                      <tr key={k.id_kuis}>
                        <td>
                          <Link className="table-link" to={`/admin/kuis/${k.id_kuis}`}>{k.judul}</Link>
                          <span className="sub">{k.jumlah_soal} soal · {k.durasi_soal_detik} dtk/soal</span>
                        </td>
                        <td>{k.kelas.join(", ")}</td>
                        <td>{formatTanggalWaktu(k.mulai_at)}</td>
                        <td><StatusBadge status={k.status} /></td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              )}
            </CardBody>
          </Card>
        </Col>
      </Row>
    </div>
  );
}

export default Dashboard;
