import React from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { Alert, Button, Card, CardBody, CardHeader, CardTitle, Col, Input, Modal, ModalBody, ModalFooter, ModalHeader, Row, Table } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import ConfirmModal from "components/ConfirmModal/ConfirmModal";
import FormField from "components/FormField/FormField";
import ProyekBadge from "components/ProyekBadge/ProyekBadge";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { useNotify } from "contexts/NotifyContext";
import { formatTanggalPertemuan, formatTanggalWaktu } from "utils/format";

function TugasDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const notify = useNotify();
  const [t, setT] = React.useState(null);
  const [error, setError] = React.useState(null);
  const [bekerja, setBekerja] = React.useState(false);
  const [tanggalBaru, setTanggalBaru] = React.useState("");
  const [hasil, setHasil] = React.useState(null); // { judul, diterapkan, total, dilewati[] } dari aksi massal
  const [ubahNama, setUbahNama] = React.useState(null);
  const [ubahTgl, setUbahTgl] = React.useState(null); // { nomor, tanggal }
  const [konfirmasi, setKonfirmasi] = React.useState(null); // "hapus" | { hapusPertemuan: nomor }

  const muat = React.useCallback(async (signal) => {
    try { setT(await proyekApi.getTugas(id, signal)); setError(null); }
    catch (err) { if (err.name !== "AbortError") setError(err); }
  }, [id]);
  React.useEffect(() => {
    const ac = new AbortController();
    muat(ac.signal);
    return () => ac.abort();
  }, [muat]);

  // Aksi jadwal massal: tampilkan ringkasan (diterapkan / dilewati + alasan).
  const jadwal = async (fn, judul) => {
    setBekerja(true);
    try {
      const r = await fn();
      setHasil({ judul, ...r.hasil });
      await muat();
      return true;
    } catch (err) {
      notify.gagal(err.message);
      muat();
      return false;
    } finally {
      setBekerja(false);
    }
  };

  if (error && !t) return <div className="content"><ErrorBox error={error} onRetry={() => muat()} /></div>;
  if (!t) return <div className="content"><Loading /></div>;

  const terakhir = t.jadwal.length;
  const adaKelompok = t.kelompok.length > 0;

  return (
    <div className="content">
      <ErrorBox error={error} onRetry={() => muat()} />
      <Row>
        <Col lg="8">
          <Card>
            <CardHeader>
              <Row className="align-items-start">
                <Col>
                  <CardTitle tag="h4" className="mb-1">{t.nama_tugas}</CardTitle>
                  <p className="category mb-0">Kelas {t.kelas} · dibuat oleh {t.dibuat_oleh} · {formatTanggalWaktu(t.createdAt)}</p>
                </Col>
                <Col xs="auto">
                  <Button size="sm" color="info" onClick={() => setUbahNama(t.nama_tugas)}>Ubah nama</Button>
                  <Button size="sm" color="danger" className="ml-2" onClick={() => setKonfirmasi("hapus")}>Hapus</Button>
                </Col>
              </Row>
            </CardHeader>
          </Card>

          <Card>
            <CardHeader>
              <Row className="align-items-center">
                <Col><CardTitle tag="h4" className="mb-0">Kelompok ({t.kelompok.length})</CardTitle></Col>
                <Col xs="auto">
                  <Button tag={Link} to={`/admin/tugas/${t.id_tugas}/kelompok/baru`} color="primary" size="sm" className="btn-fill" disabled={t.belum_berkelompok.length === 0}>
                    <i className="tim-icons icon-simple-add" /> Kelompok baru
                  </Button>
                </Col>
              </Row>
              {t.belum_berkelompok.length === 0 ? <p className="category mt-2 mb-0">Semua siswa aktif kelas {t.kelas} sudah masuk kelompok.</p> : null}
            </CardHeader>
            <CardBody>
              <Table responsive>
                <thead className="text-primary"><tr><th>Kelompok / Proyek</th><th>Anggota</th><th>Progress</th><th>Berkas</th><th>Status</th></tr></thead>
                <tbody>
                  {t.kelompok.map((k) => (
                    <tr key={k.id_proyek}>
                      <td style={{ whiteSpace: "normal", minWidth: 200 }}>
                        <Link className="table-link" to={`/admin/tugas/kelompok/${k.id_proyek}`}>{k.nama_kelompok}</Link>
                        <span className="sub">{k.nama_proyek}</span>
                      </td>
                      <td>{k.jumlah_anggota}</td>
                      <td>
                        {k.jumlah_terkirim}/{k.jumlah_pertemuan}
                        {k.pertemuan_terbuka.length ? <span className="sub text-success">Terbuka: ke-{k.pertemuan_terbuka.join(", ")}</span> : null}
                      </td>
                      <td>{k.jumlah_berkas}</td>
                      <td><ProyekBadge status={k.status} />{k.status === "final" ? <span className="sub">{k.final_oleh_nama}</span> : null}</td>
                    </tr>
                  ))}
                  {!adaKelompok ? <tr><td colSpan="5" className="text-center text-muted py-4">Belum ada kelompok. Klik "Kelompok baru".</td></tr> : null}
                </tbody>
              </Table>
            </CardBody>
          </Card>
        </Col>

        <Col lg="4">
          <Card>
            <CardHeader>
              <CardTitle tag="h4" className="mb-1">Jadwal Pertemuan</CardTitle>
              <p className="category mb-0">Perubahan di sini diterapkan ke <b>jadwal bawaan</b> dan ke <b>semua kelompok</b>. Kelompok yang tidak bisa menerimanya dilewati. Jadwal khusus satu kelompok diatur di halaman kelompok.</p>
            </CardHeader>
            <CardBody>
              {t.jadwal.length === 0 ? <p className="text-muted">Belum ada pertemuan.</p> : null}
              {t.jadwal.map((tgl, i) => (
                <div key={i} className="d-flex align-items-center py-1">
                  <div className="flex-grow-1"><b>Pertemuan {i + 1}</b><small className="text-muted d-block">{formatTanggalPertemuan(tgl)}</small></div>
                  <Button size="sm" color="secondary" className="mr-1" onClick={() => setUbahTgl({ nomor: i + 1, tanggal: tgl })}>Ubah</Button>
                  {i + 1 === terakhir ? <Button size="sm" color="danger" onClick={() => setKonfirmasi({ hapusPertemuan: i + 1 })}>Hapus</Button> : null}
                </div>
              ))}
              <div className="d-flex align-items-center mt-3">
                <Input type="date" bsSize="sm" value={tanggalBaru} onChange={(e) => setTanggalBaru(e.target.value)} />
                <Button size="sm" color="primary" className="ml-2 text-nowrap" disabled={bekerja || !tanggalBaru}
                  onClick={async () => { if (await jadwal(() => proyekApi.tambahPertemuanTugas(id, tanggalBaru), `Pertemuan ${terakhir + 1} ditambahkan`)) setTanggalBaru(""); }}>
                  + Pertemuan
                </Button>
              </div>
              {hasil ? (
                <Alert color={hasil.dilewati.length ? "warning" : "success"} className="mt-3 mb-0" toggle={() => setHasil(null)}>
                  <b>{hasil.judul}.</b> Diterapkan ke {hasil.diterapkan} dari {hasil.total} kelompok.
                  {hasil.dilewati.length ? (
                    <>
                      <div className="mt-2"><b>Dilewati ({hasil.dilewati.length}):</b></div>
                      <ul className="mb-0 pl-3">
                        {hasil.dilewati.map((d) => <li key={d.id_proyek}><b>{d.nama_kelompok}</b>: {d.alasan}</li>)}
                      </ul>
                    </>
                  ) : null}
                </Alert>
              ) : null}
            </CardBody>
          </Card>

          <Card>
            <CardHeader><CardTitle tag="h4" className="mb-0">Belum Berkelompok ({t.belum_berkelompok.length})</CardTitle></CardHeader>
            <CardBody>
              {t.belum_berkelompok.length === 0 ? <p className="text-muted mb-0">Semua siswa aktif sudah masuk kelompok.</p> : (
                <ul className="mb-0">{t.belum_berkelompok.map((s) => <li key={s.id_siswa}>{s.nama} <small className="text-muted">{s.nim}</small></li>)}</ul>
              )}
            </CardBody>
          </Card>
        </Col>
      </Row>

      <Modal isOpen={ubahNama !== null} toggle={() => setUbahNama(null)} centered>
        <ModalHeader toggle={() => setUbahNama(null)}>Ubah nama tugas</ModalHeader>
        <ModalBody><FormField label="Nama tugas" name="nama_tugas" value={ubahNama || ""} onChange={(e) => setUbahNama(e.target.value)} maxLength={150} /></ModalBody>
        <ModalFooter>
          <Button color="secondary" onClick={() => setUbahNama(null)}>Batal</Button>
          <Button color="primary" disabled={bekerja || (ubahNama || "").trim().length < 3}
            onClick={async () => { setBekerja(true); try { await proyekApi.updateTugas(id, { nama_tugas: ubahNama.trim() }); notify.sukses("Nama tugas diperbarui."); setUbahNama(null); await muat(); } catch (err) { notify.gagal(err.message); } finally { setBekerja(false); } }}>
            Simpan
          </Button>
        </ModalFooter>
      </Modal>

      <Modal isOpen={!!ubahTgl} toggle={() => setUbahTgl(null)} centered>
        <ModalHeader toggle={() => setUbahTgl(null)}>Ubah tanggal — Pertemuan {ubahTgl?.nomor}</ModalHeader>
        <ModalBody>
          <FormField label="Tanggal pertemuan" name="tgl" type="date" value={ubahTgl?.tanggal || ""} onChange={(e) => setUbahTgl((u) => ({ ...u, tanggal: e.target.value }))}
            hint="Diterapkan ke semua kelompok yang pertemuannya belum menerima progress dan belum final." />
        </ModalBody>
        <ModalFooter>
          <Button color="secondary" onClick={() => setUbahTgl(null)}>Batal</Button>
          <Button color="primary" disabled={bekerja || !ubahTgl?.tanggal}
            onClick={async () => { if (await jadwal(() => proyekApi.ubahPertemuanTugas(id, ubahTgl.nomor, ubahTgl.tanggal), `Pertemuan ${ubahTgl.nomor} diubah`)) setUbahTgl(null); }}>
            Simpan
          </Button>
        </ModalFooter>
      </Modal>

      <ConfirmModal isOpen={!!konfirmasi?.hapusPertemuan} title="Hapus pertemuan terakhir?" confirmText="Ya, hapus" loading={bekerja}
        onCancel={() => setKonfirmasi(null)}
        onConfirm={async () => { if (await jadwal(() => proyekApi.hapusPertemuanTugas(id, konfirmasi.hapusPertemuan), `Pertemuan ${konfirmasi.hapusPertemuan} dihapus`)) setKonfirmasi(null); }}>
        Pertemuan {konfirmasi?.hapusPertemuan} dihapus dari jadwal tugas dan dari kelompok yang belum menerima progress pada pertemuan itu.
      </ConfirmModal>
      <ConfirmModal isOpen={konfirmasi === "hapus"} title="Hapus tugas?" confirmText="Ya, hapus semua" loading={bekerja}
        onCancel={() => setKonfirmasi(null)}
        onConfirm={async () => { setBekerja(true); try { await proyekApi.removeTugas(id); notify.sukses("Tugas dihapus."); navigate("/admin/tugas"); } catch (err) { notify.gagal(err.message); setBekerja(false); } }}>
        Tugas <b>{t.nama_tugas}</b> beserta <b>{t.kelompok.length} kelompok</b> dan seluruh berkas yang sudah diunggah akan dihapus permanen, termasuk kelompok yang sudah final.
      </ConfirmModal>
    </div>
  );
}
export default TugasDetail;
