// Format tampilan (tanggal, status, angka). Semua waktu ditampilkan & diinput dalam WIB (Asia/Jakarta).
const TZ = "Asia/Jakarta";
const OFFSET = "+07:00"; // Indonesia (WIB) tidak memakai DST

export const formatTanggalWaktu = (d) =>
  d
    ? new Date(d).toLocaleString("id-ID", {
        day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: TZ,
      })
    : "-";

export const formatTanggalWaktuDetik = (d) =>
  d
    ? new Date(d).toLocaleString("id-ID", {
        day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", second: "2-digit", timeZone: TZ,
      })
    : "-";

export const formatTanggal = (d) =>
  d ? new Date(d).toLocaleDateString("id-ID", { day: "numeric", month: "long", year: "numeric", timeZone: TZ }) : "-";

/** ISO dari backend → "yyyy-mm-ddThh:mm" (WIB) untuk <input type="datetime-local">. */
export const keInputWaktu = (d) => {
  if (!d) return "";
  const s = new Intl.DateTimeFormat("sv-SE", {
    timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23",
  }).format(new Date(d));
  return s.replace(" ", "T");
};

/** "yyyy-mm-ddThh:mm" (WIB) → ISO 8601 dengan offset, format yang diminta backend. */
export const dariInputWaktu = (v) => (v ? `${v}:00${OFFSET}` : "");

/** Nilai/angka desimal gaya Indonesia (maks 2 desimal). */
export const formatAngka = (n) =>
  n === null || n === undefined || n === "" || Number.isNaN(Number(n))
    ? "-"
    : new Intl.NumberFormat("id-ID", { maximumFractionDigits: 2 }).format(Number(n));

export const formatDetik = (ms) => (ms === null || ms === undefined ? "-" : `${(Number(ms) / 1000).toFixed(2)} dtk`);

/** Hitung mundur "m:ss" / "n dtk" dari milidetik. */
export const formatHitungMundur = (ms) => {
  const d = Math.max(0, Math.ceil(ms / 1000));
  if (d >= 3600) return `${Math.floor(d / 3600)}j ${String(Math.floor((d % 3600) / 60)).padStart(2, "0")}m`;
  if (d >= 60) return `${Math.floor(d / 60)}:${String(d % 60).padStart(2, "0")}`;
  return `${d} dtk`;
};

