/** "2026-11-20" → "Jumat, 20 November 2026" (tanggal kalender WIB, tanpa konversi zona). */
export const formatTanggalPertemuan = (yyyyMmDd) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(yyyyMmDd || ""));
  if (!m) return "-";
  return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3], 12)).toLocaleDateString("id-ID", {
    weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: "UTC",
  });
};

/** Tanggal hari ini menurut WIB, "yyyy-mm-dd" (untuk nilai awal/batas <input type="date">). */
export const hariIniWIB = () => new Date(Date.now() + 7 * 3600e3).toISOString().slice(0, 10);

export const formatUkuran = (b) => (b >= 1048576 ? `${(b / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(b / 1024))} KB`);

/** Nama aman untuk nama berkas unduhan ("Kelompok Elang" → "Kelompok-Elang"). */
export const slugNama = (s) => String(s || "proyek").normalize("NFKD").replace(/[^\w\- ]+/g, "").trim().replace(/\s+/g, "-").slice(0, 50) || "proyek";
