// Validasi sisi klien — mencerminkan aturan model di backend (app/*/model.js, passwordValidator.js)
// supaya pengguna mendapat umpan balik langsung. Backend tetap sumber kebenaran.
const len = (v, min, max, label) => {
  const s = String(v ?? "").trim();
  if (min && s.length < min) return s.length === 0 ? `${label} wajib diisi` : `${label} minimal ${min} karakter`;
  if (max && s.length > max) return `${label} maksimal ${max} karakter`;
  return null;
};

/** Sama dengan validateNewPassword di backend. Mengembalikan pesan error atau null. */
export function validasiPasswordBaru(p) {
  const s = String(p ?? "");
  if (s.length < 8) return "Password minimal 8 karakter.";
  if (s.length > 100) return "Password maksimal 100 karakter.";
  if (!/[a-z]/.test(s) || !/[A-Z]/.test(s) || !/\d/.test(s)) {
    return "Password harus mengandung huruf besar, huruf kecil, dan angka.";
  }
  return null;
}

export function validasiAdmin(v, { buat = false } = {}) {
  const e = {};
  const set = (k, msg) => msg && (e[k] = msg);
  set("nama", len(v.nama, 3, 100, "Nama"));
  if (buat) {
    const u = String(v.username ?? "").trim();
    if (!u) e.username = "Username wajib diisi";
    else if (u.length < 3) e.username = "Username minimal 3 karakter";
    else if (u.length > 50) e.username = "Username maksimal 50 karakter";
    else if (!/^[a-z0-9._-]+$/i.test(u)) e.username = "Username hanya boleh huruf, angka, titik, underscore, dan strip";
    const pw = validasiPasswordBaru(v.password);
    if (pw) e.password = pw;
  }
  const em = String(v.email ?? "").trim();
  if (em && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)) e.email = "Format email tidak valid";
  return e;
}

const PIN_RE = /^\d{4,12}$/;

/** Siswa: nim 3–30 [A-Za-z0-9._-], nama 2–100, kelas 1–50, pin (opsional) 4–12 digit. */
export function validasiSiswa(v, { buat = false } = {}) {
  const e = {};
  const set = (k, msg) => msg && (e[k] = msg);
  if (buat) {
    const nim = String(v.nim ?? "").trim();
    if (!nim) e.nim = "NIM wajib diisi";
    else if (!/^[A-Za-z0-9._-]{3,30}$/.test(nim)) e.nim = "NIM 3–30 karakter (huruf, angka, titik, strip, underscore)";
    if (v.pin && !PIN_RE.test(String(v.pin).trim())) e.pin = "PIN harus 4–12 digit angka";
  }
  set("nama", len(v.nama, 2, 100, "Nama"));
  set("kelas", len(v.kelas, 1, 50, "Kelas"));
  return e;
}

export const validasiPin = (pin) => (!pin || PIN_RE.test(String(pin).trim()) ? null : "PIN harus 4–12 digit angka");

/** Soal — mencerminkan soal/model.js. Mengembalikan { field: pesan }. */
export function validasiSoal(v) {
  const e = {};
  const set = (k, msg) => msg && (e[k] = msg);
  set("teks", len(v.teks, 1, 2000, "Teks soal"));
  set("mapel", len(v.mapel, 0, 100, "Mapel"));
  if (v.tipe === "pilihan_ganda") {
    const opsi = v.opsi || [];
    if (opsi.length < 2) e.opsi = "Pilihan ganda minimal memiliki 2 opsi.";
    else if (opsi.length > 8) e.opsi = "Pilihan ganda maksimal 8 opsi.";
    else if (opsi.some((o) => !String(o.teks || "").trim())) e.opsi = "Teks setiap opsi wajib diisi.";
    else if (opsi.some((o) => String(o.teks).trim().length > 300)) e.opsi = "Teks opsi maksimal 300 karakter.";
    else if (opsi.filter((o) => o.is_benar).length !== 1) e.opsi = "Pilih tepat 1 jawaban benar.";
  } else if (v.tipe === "isian") {
    const acuan = (v.jawaban_acuan || []).filter((x) => String(x).trim());
    if (v.mode_periksa === "otomatis" && acuan.length === 0) {
      e.jawaban_acuan = "Pemeriksaan otomatis wajib punya minimal 1 jawaban acuan.";
    }
    if (acuan.some((x) => String(x).trim().length > 500)) e.jawaban_acuan = "Jawaban acuan maksimal 500 karakter.";
    set("rubrik", len(v.rubrik, 0, 2000, "Rubrik"));
  }
  return e;
}

/** Kuis — mencerminkan kuis/model.js + validasi controller. `mulai`/`selesai` = "yyyy-mm-ddThh:mm". */
export function validasiKuis(v, { kunciJadwal = false } = {}) {
  const e = {};
  const set = (k, msg) => msg && (e[k] = msg);
  set("judul", len(v.judul, 3, 150, "Judul"));
  set("deskripsi", len(v.deskripsi, 0, 1000, "Deskripsi"));
  set("mapel", len(v.mapel, 0, 100, "Mapel"));
  if (!kunciJadwal) {
    if (!v.mulai) e.mulai = "Jadwal mulai wajib diisi";
    if (!v.selesai) e.selesai = "Jadwal berakhir wajib diisi";
    if (v.mulai && v.selesai && v.mulai >= v.selesai) e.selesai = "Waktu berakhir harus setelah waktu mulai";
    const d = Number(v.durasi_soal_detik);
    if (!Number.isFinite(d) || d < 3 || d > 60) e.durasi_soal_detik = "Durasi soal 3–60 detik";
    if (!(v.kelas || []).length) e.kelas = "Pilih minimal 1 kelas yang akan mengikuti kuis.";
  }
  return e;
}
