import { API_URL, TOKEN_KEY } from "config";

// ─── Penyimpanan token (per peran: "admin" | "siswa") ────────────────────────
export const getToken = (role) => {
  try {
    return window.localStorage.getItem(TOKEN_KEY[role]);
  } catch {
    return null;
  }
};
export const setToken = (role, token) => {
  try {
    window.localStorage.setItem(TOKEN_KEY[role], token);
  } catch {
    /* storage diblokir — sesi hanya berlaku sampai halaman dimuat ulang */
  }
};
export const clearToken = (role) => {
  try {
    window.localStorage.removeItem(TOKEN_KEY[role]);
  } catch {
    /* abaikan */
  }
};

/** Dipancarkan saat server menyatakan sesi sebuah peran tidak berlaku. detail = { role } */
export const AUTH_EXPIRED_EVENT = "auth:expired";

/**
 * Kode galat 401/403 backend yang berarti SESI sudah tidak berlaku (→ paksa keluar).
 * Kode lain (LOGIN_GAGAL, PASSWORD_LAMA_SALAH, AKSES_DITOLAK, ...) BUKAN akhir sesi.
 */
const KODE_SESI_BERAKHIR = new Set(["TOKEN_TIDAK_ADA", "SESI_KEDALUWARSA", "AKUN_NONAKTIF", "PESERTA_NONAKTIF"]);

// ─── Error ───────────────────────────────────────────────────────────────────
export class ApiError extends Error {
  constructor(message, { status = 0, code = "", body = null } = {}) {
    super(message);
    this.name = "ApiError";
    this.status = status; // 0 = tidak terhubung ke server
    this.code = code; // kode backend, mis. "JAWABAN_TERLAMBAT"
    this.body = body;
  }
}

// ─── Util ────────────────────────────────────────────────────────────────────
function buildUrl(path, query) {
  const url = new URL(`${API_URL}${path}`, window.location.href);
  if (query) {
    for (const [k, v] of Object.entries(query)) {
      if (v === undefined || v === null || v === "") continue;
      url.searchParams.set(k, v);
    }
  }
  return url.toString();
}

/**
 * Opsi:
 *  role         "admin" | "siswa" | null (tanpa token)
 *  body         objek → JSON
 *  formData     FormData → multipart (Content-Type diatur browser)
 *  expireOnAuth false → jangan paksa keluar walau 401 (mis. login)
 */
async function send(path, { role = null, method = "GET", body, formData, query, signal, headers: extra, expireOnAuth = true } = {}) {
  const headers = { ...(extra || {}) };
  if (role) {
    const token = getToken(role);
    if (token) headers.Authorization = `Bearer ${token}`;
  }
  let payload;
  if (formData) {
    payload = formData;
  } else if (body !== undefined) {
    headers["Content-Type"] = "application/json";
    payload = JSON.stringify(body);
  }

  let res;
  try {
    res = await fetch(buildUrl(path, query), { method, headers, body: payload, signal });
  } catch (err) {
    if (err.name === "AbortError") throw err;
    throw new ApiError("Tidak dapat terhubung ke server. Periksa koneksi atau pastikan backend sedang berjalan.");
  }
  return { res, role, expireOnAuth };
}

async function failFrom(res, role, expireOnAuth) {
  let body = null;
  try {
    body = await res.json();
  } catch {
    /* bukan JSON */
  }
  const code = body?.code || `HTTP_${res.status}`;
  const message =
    body?.message ||
    (res.status === 429 ? "Terlalu banyak permintaan, coba lagi sebentar." : `Permintaan gagal (HTTP ${res.status}).`);
  if (role && expireOnAuth && [401, 403].includes(res.status) && KODE_SESI_BERAKHIR.has(code)) {
    clearToken(role);
    window.dispatchEvent(new CustomEvent(AUTH_EXPIRED_EVENT, { detail: { role } }));
  }
  const retry = Number(res.headers.get("Retry-After"));
  const err = new ApiError(message, { status: res.status, code, body });
  if (retry) err.retryAfter = retry;
  return err;
}

/** Panggilan JSON. Mengembalikan `body.data` (backend: { error, message?, data? }). */
export async function request(path, opts) {
  const { res, role, expireOnAuth } = await send(path, opts);
  if (!res.ok) throw await failFrom(res, role, expireOnAuth);
  let body;
  try {
    body = await res.json();
  } catch {
    throw new ApiError("Respons server tidak valid.", { status: res.status });
  }
  if (body?.error) throw new ApiError(body.message || "Terjadi kesalahan.", { status: res.status, code: body.code, body });
  return body;
}

/** Seperti request, tetapi mengembalikan hanya `data`. */
export const requestData = (path, opts) => request(path, opts).then((r) => r.data);

/** Panggilan yang menghasilkan file (mis. CSV). Mengembalikan Blob. */
export async function requestBlob(path, opts) {
  const { res, role, expireOnAuth } = await send(path, opts);
  if (!res.ok) throw await failFrom(res, role, expireOnAuth);
  return res.blob();
}

/**
 * Server-Sent Events lewat fetch streaming (EventSource tidak bisa mengirim header Authorization).
 * onEvent(nama, data) dipanggil tiap event; heartbeat komentar → onEvent("_hb", null).
 * Promise selesai saat server menutup stream; melempar ApiError bila gagal tersambung.
 */
export async function stream(path, { role, signal, onEvent }) {
  let res;
  try {
    res = await fetch(buildUrl(path), {
      headers: { Authorization: `Bearer ${getToken(role)}`, Accept: "text/event-stream" },
      signal,
    });
  } catch (err) {
    if (err.name === "AbortError") throw err;
    throw new ApiError("Koneksi stream terputus.");
  }
  if (!res.ok) throw await failFrom(res, role, true);
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let buf = "";
  for (;;) {
    const { done, value } = await reader.read();
    if (done) return;
    buf += dec.decode(value, { stream: true });
    let i;
    while ((i = buf.indexOf("\n\n")) >= 0) {
      const blok = buf.slice(0, i);
      buf = buf.slice(i + 2);
      const ev = /^event: (.+)$/m.exec(blok);
      const dt = /^data: (.+)$/m.exec(blok);
      if (ev && dt) {
        try {
          onEvent(ev[1], JSON.parse(dt[1]));
        } catch {
          /* abaikan data rusak */
        }
      } else {
        onEvent("_hb", null);
      }
    }
  }
}
