// Konfigurasi runtime frontend. Nilai dibaca dari .env (REACT_APP_*) saat build/start.
// Di GitHub Pages nilai ini "dipanggang" ke dalam bundle saat `npm run build`,
// jadi JANGAN menaruh rahasia apa pun di .env (isi bundle bisa dibaca siapa saja).

const trimSlash = (s) => String(s || "").replace(/\/+$/, "");

/** URL dasar API backend kuis, termasuk awalan /api. */
export const API_URL = trimSlash(process.env.REACT_APP_API_URL || "http://localhost:3000/api");

/**
 * Basis tempat file statis backend dilayani (gambar soal ada di {BASE}/uploads/<nama>).
 * Default: API_URL tanpa akhiran "/api". Isi REACT_APP_UPLOAD_BASE_URL bila berbeda.
 */
export const UPLOAD_BASE_URL = trimSlash(
  process.env.REACT_APP_UPLOAD_BASE_URL || API_URL.replace(/\/api$/, "")
);

/** URL gambar soal dari nama berkas yang disimpan backend (UUID.ext). */
export const urlGambar = (nama) => (nama ? `${UPLOAD_BASE_URL}/uploads/${encodeURIComponent(nama)}` : "");

// Token tiap peran disimpan terpisah, sehingga admin & siswa bisa login di browser yang sama.
export const TOKEN_KEY = { admin: "kuis_admin_token", siswa: "kuis_siswa_token" };
