import React from "react";
import { Alert, Button, Input, Modal, ModalBody, ModalFooter, ModalHeader, Table } from "reactstrap";
import * as soalApi from "services/soalApi";
import { parseCsv } from "utils/csv";
import { unduhTemplateSoal } from "utils/templates";

const MAKS_BYTE = 2e6;
const BATCH = 200; // batas backend per permintaan

/** Kirim semua baris per 200 (uji=true → hanya validasi). Nomor baris gagal = nomor baris di file (judul = baris 1). */
async function kirimSemua(baris, uji, onProgres) {
  let berhasil = 0;
  const gagal = [];
  for (let i = 0; i < baris.length; i += BATCH) {
    const d = await soalApi.importMassal(baris.slice(i, i + BATCH), uji);
    berhasil += d.berhasil;
    gagal.push(...d.gagal.map((g) => ({ ...g, baris: i + g.baris + 1 })));
    onProgres?.(Math.min(i + BATCH, baris.length));
  }
  return { berhasil, gagal };
}

/**
 * Impor soal dari CSV: baca file → PRATINJAU (validasi di server, belum disimpan) → konfirmasi → simpan.
 * Gambar tidak bisa diimpor lewat CSV (unggah manual di form soal).
 */
function ImporSoal({ onClose, onSelesai }) {
  const [baris, setBaris] = React.useState(null);
  const [namaFile, setNamaFile] = React.useState("");
  const [pratinjau, setPratinjau] = React.useState(null); // { berhasil, gagal }
  const [hasil, setHasil] = React.useState(null);
  const [error, setError] = React.useState("");
  const [proses, setProses] = React.useState(""); // "" | "uji" | "simpan"
  const [progres, setProgres] = React.useState(0);

  const pilihFile = async (e) => {
    const f = e.target.files?.[0];
    setPratinjau(null);
    setHasil(null);
    setError("");
    setBaris(null);
    if (!f) return;
    if (f.size > MAKS_BYTE) return setError("File terlalu besar (maks 2 MB).");
    const rows = parseCsv(await f.text());
    if (rows.length < 2) return setError("CSV kosong atau hanya berisi baris judul.");
    const kol = rows[0].map((x) => x.trim().toLowerCase());
    if (!kol.includes("tipe") || !kol.includes("teks")) {
      return setError("Baris judul harus memuat kolom 'tipe' dan 'teks'. Gunakan template.");
    }
    const data = rows.slice(1).map((r) => Object.fromEntries(kol.map((k, i) => [k, (r[i] || "").trim()])));
    setNamaFile(f.name);
    setBaris(data);
    setProses("uji");
    setProgres(0);
    try {
      setPratinjau(await kirimSemua(data, true, setProgres));
    } catch (err) {
      setError(err.message);
    } finally {
      setProses("");
    }
  };

  const simpan = async () => {
    setError("");
    setProses("simpan");
    setProgres(0);
    try {
      const r = await kirimSemua(baris, false, setProgres);
      setHasil(r);
      if (r.berhasil) onSelesai();
    } catch (err) {
      // Batch sebelumnya sudah tersimpan; muat ulang daftar agar terlihat.
      setError(`Impor berhenti: ${err.message} Soal pada batch sebelumnya sudah tersimpan.`);
      onSelesai();
    } finally {
      setProses("");
    }
  };

  const tabelGagal = (daftar) => (
    <div style={{ maxHeight: 260, overflowY: "auto" }}>
      <Table size="sm">
        <tbody>
          {daftar.slice(0, 50).map((g, i) => (
            <tr key={i}>
              <td style={{ whiteSpace: "nowrap" }}>Baris {g.baris}</td>
              <td className="text-danger" style={{ whiteSpace: "normal" }}>{g.alasan}</td>
            </tr>
          ))}
        </tbody>
      </Table>
      {daftar.length > 50 ? <small className="text-muted">…dan {daftar.length - 50} baris lain.</small> : null}
    </div>
  );

  const sibuk = !!proses;
  return (
    <Modal isOpen toggle={sibuk ? undefined : onClose} centered size="lg">
      <ModalHeader toggle={sibuk ? undefined : onClose}>Impor soal dari CSV</ModalHeader>
      <ModalBody>
        {error ? <Alert color="danger">{error}</Alert> : null}
        {!hasil ? (
          <>
            <p>
              Gunakan template (<Button color="link" size="sm" className="p-0 align-baseline" onClick={unduhTemplateSoal}>unduh template</Button>).
              Kolom: <code>tipe, teks, opsi_a…opsi_h, jawaban_benar, acak_opsi, mode_periksa, jawaban_acuan, kata_kunci, rubrik, mapel</code>.
              Beberapa jawaban acuan / kata kunci dipisah <code>|</code>. <code>tipe</code>: <code>pilihan_ganda</code> (atau <code>pg</code>),
              <code> isian</code>, atau <code>uraian</code> (isian dengan pemeriksaan manual). Gambar tidak bisa diimpor lewat CSV.
            </p>
            <Input type="file" accept=".csv,text/csv" onChange={pilihFile} disabled={sibuk} />
            {proses === "uji" ? <p className="mt-3 mb-0 text-info">Memeriksa file… {progres}/{baris?.length}</p> : null}
            {pratinjau ? (
              <div className="mt-3">
                <Alert color={pratinjau.gagal.length ? "warning" : "success"}>
                  <b>{namaFile}</b> — pratinjau: {pratinjau.berhasil} baris valid, {pratinjau.gagal.length} bermasalah.{" "}
                  {pratinjau.gagal.length
                    ? "Baris bermasalah akan dilewati; perbaiki di file lalu impor ulang, atau lanjutkan hanya yang valid."
                    : "Belum ada yang tersimpan sampai Anda menekan Impor."}
                </Alert>
                {pratinjau.gagal.length ? tabelGagal(pratinjau.gagal) : null}
              </div>
            ) : null}
            {proses === "simpan" ? <p className="mt-3 mb-0 text-info">Menyimpan… {progres}/{baris?.length}</p> : null}
          </>
        ) : (
          <>
            <Alert color={hasil.gagal.length ? "warning" : "success"}>
              {hasil.berhasil} soal diimpor{hasil.gagal.length ? `, ${hasil.gagal.length} gagal` : ""}.
            </Alert>
            {hasil.gagal.length ? tabelGagal(hasil.gagal) : null}
          </>
        )}
      </ModalBody>
      <ModalFooter>
        {!hasil ? (
          <>
            <Button color="secondary" onClick={onClose} disabled={sibuk}>Batal</Button>
            <Button color="primary" className="btn-fill" onClick={simpan} disabled={sibuk || !pratinjau || pratinjau.berhasil === 0}>
              {proses === "simpan" ? "Menyimpan..." : `Impor ${pratinjau ? pratinjau.berhasil : 0} soal`}
            </Button>
          </>
        ) : (
          <Button color="primary" className="btn-fill" onClick={onClose}>Tutup</Button>
        )}
      </ModalFooter>
    </Modal>
  );
}

export default ImporSoal;
