import { request, requestData } from "./api";

// Semua endpoint admin. Bentuk respons backend: { error, message?, data? }

/** GET /admin/captcha → { enabled, captcha_id?, gambar_svg? } */
export const captcha = () => requestData("/admin/captcha", { role: null });

/** POST /admin/login → { token, kedaluwarsa_at, admin }. Captcha dikirim bila backend mengaktifkannya. */
export const login = (username, password, captchaId, captchaJawaban) =>
  requestData("/admin/login", {
    method: "POST",
    expireOnAuth: false,
    body: { username, password, ...(captchaId ? { captcha_id: captchaId, captcha: captchaJawaban } : {}) },
  });

/** POST /admin/logout — mencabut sesi di server (best effort). */
export const logout = () => request("/admin/logout", { role: "admin", method: "POST", expireOnAuth: false });

/** GET /admin/profil */
export const profil = () => requestData("/admin/profil", { role: "admin" });

/**
 * POST /admin/ubah-password. Backend membalas 401 PASSWORD_LAMA_SALAH bila password lama salah
 * (bukan sesi habis). Bila sukses, SEMUA sesi admin dicabut → pemanggil harus keluar.
 */
export const ubahPassword = (password_lama, password_baru) =>
  request("/admin/ubah-password", { role: "admin", method: "POST", body: { password_lama, password_baru } });

// ── Kelola akun admin: /admin/akun ──
export const list = () => requestData("/admin/akun", { role: "admin" });
export const create = (data) => requestData("/admin/akun", { role: "admin", method: "POST", body: data });
/** Hanya { nama, email, is_aktif } yang diterima backend. */
export const update = (id, data) => requestData(`/admin/akun/${id}`, { role: "admin", method: "PUT", body: data });
export const remove = (id) => request(`/admin/akun/${id}`, { role: "admin", method: "DELETE" });
