import React from "react";
import { FormGroup, Input } from "reactstrap";

/**
 * Field form dengan label + pesan error. Memakai kelas `has-danger` bawaan Black Dashboard
 * untuk gaya invalid. Semua prop lain diteruskan ke <Input>.
 */
function FormField({ label, name, error, hint, required, children, ...inputProps }) {
  return (
    <FormGroup className={error ? "has-danger" : ""}>
      <label htmlFor={name}>
        {label}
        {required ? <span className="text-danger"> *</span> : null}
      </label>
      {children || <Input id={name} name={name} invalid={!!error} {...inputProps} />}
      {error ? (
        <small className="text-danger d-block mt-1" role="alert">
          {error}
        </small>
      ) : hint ? (
        <small className="text-muted d-block mt-1">{hint}</small>
      ) : null}
    </FormGroup>
  );
}

export default FormField;
