import React from "react";
import { Pagination, PaginationItem, PaginationLink } from "reactstrap";

// Nomor halaman yang ditampilkan: 1 … (p-1) p (p+1) … N
function nomorHalaman(page, total) {
  const set = new Set([1, total, page, page - 1, page + 1]);
  const arr = [...set].filter((n) => n >= 1 && n <= total).sort((a, b) => a - b);
  const out = [];
  arr.forEach((n, i) => {
    if (i > 0 && n - arr[i - 1] > 1) out.push("…" + n);
    out.push(n);
  });
  return out;
}

/** Paginasi berdasarkan `meta` dari backend: { page, limit, total, total_halaman }. */
function Pager({ meta, onPage }) {
  if (!meta || meta.total_halaman <= 1) return null;
  const { page, total_halaman: total } = meta;
  const go = (n) => (e) => {
    e.preventDefault();
    onPage(n);
  };
  return (
    <Pagination className="pagination-info mb-0" listClassName="justify-content-end mb-0">
      <PaginationItem disabled={page <= 1}>
        <PaginationLink previous href="#" onClick={go(page - 1)} />
      </PaginationItem>
      {nomorHalaman(page, total).map((n) =>
        typeof n === "string" ? (
          <PaginationItem key={n} disabled>
            <PaginationLink href="#" onClick={(e) => e.preventDefault()}>…</PaginationLink>
          </PaginationItem>
        ) : (
          <PaginationItem key={n} active={n === page}>
            <PaginationLink href="#" onClick={go(n)}>{n}</PaginationLink>
          </PaginationItem>
        )
      )}
      <PaginationItem disabled={page >= total}>
        <PaginationLink next href="#" onClick={go(page + 1)} />
      </PaginationItem>
    </Pagination>
  );
}

export default Pager;
