/** Simpan Blob / teks sebagai berkas unduhan di browser. */
export function unduhBlob(blob, namaFile) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = namaFile;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export const unduhTeks = (teks, namaFile, mime = "text/csv;charset=utf-8") =>
  unduhBlob(new Blob([teks], { type: mime }), namaFile);
