import * as pesertaApi from "services/pesertaApi";

/**
 * Sinkron jam server. Soal aktif & batas waktu SELALU ditentukan server; klien hanya
 * menggambar hitung mundur dari `batas_ms` yang dikirim server, dikoreksi selisih jam.
 * Sampel dengan RTT terkecil dipilih; offset = serverNow - clientNow.
 */
const Waktu = {
  offset: 0,
  rtt: null,

  async sinkron(n = 5) {
    let best = null;
    for (let i = 0; i < n; i++) {
      const t0 = performance.now();
      const c0 = Date.now();
      try {
        const r = await pesertaApi.waktu();
        const rtt = performance.now() - t0;
        if (!best || rtt < best.rtt) best = { rtt, offset: r.server_now + rtt / 2 - (c0 + rtt) };
      } catch {
        /* lewati sampel gagal */
      }
    }
    if (best) {
      Waktu.offset = best.offset;
      Waktu.rtt = best.rtt;
    }
    return Waktu;
  },

  /** Waktu server perkiraan saat ini (ms). */
  now: () => Date.now() + Waktu.offset,

  /** Perhalus offset dari `server_now` di snapshot. */
  dariSnapshot(serverNow) {
    const est = serverNow + (Waktu.rtt || 0) / 2 - Date.now();
    Waktu.offset = Waktu.rtt == null ? est : Waktu.offset * 0.5 + est * 0.5;
  },
};

export default Waktu;
