import React from "react";
import { Link, NavLink, Navigate, Route, Routes, useLocation, useNavigate } from "react-router-dom";
import { Button, Container } from "reactstrap";
import { useAuth } from "contexts/AuthContext";
import { Loading } from "components/Feedback/Feedback";
import DaftarKuis from "views/siswa/DaftarKuis.js";
import RuangKuis from "views/siswa/RuangKuis.js";
import HasilSiswa from "views/siswa/HasilSiswa.js";
import DaftarProyek from "views/siswa/DaftarProyek.js";
import DetailProyek from "views/siswa/DetailProyek.js";
import logo from "assets/img/logo.svg";

/** Layout ringan untuk siswa: bilah atas + konten (tanpa sidebar admin). Dijaga login siswa. */
function Siswa() {
  const location = useLocation();
  const navigate = useNavigate();
  const { statusSiswa: status, siswa, logoutSiswa } = useAuth();

  if (status === "memeriksa") return <div className="auth-page"><Loading text="Memeriksa sesi..." /></div>;
  if (status !== "masuk") return <Navigate to="/login" replace state={{ dari: location }} />;

  const keluar = () => {
    navigate("/login", { replace: true });
    logoutSiswa();
  };

  return (
    <div className="siswa-shell">
      <header className="siswa-bar">
        <Container className="d-flex align-items-center">
          <Link to="/siswa/kuis" className="siswa-brand">
            <img src={logo} alt="" /> Kuis Real-Time
          </Link>
          <nav className="siswa-nav ml-3">
            <NavLink to="/siswa/kuis">Kuis</NavLink>
            <NavLink to="/siswa/proyek">Proyek</NavLink>
          </nav>
          <span className="flex-grow-1" />
          <span className="siswa-user d-none d-sm-inline">
            {siswa?.nama} <small className="text-muted">· {siswa?.kelas}</small>
          </span>
          <Button color="link" size="sm" className="ml-2" onClick={keluar}>
            Keluar
          </Button>
        </Container>
      </header>
      <Container className="siswa-content">
        <Routes>
          <Route path="kuis" element={<DaftarKuis />} />
          <Route path="kuis/:id" element={<RuangKuis />} />
          <Route path="kuis/:id/hasil" element={<HasilSiswa />} />
          <Route path="proyek" element={<DaftarProyek />} />
          <Route path="proyek/:id" element={<DetailProyek />} />
          <Route path="*" element={<Navigate to="/siswa/kuis" replace />} />
        </Routes>
      </Container>
    </div>
  );
}

export default Siswa;
