import React from "react";
import { useParams } from "react-router-dom";
import { Card, CardBody, CardHeader } from "reactstrap";
import * as proyekApi from "services/proyekApi";
import { Loading } from "components/Feedback/Feedback";
import { formatTanggalWaktu } from "utils/format";
import logo from "assets/img/komputer.svg";

/** Halaman PUBLIK (tanpa login) tujuan QR tanda tangan dosen pada laporan proyek. */
function VerifikasiProyek() {
  const { kode } = useParams();
  const [d, setD] = React.useState(null);
  const [galat, setGalat] = React.useState(null);

  React.useEffect(() => {
    const ac = new AbortController();
    proyekApi.verifikasi(kode, ac.signal).then(setD).catch((e) => e.name !== "AbortError" && setGalat(e));
    return () => ac.abort();
  }, [kode]);

  const Baris = ({ l, v }) => (
    <div className="mb-3"><small className="text-muted d-block">{l}</small><b>{v}</b></div>
  );

  return (
    <div className="auth-page">
      <div style={{ width: "100%", maxWidth: 480 }}>
        <div className="auth-brand">
          <img src={logo} alt="" />
          <h1>Verifikasi Laporan Proyek</h1>
        </div>
        <Card>
          <CardHeader>
            <h4 className={`card-title mb-0 ${d ? "text-success" : galat ? "text-danger" : ""}`}>
              {d ? "✔ Dokumen sah" : galat ? "✖ Tidak dapat diverifikasi" : "Memeriksa..."}
            </h4>
          </CardHeader>
          <CardBody>
            {!d && !galat ? <Loading text="Memeriksa kode..." /> : null}
            {galat ? (
              <p className="mb-0">{galat.status === 404 ? "Kode verifikasi tidak dikenali. QR mungkin rusak atau dokumen tidak asli." : galat.message}</p>
            ) : null}
            {d ? (
              <>
                <Baris l="Dosen pengampu" v={d.nama_dosen} />
                {d.nama_tugas ? <Baris l="Tugas" v={d.nama_tugas} /> : null}
                <Baris l="Nama kelompok" v={d.nama_kelompok} />
                <Baris l="Nama proyek" v={d.nama_proyek} />
                <Baris l="Kelas" v={d.kelas} />
                <Baris l="Disahkan final pada" v={formatTanggalWaktu(d.final_at)} />
                <small className="text-muted">Proyek ini tercatat final di sistem dan disahkan oleh dosen pengampu di atas.</small>
              </>
            ) : null}
          </CardBody>
        </Card>
      </div>
    </div>
  );
}

export default VerifikasiProyek;
