import { request, requestData, stream } from "./api";

// Sisi siswa: /siswa/*  (peran "siswa")

/** GET /waktu (publik) → { server_now } — untuk sinkron jam klien. */
export const waktu = () => requestData("/waktu", { role: null });

/** GET /siswa/captcha → { enabled, captcha_id?, gambar_svg? } (sama seperti captcha admin; sekali pakai, 2 menit) */
export const captcha = () => requestData("/siswa/captcha", { role: null });

/** POST /siswa/login { nim, pin, captcha_id?, captcha? } → { token, kedaluwarsa_at, siswa } */
export const login = (nim, pin, captchaId, captchaJawaban) =>
  requestData("/siswa/login", {
    method: "POST",
    expireOnAuth: false,
    body: { nim, pin, ...(captchaId ? { captcha_id: captchaId, captcha: captchaJawaban } : {}) },
  });
export const logout = () => request("/siswa/logout", { role: "siswa", method: "POST", expireOnAuth: false });
export const profil = () => requestData("/siswa/profil", { role: "siswa" });

/** GET /siswa/kuis → { server_now, kuis[] } */
export const daftarKuis = (signal) => requestData("/siswa/kuis", { role: "siswa", signal });
/** GET /siswa/kuis/:id → { server_now, kuis } */
export const detailKuis = (id, signal) => requestData(`/siswa/kuis/${id}`, { role: "siswa", signal });
/** GET /siswa/kuis/:id/snapshot — bergabung + status sesi. gabung=false → hanya baca. */
export const snapshot = (id, { gabung = true } = {}, signal) =>
  requestData(`/siswa/kuis/${id}/snapshot`, { role: "siswa", query: gabung ? undefined : { gabung: "0" }, signal });
/** POST /siswa/kuis/:id/jawaban { id_soal, id_opsi | teks, kunci_idempoten } */
export const jawab = (id, payload) =>
  requestData(`/siswa/kuis/${id}/jawaban`, { role: "siswa", method: "POST", body: payload });
export const hasil = (id, signal) => requestData(`/siswa/kuis/${id}/hasil`, { role: "siswa", signal });
export const leaderboard = (id, signal) => requestData(`/siswa/kuis/${id}/leaderboard`, { role: "siswa", signal });
/** GET /siswa/kuis/:id/stream (SSE) — event: snapshot | hasil | selesai | sesi_berakhir */
export const alirStream = (id, { signal, onEvent }) => stream(`/siswa/kuis/${id}/stream`, { role: "siswa", signal, onEvent });
