import React from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import {
  Alert, Button, Card, CardBody, CardFooter, CardHeader, CardTitle, Col, FormGroup, Input, Label, Row,
} from "reactstrap";
import * as soalApi from "services/soalApi";
import { urlGambar } from "config";
import { useNotify } from "contexts/NotifyContext";
import FormField from "components/FormField/FormField";
import { ErrorBox, Loading } from "components/Feedback/Feedback";
import { TIPE_SOAL } from "utils/format";
import { validasiSoal } from "utils/validasi";

const opsiKosong = () => ({ teks: "", is_benar: false });
const AWAL = {
  tipe: "pilihan_ganda", teks: "", mapel: "", gambar: "",
  opsi: [opsiKosong(), opsiKosong(), opsiKosong(), opsiKosong()], acak_opsi: false,
  mode_periksa: "otomatis", jawaban_acuan: [""], kata_kunci: [], rubrik: "",
  aturan: { abaikan_kapital: true, abaikan_spasi: true, abaikan_tanda_baca: false },
};

const dariServer = (s) => ({
  tipe: s.tipe, teks: s.teks || "", mapel: s.mapel || "", gambar: s.gambar || "",
  opsi: s.opsi?.length ? s.opsi.map((o) => ({ id_opsi: o.id_opsi, teks: o.teks, is_benar: !!o.is_benar })) : AWAL.opsi,
  acak_opsi: !!s.acak_opsi, mode_periksa: s.mode_periksa || "otomatis",
  jawaban_acuan: s.jawaban_acuan?.length ? s.jawaban_acuan : [""], kata_kunci: s.kata_kunci || [], rubrik: s.rubrik || "",
  aturan: {
    abaikan_kapital: s.aturan?.abaikan_kapital !== false,
    abaikan_spasi: s.aturan?.abaikan_spasi !== false,
    abaikan_tanda_baca: !!s.aturan?.abaikan_tanda_baca,
  },
});

/** Daftar string yang bisa ditambah/dihapus (jawaban acuan, kata kunci). */
function DaftarTeks({ nilai, onChange, placeholder, disabled, maks = 20 }) {
  const set = (i, v) => onChange(nilai.map((x, j) => (j === i ? v : x)));
  return (
    <>
      {nilai.map((v, i) => (
        <div className="d-flex mb-2" key={i}>
          <Input value={v} placeholder={placeholder} maxLength={500} disabled={disabled} onChange={(e) => set(i, e.target.value)} />
          <Button type="button" color="danger" className="btn-link btn-icon ml-2" disabled={disabled} title="Hapus" onClick={() => onChange(nilai.filter((_, j) => j !== i))}>
            <i className="tim-icons icon-simple-remove" />
          </Button>
        </div>
      ))}
      <Button type="button" size="sm" color="secondary" disabled={disabled || nilai.length >= maks} onClick={() => onChange([...nilai, ""])}>
        <i className="tim-icons icon-simple-add" /> Tambah
      </Button>
    </>
  );
}

function Centang({ label, checked, onChange, disabled, hint }) {
  return (
    <FormGroup check className="mb-2">
      <Label check>
        <Input type="checkbox" checked={checked} disabled={disabled} onChange={(e) => onChange(e.target.checked)} />
        <span className="form-check-sign"><span className="check" /></span>
        {label} {hint ? <small className="text-muted">{hint}</small> : null}
      </Label>
    </FormGroup>
  );
}

function SoalForm() {
  const { id } = useParams();
  const edit = !!id;
  const navigate = useNavigate();
  const notify = useNotify();
  const [v, setV] = React.useState(AWAL);
  const [terkunci, setTerkunci] = React.useState(false);
  const [errors, setErrors] = React.useState({});
  const [serverError, setServerError] = React.useState("");
  const [loadError, setLoadError] = React.useState(null);
  const [loading, setLoading] = React.useState(edit);
  const [saving, setSaving] = React.useState(false);
  const [mengunggah, setMengunggah] = React.useState(false);

  React.useEffect(() => {
    if (!edit) return;
    const ac = new AbortController();
    setLoading(true);
    soalApi
      .get(id, ac.signal)
      .then((s) => {
        setV(dariServer(s));
        setTerkunci(!!s.terkunci);
      })
      .catch((err) => err.name !== "AbortError" && setLoadError(err))
      .finally(() => !ac.signal.aborted && setLoading(false));
    return () => ac.abort();
  }, [edit, id]);

  const set = (k, val) => {
    setV((x) => ({ ...x, [k]: val }));
    if (errors[k]) setErrors((er) => ({ ...er, [k]: undefined }));
  };
  const setOpsi = (i, patch) => set("opsi", v.opsi.map((o, j) => (j === i ? { ...o, ...patch } : o)));
  const pilihBenar = (i) => set("opsi", v.opsi.map((o, j) => ({ ...o, is_benar: j === i })));

  const unggah = async (e) => {
    const f = e.target.files?.[0];
    e.target.value = "";
    if (!f) return;
    setMengunggah(true);
    try {
      const r = await soalApi.unggahGambar(f);
      set("gambar", r.gambar);
      notify.sukses("Gambar diunggah.");
    } catch (err) {
      notify.gagal(err.message);
    } finally {
      setMengunggah(false);
    }
  };

  const simpan = async (e) => {
    e.preventDefault();
    const er = validasiSoal(v);
    setErrors(er);
    if (Object.keys(er).length) return;
    setSaving(true);
    setServerError("");
    const pg = v.tipe === "pilihan_ganda";
    const payload = {
      tipe: v.tipe, teks: v.teks.trim(), mapel: v.mapel.trim(), gambar: v.gambar,
      ...(pg
        ? {
            acak_opsi: v.acak_opsi,
            opsi: v.opsi.map((o) => ({ ...(o.id_opsi ? { id_opsi: o.id_opsi } : {}), teks: o.teks.trim(), is_benar: !!o.is_benar })),
          }
        : {
            mode_periksa: v.mode_periksa,
            jawaban_acuan: v.jawaban_acuan.map((x) => x.trim()).filter(Boolean),
            aturan: v.aturan,
            kata_kunci: v.kata_kunci.map((x) => x.trim()).filter(Boolean),
            rubrik: v.rubrik.trim(),
          }),
    };
    try {
      if (edit) await soalApi.update(id, payload);
      else await soalApi.create(payload);
      notify.sukses(edit ? "Soal diperbarui." : "Soal dibuat.");
      navigate("/admin/soal");
    } catch (err) {
      setServerError(err.message);
      setSaving(false);
    }
  };

  if (loading) return <div className="content"><Loading /></div>;
  if (loadError) return <div className="content"><ErrorBox error={loadError} /><Button tag={Link} to="/admin/soal" color="secondary">Kembali</Button></div>;

  const lock = terkunci || saving;
  const pg = v.tipe === "pilihan_ganda";

  return (
    <div className="content">
      <Row>
        <Col lg="9">
          <Card>
            <CardHeader><CardTitle tag="h4" className="mb-0">{edit ? "Ubah soal" : "Soal baru"}</CardTitle></CardHeader>
            <form onSubmit={simpan} noValidate>
              <CardBody>
                {terkunci ? (
                  <Alert color="warning">
                    Soal ini dipakai kuis yang sudah diterbitkan sehingga <b>tidak bisa diubah</b>. Kembali ke daftar lalu pilih
                    <b> Duplikasi</b> untuk membuat versi baru.
                  </Alert>
                ) : null}
                {serverError ? <Alert color="danger">{serverError}</Alert> : null}

                <Row>
                  <Col md="6">
                    <FormField label="Tipe soal" name="tipe">
                      <Input id="tipe" type="select" value={v.tipe} disabled={lock} onChange={(e) => set("tipe", e.target.value)}>
                        {Object.entries(TIPE_SOAL).map(([k, l]) => <option key={k} value={k}>{l}</option>)}
                      </Input>
                    </FormField>
                  </Col>
                  <Col md="6">
                    <FormField label="Mapel" name="mapel" value={v.mapel} disabled={lock} onChange={(e) => set("mapel", e.target.value)} error={errors.mapel} maxLength={100} />
                  </Col>
                </Row>

                <FormField label="Teks soal" name="teks" required error={errors.teks}>
                  <Input id="teks" type="textarea" rows="4" maxLength={2000} value={v.teks} disabled={lock} invalid={!!errors.teks} onChange={(e) => set("teks", e.target.value)} />
                </FormField>

                <FormGroup>
                  <label>Gambar pendukung (opsional)</label>
                  {v.gambar ? (
                    <div className="mb-2">
                      <img src={urlGambar(v.gambar)} alt="Pratinjau gambar soal" className="soal-gambar-preview" />
                      <div>
                        <Button type="button" size="sm" color="danger" className="btn-link" disabled={lock} onClick={() => set("gambar", "")}>Lepas gambar</Button>
                      </div>
                    </div>
                  ) : null}
                  <Input type="file" accept="image/png,image/jpeg,image/webp,image/gif" disabled={lock || mengunggah} onChange={unggah} />
                  <small className="text-muted d-block mt-1">
                    {mengunggah ? "Mengunggah…" : "PNG, JPEG, WEBP, atau GIF. Ukuran maksimal ditentukan server (bawaan 2 MB)."}
                  </small>
                </FormGroup>

                {pg ? (
                  <>
                    <hr />
                    <h5>Pilihan jawaban</h5>
                    <p className="text-muted small">Isi 2–8 opsi, lalu pilih tepat satu jawaban yang benar (lingkaran di kiri).</p>
                    {v.opsi.map((o, i) => (
                      <div className="d-flex align-items-center mb-2" key={o.id_opsi || i}>
                        <Input type="radio" name="benar" className="mr-3 opsi-radio" checked={!!o.is_benar} disabled={lock} onChange={() => pilihBenar(i)} aria-label={`Opsi ${String.fromCharCode(65 + i)} benar`} />
                        <b className="mr-2">{String.fromCharCode(65 + i)}.</b>
                        <Input value={o.teks} placeholder={`Teks opsi ${String.fromCharCode(65 + i)}`} maxLength={300} disabled={lock} onChange={(e) => setOpsi(i, { teks: e.target.value })} />
                        <Button type="button" color="danger" className="btn-link btn-icon ml-2" disabled={lock || v.opsi.length <= 2} title="Hapus opsi" onClick={() => set("opsi", v.opsi.filter((_, j) => j !== i))}>
                          <i className="tim-icons icon-simple-remove" />
                        </Button>
                      </div>
                    ))}
                    {errors.opsi ? <small className="text-danger d-block mb-2" role="alert">{errors.opsi}</small> : null}
                    <Button type="button" size="sm" color="secondary" disabled={lock || v.opsi.length >= 8} onClick={() => set("opsi", [...v.opsi, opsiKosong()])}>
                      <i className="tim-icons icon-simple-add" /> Tambah opsi
                    </Button>
                    <div className="mt-3">
                      <Centang label="Acak urutan opsi" hint="(urutan stabil per siswa; refresh tidak mengubahnya)" checked={v.acak_opsi} disabled={lock} onChange={(c) => set("acak_opsi", c)} />
                    </div>
                  </>
                ) : (
                  <>
                    <hr />
                    <h5>Pemeriksaan jawaban isian</h5>
                    <FormField label="Cara memeriksa" name="mode_periksa">
                      <Input id="mode_periksa" type="select" value={v.mode_periksa} disabled={lock} onChange={(e) => set("mode_periksa", e.target.value)}>
                        <option value="otomatis">Otomatis (cocokkan dengan jawaban acuan)</option>
                        <option value="manual">Manual (admin menentukan benar/salah)</option>
                      </Input>
                    </FormField>
                    <FormGroup className={errors.jawaban_acuan ? "has-danger" : ""}>
                      <label>
                        Jawaban acuan{v.mode_periksa === "otomatis" ? <span className="text-danger"> *</span> : <span className="text-muted"> (opsional untuk pemeriksaan manual)</span>}
                      </label>
                      <DaftarTeks nilai={v.jawaban_acuan} onChange={(x) => set("jawaban_acuan", x)} placeholder="Salah satu jawaban yang dianggap benar" disabled={lock} />
                      {errors.jawaban_acuan ? <small className="text-danger d-block mt-1" role="alert">{errors.jawaban_acuan}</small> : null}
                    </FormGroup>
                    <label>Aturan pencocokan</label>
                    <Centang label="Abaikan huruf besar/kecil" checked={v.aturan.abaikan_kapital} disabled={lock} onChange={(c) => set("aturan", { ...v.aturan, abaikan_kapital: c })} />
                    <Centang label="Abaikan spasi berlebih" checked={v.aturan.abaikan_spasi} disabled={lock} onChange={(c) => set("aturan", { ...v.aturan, abaikan_spasi: c })} />
                    <Centang label="Abaikan tanda baca" checked={v.aturan.abaikan_tanda_baca} disabled={lock} onChange={(c) => set("aturan", { ...v.aturan, abaikan_tanda_baca: c })} />
                    <FormGroup className="mt-3">
                      <label>Kata kunci (opsional)</label>
                      <DaftarTeks nilai={v.kata_kunci} onChange={(x) => set("kata_kunci", x)} placeholder="Kata kunci" disabled={lock} />
                      <small className="text-muted d-block mt-1">Dipakai backend sebagai pembantu pemeriksaan; tidak tampil ke siswa.</small>
                    </FormGroup>
                    <FormField label="Rubrik / catatan pemeriksa (opsional)" name="rubrik" error={errors.rubrik}>
                      <Input id="rubrik" type="textarea" rows="3" maxLength={2000} value={v.rubrik} disabled={lock} onChange={(e) => set("rubrik", e.target.value)} />
                    </FormField>
                  </>
                )}
              </CardBody>
              <CardFooter>
                <Button type="submit" color="primary" className="btn-fill" disabled={lock || mengunggah}>{saving ? "Menyimpan..." : "Simpan"}</Button>
                <Button tag={Link} to="/admin/soal" color="secondary" className="ml-2" disabled={saving}>{terkunci ? "Kembali" : "Batal"}</Button>
              </CardFooter>
            </form>
          </Card>
        </Col>
      </Row>
    </div>
  );
}

export default SoalForm;
